  ui_story_5028_50280101_73_dialog_content = "¡Oye, estás ahí! ¡Sal aquí!",
  ui_story_5028_50280101_74_dialog_content = "¡Mira el lío que hiciste! ¿Por qué tuviste que obligarme a llevar a Kyllo contigo?",
  ui_story_5028_50280101_75_dialog_content = "Es más problema de lo que vale, ¡completamente inútil!",
