  ui_story_5028_50280101_82_dialog_content = "¡Es Fía! fia!!!",
  ui_story_5028_50280101_83_dialog_content = "¿Estas borracho? ¿Recuerdas tu propio nombre?",
  ui_story_5028_50280101_83X_dialog_content = "Esto es facil. El nombre es Vic.",
  ui_story_5028_50280101_83X1_dialog_content = "No me refería a eso...",
  ui_story_5028_50280101_84_dialog_content = "¡Vaya! Fia, has vuelto.",
  ui_story_5028_50280101_85_dialog_content = "Ahora recuerdo que fuiste a... Era...",
  ui_story_5028_50280101_86_dialog_content = "¿Recolectar estiércol de Linmaphant? ¿Fue eso?",
  ui_story_5028_50280101_87_dialog_content = "¿¡Quién querría estiércol de Linmaphant!?",
  ui_story_5028_50280101_88_dialog_content = "Fui a atrapar Pangalo.",
  ui_story_5028_50280101_89_dialog_content = "Por supuesto, la captura de Pangalo. ¿Y conseguiste uno?",
  ui_story_5028_50280101_90_dialog_content = "Oh, estaba tan cerca. ¡Pero adivina que!",
  ui_story_5028_50280101_91_dialog_content = "Kyllo no dejaba de fastidiarme. El Pangalo se escapó al final.",
  ui_story_5028_50280101_S91_dialog_content = "Ah, se escapó. Que desafortunado. Y, ¿por qué querías uno de nuevo? Recuerdame.",
  ui_story_5028_50280101_S92_dialog_content = "Así pude observar su comportamiento, duh! ¡Esa fue la tarea que me diste!",
  ui_story_5028_50280101_S93_dialog_content = "Vaya. Bueno, entonces puedes anotar esto en tu diario: \"Los pangalos son tímidos y temen a la gente\".",
  ui_story_5028_50280101_S94_dialog_content = "¿Qué, y eso es todo?",
  ui_story_5028_50280101_S95_dialog_content = "El resto vendrá con el tiempo. ¿Recuerdas lo que te dije? Estudiar bestias maravillosas comienza con respetarlas.",
  ui_story_5028_50280101_S96_dialog_content = "Respetando sus comportamientos y estados de ánimo extraños, y sus hábitats.",
  ui_story_5028_50280101_S97_dialog_content = "Estudiar, pero no interferir. Esa es la clave para convertirse en un extrozoólogo.",
  ui_story_5028_50280101_92_dialog_content = "Ese, Fia, es el camino hacia el conocimiento. Oh, tienes mucho que aprender.",
  ui_story_5028_50280101_93_dialog_content = "Oh, esto de nuevo. Sé que sé. Sabes que la gente llama a esto \"hacer alarde de tu antigüedad\", ¿verdad?",
  ui_story_5028_50280101_94_dialog_content = "¿Me estás llamando viejo?",
  ui_story_5028_50280101_X94_dialog_content = "Los hombres guapos como yo no envejecen. maduramos.",
  ui_story_5028_50280101_X95_dialog_content = "(Caramba, qué fanfarrón. ¿Por qué lo escucho?)",
  ui_story_5028_50280101_95_dialog_content = "Lo que no entiendo es por qué querías que llevara a Kyllo.",
  ui_story_5028_50280101_96_dialog_content = "Nosotros... No trabajamos bien juntos. No es el socio adecuado para mí.",
  ui_story_5028_50280101_97_dialog_content = "No puedo hacer nada cuando está ahí, y mucho menos convertirme en un <color=#FFB400>extrozoólogo</color>!",
  ui_story_5028_50280101_98_dialog_content = "Porque no puedes comunicarte con él, ¿verdad?",
  ui_story_5028_50280101_99_dialog_content = "...",
  ui_story_5028_50280101_100_dialog_content = "Sí.",
  ui_story_5028_50280101_102_dialog_content = "Tu habilidad para comunicarte con los animales es un regalo. Pero no sería prudente confiar demasiado en él.",
  ui_story_5028_50280101_103_dialog_content = "Por ejemplo, puedes entender aurorianos. Pero, ¿simplemente ser capaz de entender a todos significa que puedes ser amigo de ellos?",
  ui_story_5028_50280101_104_dialog_content = "Oh, lo siento. Lo olvidé, no tienes amigos.",
  ui_story_5028_50280101_105_dialog_content = "Tú-",
  ui_story_5028_50280101_106_dialog_content = "¡Tú tampoco tienes! ¡No actúes todo engreído!",
  ui_story_5028_50280101_107_dialog_content = "La amistad funciona de manera diferente para los adultos. No lo entenderías.",
  ui_story_5028_50280101_108_dialog_content = "Eh. Bueno, si los adultos hacen amigos pasando el rato en bares presumiendo todo el tiempo...",
  ui_story_5028_50280101_109_dialog_content = "E-Eso fue...",
  ui_story_5028_50280101_110_dialog_content = "¡Y luego hacer que su aprendiz pague la cuenta por ellos!",
  ui_story_5028_50280101_111_dialog_content = "¿Es eso lo que hacen todos los perdedores de mediana edad?",
  ui_story_5028_50280101_112_dialog_content = "¡Broke, desempleado, holgazaneando en casa todo el día!",
  ui_story_5028_50280101_113_dialog_content = "Bien, eso es suficiente! ¿Y quién es un perdedor de mediana edad?",
  ui_story_5028_50280101_S113_dialog_content = "¿Cómo llamas a alguien que depende de su aprendiz para sobrevivir?",
  ui_story_5028_50280101_S114_dialog_content = "Tengo que prepararte la comida de un día entero antes de salir. Luego, cuando regrese, tengo que limpiar el desastre que han dejado todos tus amiguitos corriendo.",
  ui_story_5028_50280101_S115_dialog_content = "¿Quizás le gustaría tratar de cuidar de sí mismo? Ya sabes, la adultez?",
  ui_story_5028_50280101_S116_dialog_content = "tu... tu...",
  ui_story_5028_50280101_114_dialog_content = "Sigo siendo tu mentor, ¿no? ¿No deberías hablar un poco más amablemente?",
  ui_story_5028_50280101_X114_dialog_content = "Bien, seré un poco más amable...",
  ui_story_5028_50280101_X115_dialog_content = "(¡No, espera! Fia, ¡tienes razón!)",
  ui_story_5028_50280101_X116_dialog_content = "(Y si muestra debilidad ahora, esto volverá a suceder).",
  ui_story_5028_50280101_X117_dialog_content = "(Necesito ser valiente. Sí, eso es todo. ¡Valiente!)",
  ui_story_5028_50280101_115_dialog_content = "¡Ni siquiera tomas mis lecciones en serio!",
  ui_story_5028_50280101_116_dialog_content = "Te quedas en casa y me envías a hacer recados solo.",
  ui_story_5028_50280101_117_dialog_content = "Y para colmo de males, ahora tengo que hacerlo con Kyllo frenándome.",
  ui_story_5028_50280101_118_dialog_content = "¡Al menos podrías explicar por qué!",
  ui_story_5028_50280101_119_dialog_content = "Bien bien. Entiendo que los niños luchan por controlar su temperamento.",
  ui_story_5028_50280101_120_dialog_content = "¿Alguna vez te has preguntado por qué puedes comunicarte con todos los animales excepto con este?",
  ui_story_5028_50280101_121_dialog_content = "Yo no...",
  ui_story_5028_50280101_122_dialog_content = "Porque Kyllo...",
  ui_story_5028_50280101_123_dialog_content = "Kyllo es un <color=#FFB400>exótico</color>!",
  ui_story_5028_50280101_124_dialog_content = "¿¡Exótico!?",
  ui_story_5028_50280101_125_dialog_content = "Lo?",
  ui_story_5028_50280101_126_dialog_content = "Las maravillosas bestias que estudiamos son las criaturas más raras y únicas de la naturaleza.",
  ui_story_5028_50280101_X126_dialog_content = "Su naturaleza única se deriva de las diferentes formas en que utilizan Lumina.",
  ui_story_5028_50280101_X127_dialog_content = "Pero los exóticos son los más raros entre las bestias maravillosas y tienen muchos más poderes.",
  ui_story_5028_50280101_127_dialog_content = "Entonces, ¿por qué parece un gran idiota?",
  ui_story_5028_50280101_128_dialog_content = "Porque, niño tonto, todavía es joven.",
  ui_story_5028_50280101_129_dialog_content = "Los exóticos deben sufrir un proceso de metamorfosis durante su crecimiento. yo lo llamo <color=#FFB400>\"evolución.\"</color>",
  ui_story_5028_50280101_130_dialog_content = "Y una vez que Kyllo evolucione, será más poderoso de lo que puedas imaginar.",
  ui_story_5028_50280101_131_dialog_content = "¿Tu quieres dinero? Convertirá las rocas en oro.",
  ui_story_5028_50280101_132_dialog_content = "¿Quieres fuerza? Destruirá ejércitos y arrasará Lumopolis, sin siquiera sudar.",
  ui_story_5028_50280101_133_dialog_content = "¿Quieres poder? El miedo que inspira Kyllo hará que incluso la Reina del Norte incline la cabeza.",
  ui_story_5028_50280101_134_dialog_content = "¡Vaya, dártelo fue un gran sacrificio de mi parte!",
  ui_story_5028_50280101_135_dialog_content = "Pero, ¿qué puedo decir? Tal altruismo está en mi naturaleza.",
  ui_story_5028_50280101_136_dialog_content = "...",
  ui_story_5028_50280101_137_dialog_content = "Estás fanfarroneando de nuevo.",
  ui_story_5028_50280101_138_dialog_content = "¿Qué? ¿Cómo puedes decir tal cosa?",
  ui_story_5028_50280101_139_dialog_content = "Lo he escuchado tantas veces.",
  ui_story_5028_50280101_140_dialog_content = "El año pasado dijiste que ibas a comprar un dirigible y llevarme de vacaciones.",
  ui_story_5028_50280101_141_dialog_content = "Empaqué mis maletas y esperé y esperé. ¿Y qué obtuve? Globos!",
  ui_story_5028_50280101_142_dialog_content = "Bueno... porque no sabía que los dirigibles eran tan caros...",
  ui_story_5028_50280101_143_dialog_content = "Luego, en invierno, me dijiste que tenía que aprender todo sobre Thornpoises para un tema importante.",
  ui_story_5028_50280101_144_dialog_content = "Me tomó tres días encontrar uno. Luego toda una tarde para atraparlo.",
  ui_story_5028_50280101_145_dialog_content = "¿Y que pasó? ¡Lo usaste para fregar tus zapatos!",
  ui_story_5028_50280101_146_dialog_content = "Ah bueno, eso...",
  ui_story_5028_50280101_147_dialog_content = "Y según tú, no solo eres aparentemente un noble, ¡también eres un cantante famoso que solo fue capaz de estudiar bestias maravillosas después de engañar a miles de fanáticos fanáticos!",
  ui_story_5028_50280101_148_dialog_content = "¡Pero todo es falso! ¡Nada más que mentiras!",
  ui_story_5028_50280101_149_dialog_content = "¡Apuesto a que estás mintiendo esta vez también!",
  ui_story_5028_50280101_X149_dialog_content = "(¡Es enloquecedor! Trabajo muy duro y él solo... Él solo...)",
  ui_story_5028_50280101_X150_dialog_content = "Fía, espera un momento.",
  ui_story_5028_50280101_150_dialog_content = "<size=50>¡Quiero tanto ser extrozoólogo!</size>",
  ui_story_5028_50280101_151_dialog_content = "Pero no estoy aprendiendo nada, y en lugar de eso, me cargan con un holgazán...",
  ui_story_5028_50280101_152_dialog_content = "¡Estaría mejor solo!",
  ui_story_5028_50280101_153_dialog_content = "...",
  ui_story_5028_50280101_154_dialog_content = "Ahora lo entiendo.",
  ui_story_5028_50280101_155_dialog_content = "¿Entonces crees que no tengo nada más que enseñarte?",
  ui_story_5028_50280101_156_dialog_content = "Ah, um ...",
  ui_story_5028_50280101_157_dialog_content = "Usted está dotado. Y tal vez mi pedagogía esté un poco anticuada.",
  ui_story_5028_50280101_158_dialog_content = "Pero pensé que te estaba entrenando para ser un extrozoólogo competente.",
  ui_story_5028_50280101_159_dialog_content = "Te pedí que intentaras cosas por tu cuenta porque la experiencia práctica es vital.",
  ui_story_5028_50280101_160_dialog_content = "Esperaba que desarrollara habilidades independientes para resolver problemas.",
  ui_story_5028_50280101_161_dialog_content = "Pero ahora veo que lo entendí todo mal.",
  ui_story_5028_50280101_162_dialog_content = "Quiero decir, yo no estaba...",
  ui_story_5028_50280101_163_dialog_content = "Es verdad. Eres un genio que es capaz de comunicarse con los animales. No necesitas educación superflua.",
  ui_story_5028_50280101_164_dialog_content = "Creo que es hora de terminar tu aprendizaje.",
  ui_story_5028_50280101_165_dialog_content = "¿¡Qué!?",
  ui_story_5028_50280101_166_dialog_content = "Ya no tienes necesidad de mis enseñanzas.",
  ui_story_5028_50280101_167_dialog_content = "Pero... Eso no es lo que quise decir...",
  ui_story_5028_50280101_168_dialog_content = "Kyllo puede acompañarte en tu graduación.",
  ui_story_5028_50280101_169_dialog_content = "Lo?",
  ui_story_5028_50280101_170_dialog_content = "¿Eh?",
  ui_story_5028_50280101_171_dialog_content = "Finalmente, espero sinceramente que seas capaz de realizar tus sueños.",
  ui_story_5028_50280101_172_dialog_content = "Te daré a Kyllo, este exótico, como regalo de despedida.",
  ui_story_5028_50280101_173_dialog_content = "Si puedes ayudarlo a evolucionar, significará que eres digno del nombre de extrozoólogo.",
  ui_story_5028_50280101_174_dialog_content = "Que esa sea mi última lección para ti.",
  ui_story_5028_50280101_175_dialog_content = "Maestro...",
  ui_story_5028_50280101_176_dialog_content = "Ay, no llores. Pensé que siempre quisiste ser extrozoólogo.",
  ui_story_5028_50280101_177_dialog_content = "Simplemente ayude a Kyllo a evolucionar y regrese aquí para terminar formalmente su aprendizaje. Hecho. Sueño logrado.",
  ui_story_5028_50280101_178_dialog_content = "Y en cuanto a mí, el mentor que tanto te falta... Déjame morir solo de vejez.",
  ui_story_5028_50280101_179_dialog_content = "Maestro, usted...",
  ui_story_5028_50280101_180_dialog_content = "Todavía no me has dicho cómo ayudar a Kyllo a evolucionar.",
  ui_story_5028_50280101_181_dialog_content = "...",
  ui_story_5028_50280101_182_dialog_content = "Oh, ¿eso es lo que te preocupa?",
  ui_story_5028_50280101_183_dialog_content = "¿Qué creías que me preocupaba?",
  ui_story_5028_50280101_184_dialog_content = "¿Porque quieres convertirte en extrozoólogo?",
  ui_story_5028_50280101_185_dialog_content = "¡Sí! Es mi sueño.",
  ui_story_5028_50280101_186_dialog_content = "¿N-No hay nada más que quieras decirme?",
  ui_story_5028_50280101_187_dialog_content = "¡Oh, tengo algo que decir!",
  ui_story_5028_50280101_188_dialog_content = "No me estás mintiendo otra vez, ¿verdad?",
  ui_story_5028_50280101_189_dialog_content = "Tú-",
  ui_story_5028_50280101_190_dialog_content = "¿Estás seguro de que sabes algo sobre la evolución exótica?",
  ui_story_5028_50280101_191_dialog_content = "¿Es incluso una cosa real?",
  ui_story_5028_50280101_192_dialog_content = "¡Por supuesto que existe tal cosa!",
  ui_story_5028_50280101_193_dialog_content = "¿Cuándo te he mentido?",
  ui_story_5028_50280101_194_dialog_content = "...",
  ui_story_5028_50280101_195_dialog_content = "Está bien, bueno, esta vez estoy siendo honesto.",
  ui_story_5028_50280101_196_dialog_content = "Pero evolucionar exóticos es un desafío. No tengo ningún método seguro.",
  ui_story_5028_50280101_197_dialog_content = "Aquí, toma mis notas.",
  ui_story_5028_50280101_198_dialog_content = "¡Whoa!",
  ui_story_5028_50280101_199_dialog_content = "He escrito algunos ensayos cuidadosamente diseñados.",
  ui_story_5028_50280101_200_dialog_content = "Tenga esto en cuenta: la experiencia práctica es lo más importante.",
  ui_story_5028_50280101_201_dialog_content = "Si completa estas pruebas, puede evolucionar el Kyllo.",
  ui_story_5028_50280101_202_dialog_content = "Cree en ti mismo y un día te convertirás en—",
  ui_story_5028_50280101_203_dialog_content = "Agradable. ¡Gracias, Maestro!",
  ui_story_5028_50280101_204_dialog_content = "¡Me voy entonces! ¡Adiós!",
  ui_story_5028_50280101_205_dialog_content = "¡Aférrate! no he terminado...",
  ui_story_5028_50280101_206_dialog_content = "<color=#e8d9bb>¡Golpe!</color>",
  ui_story_5028_50280101_207_dialog_content = "Extrozoólogo...",
  ui_story_5028_50280101_208_dialog_content = "¿Realmente puedes evolucionar, Kyllo?",
  ui_story_5028_50280101_209_dialog_content = "¡Lo!",
  ui_story_5028_50280101_210_dialog_content = "Está bien, veamos qué pruebas me ha dado ese maestro mío inútil.",
  ui_story_5028_50280101_211_dialog_content = "\"Sobre la evolución de los exóticos\"",
  ui_story_5028_50280101_212_dialog_content = "\"Descargo de responsabilidad: este ensayo fue diseñado en base a las propias experiencias del autor\".",
  ui_story_5028_50280101_213_dialog_content = "\"Solo deben servir como sugerencias. Los resultados no están garantizados\".",
  ui_story_5028_50280101_214_dialog_content = "Caray. Solo estoy en la página uno y ya está eludiendo la responsabilidad.",
  ui_story_5028_50280101_215_dialog_content = "Pero... 1, 2, 3, 4... hay muchas pruebas por las que pasar.",
  ui_story_5028_50280101_216_dialog_content = "\"Prueba 1: Atrapa y hazte amigo de un <color=#FFB400>caelestita</color>.\"",
  ui_story_5028_50280101_217_dialog_content = "¿Una Caelestita? Me pregunto qué clase de animal es ese.",
  ui_story_5028_50280201_1_dialog_content = "Prueba: Atrapa una caelestita",
  ui_story_5028_50280201_2_dialog_content = "PlayerName, cuando podemos empezar a jugar?",
  ui_story_5028_50280201_3_dialog_content = "Aférrate. Muy pronto.",
  ui_story_5028_50280201_4_dialog_content = "¿Por qué no ahora? ¡No puedo esperar!",
  ui_story_5028_50280201_5_dialog_content = "Porque necesitamos espacio. En algún lugar con una gran área de terreno plano.",
  ui_story_5028_50280201_6_dialog_content = "Pero este lugar está lleno de obstáculos, así que no podemos jugar aquí.",
  ui_story_5028_50280201_7_dialog_content = "Ya veo.",
  ui_story_5028_50280201_8_dialog_content = "Entonces, ¿podemos caminar más rápido?",
  ui_story_5028_50280201_9_dialog_content = "Tienes tanta prisa, jaja. Está bien, está bien, vamos a movernos.",
  ui_story_5028_50280201_10_dialog_content = "<color=#e8d9bb>Ruido... Ruido...</color>",
  ui_story_5028_50280201_11_dialog_content = "Bien, ahora voy a lanzar la pelota en tu dirección. Usa ese bate que estás sosteniendo para golpearlo.",
  ui_story_5028_50280201_12_dialog_content = "RubyLe gusta estudiar culturas antiguas y ya me contó todo sobre este juego.",
  ui_story_5028_50280201_13_dialog_content = "Básicamente, cuanto más lejos golpees la pelota, mejor.",
  ui_story_5028_50280201_14_dialog_content = "¿Entendido?",
  ui_story_5028_50280201_15_dialog_content = "¡Entiendo! Golpea la pelota con el bate.",
  ui_story_5028_50280201_16_dialog_content = "¡De acuerdo! Hagamos un intento.",
  ui_story_5028_50280201_17_dialog_content = "3, 2, 1!",
  ui_story_5028_50280201_18_dialog_content = "¡Golpealo!",
  ui_story_5028_50280201_19_dialog_content = "<color=#e8d9bb>¡Whoosh!</color>",
  ui_story_5028_50280201_20_dialog_content = "Oye, ¿por qué esquivaste?",
  ui_story_5028_50280201_21_dialog_content = "PlayerName, ¿por qué me atacaste?",
  ui_story_5028_50280201_22_dialog_content = "Eso no fue un ataque. Se llama lanzamiento.",
  ui_story_5028_50280201_23_dialog_content = "¿Cabeceo?",
  ui_story_5028_50280201_24_dialog_content = "Sí. Te tiro la pelota. Lo golpeas en el aire con el bate. Así es como funciona el juego.",
  ui_story_5028_50280201_25_dialog_content = "Está bien, lo tengo ahora. Hagámoslo de nuevo.",
  ui_story_5028_50280201_26_dialog_content = "Enfriar. Y no te preocupes si te lo pierdes. Eso es normal al principio.",
  ui_story_5028_50280201_27_dialog_content = "Está bien.",
  ui_story_5028_50280201_28_dialog_content = "¡Prepararse! 3, 2, 1—",
  ui_story_5028_50280201_29_dialog_content = "¡Golpealo!",
  ui_story_5028_50280201_30_dialog_content = "<color=#e8d9bb>¡Whoosh!</color>",
  ui_story_5028_50280201_31_dialog_content = "<color=#e8d9bb>¡¡¡Estallido!!!</color>",
  ui_story_5028_50280201_32_dialog_content = "¡Oh, vaya! Lo golpeaste!!!",
  ui_story_5028_50280201_33_dialog_content = "¡Hurra! ¡Lo hice!",
  ui_story_5028_50280201_34_dialog_content = "¡La pelota se fue tan lejos!",
  ui_story_5028_50280201_35_dialog_content = "¡Sí! ¡Eso es lo que llamaban un \"jonrón\" en el pasado!",
  ui_story_5028_50280201_36_dialog_content = "Oye, Revy, tal vez eres un natural en esto!",
  ui_story_5028_50280201_37_dialog_content = "¿Yo? ¿Natural?",
  ui_story_5028_50280201_38_dialog_content = "¡Sí! Eso fue increíble para un primer swing.",
  ui_story_5028_50280201_39_dialog_content = "Golpear la pelota es divertido.",
  ui_story_5028_50280201_40_dialog_content = "Entonces, ¿qué sucede después?",
  ui_story_5028_50280201_41_dialog_content = "Próximo...",
  ui_story_5028_50280201_42_dialog_content = "Er, creo que tenemos que recuperar la pelota.",
  ui_story_5028_50280201_43_dialog_content = "Guau, esto podría tomar un tiempo. Realmente fue lejos.",
  ui_story_5028_50280201_44_dialog_content = "Lo siento. La próxima vez, seré más amable.",
  ui_story_5028_50280201_45_dialog_content = "No hagas eso. No es tu culpa. Las reglas dicen que tienes que golpearlo lo más lejos posible.",
  ui_story_5028_50280201_46_dialog_content = "Entonces... Voy a buscar la pelota. Corro más rápido.",
  ui_story_5028_50280201_47_dialog_content = "Se ha ido por más de cinco minutos, ¿por qué no ha vuelto todavía?",
  ui_story_5028_50280201_48_dialog_content = "<color=#e8d9bb>Crujido...</color>",
  ui_story_5028_50280201_49_dialog_content = "¿Quizás no puede encontrar la pelota? ¿O le ha pasado algo?",
  ui_story_5028_50280201_50_dialog_content = "creo que recuerdo Vice diciendo que los eclipses habían aparecido por aquí.",
  ui_story_5028_50280201_51_dialog_content = "<color=#e8d9bb>Ruido... Ruido...</color>",
  ui_story_5028_50280201_52_dialog_content = "Aunque un Eclipsite ordinario no sería un desafío para Revy.",
  ui_story_5028_50280201_53_dialog_content = "Después de todo, ella es Rev—",
  ui_story_5028_50280201_54_dialog_content = "¡Ahora!",
  ui_story_5028_50280201_55_dialog_content = "¡¿Una red?!",
  ui_story_5028_50280201_56_dialog_content = "¡Kyllo, idiota! Te perdiste de nuevo.",
  ui_story_5028_50280201_57_dialog_content = "Bien, nos quedamos sin opciones. ¡Cobrar!",
  ui_story_5028_50280201_58_dialog_content = "¡¿Quién en el mundo eres tú?! Te lo advierto, no soy alguien con quien quieras meterte.",
  ui_story_5028_50280201_59_dialog_content = "¡Y esa Auroriana que acaba de estar aquí aplasta cabezas de Eclipsite con sus propias manos como si fueran sandías!",
  ui_story_5028_50280201_60_dialog_content = "Acércate más y usaré mis habilidades psíquicas para pedir ayuda.",
  ui_story_5028_50280201_61_dialog_content = "¿Habilidades psíquicas? ¡Realmente eres un Caelestite!",
  ui_story_5028_50280201_62_dialog_content = "¡Tenemos que evitar que pida ayuda!",
  ui_story_5028_50280201_63_dialog_content = "¡Kyllo, plan B! ¡Ahora!",
  ui_story_5028_50280201_64_dialog_content = "¡Lo!",
  ui_story_5028_50280201_65_dialog_content = "¡Esperar! ¿Qué es el Plan B?",
  ui_story_5028_50280201_66_dialog_content = "Lo digo en serio. Da un paso más y pediré ayuda.",
  ui_story_5028_50280201_67_dialog_content = "Vamos-",
  ui_story_5028_50280201_68_option_content = "Fuerza—¡Ay!",
  ui_story_5028_50280201_69_dialog_content = "¡Eso duele!",
  ui_story_5028_50280201_70_dialog_content = "¡Lo, lo, lo!",
  ui_story_5028_50280201_71_dialog_content = "Buen trabajo, Kyllo. Vale, retírate por el bosque como estaba previsto.",
  ui_story_5028_50280201_72_dialog_content = "¡Lo, lo!",
  ui_story_5028_50280201_73_dialog_content = "¡P-Bájame! ¡¿A dónde me llevas?!",
  ui_story_5028_50280201_74_dialog_content = "<anim type=Shake><size=45>Revy-Rvdo-!</size></anim>",
  ui_story_5028_50280201_76_dialog_content = "Ya estoy de vuelta. Confundí un conejo con la pelota y pasé años persiguiéndolo.",
  ui_story_5028_50280201_77_dialog_content = "¿eh? donde esta PlayerName?",
  ui_story_5028_50280201_78_dialog_content = "El bate sigue aquí. ¡Oh, lo sé! PlayerName debe querer que practique batear jonrones.",
  ui_story_5028_50280201_79_dialog_content = "¡No te decepcionaré! Primero, 1000 swings de práctica. Listo... ¡adelante!",
  ui_story_5028_50280201_80_dialog_content = "¡Lo!",
  ui_story_5028_50280201_81_dialog_content = "Espera, espera, ¿adónde me lleva esta cosita rara?",
  ui_story_5028_50280201_82_dialog_content = "Solo bájame. ¡Estoy en agonía aquí! Creo que me rompiste la espalda.",
  ui_story_5028_50280201_83_dialog_content = "Lo?",
  ui_story_5028_50280201_84_dialog_content = "¡Kyllo, espera!",
  ui_story_5028_50280201_85_dialog_content = "Uf... ¿Finalmente has decidido parar? Ay, ay, ay.",
  ui_story_5028_50280201_86_dialog_content = "Kyllo, ¿era esta la ruta que planeamos para el Plan B?",
  ui_story_5028_50280201_87_dialog_content = "Lo lo?",
  ui_story_5028_50280201_88_dialog_content = "No me digas que acabas de correr hacia el bosque al azar...",
  ui_story_5028_50280201_89_dialog_content = "Lo...",
  ui_story_5028_50280201_90_dialog_content = "No hay señales del camino por el que entramos... todo son solo... árboles.",
  ui_story_5028_50280201_91_dialog_content = "¡Ustedes están locos! ¿Sabes que este lugar está lleno de eclipses?",
  ui_story_5028_50280201_92_dialog_content = "¿Eclipsites?",
  ui_story_5028_50280201_93_dialog_content = "¡Gahhhhhh!",
  ui_story_5028_50280201_94_dialog_content = "¡Mira, en realidad apareció uno!",
  ui_story_5028_50280201_95_dialog_content = "Por qué habría... ¡¡¡Es un eclipse!!!",
  ui_story_5028_50280201_96_dialog_content = "¡No te quedes ahí parado! ¡Correr!",
  ui_story_5028_50280201_97_dialog_content = "¡Graagh!",
  ui_story_5028_50280201_98_dialog_content = "Kyllo!",
  ui_story_5028_50280201_99_dialog_content = "¡Lo!",
  ui_story_5028_50280201_100_dialog_content = "¿Un eclipse? ¿Cómo puede haber eclipses aquí?",
  ui_story_5028_50280201_101_dialog_content = "¡Deja de pensar y corre!",
  ui_story_5028_50280201_102_dialog_content = "Ugh no, realmente no puedo correr mucho más...",
  ui_story_5028_50280201_103_dialog_content = "Soy bueno hablando con bestias maravillosas. ¿Pero eclipses y todo eso? ¡Puaj!",
  ui_story_5028_50280201_104_dialog_content = "Sin embargo, todavía no puedo ser devorado por un Eclipsite. ¡Tengo que convertirme en un extrozoólogo primero!",
  ui_story_5028_50280201_105_dialog_content = "Piensa, piensa, tiene que haber una manera...",
  ui_story_5028_50280201_106_dialog_content = "¿Qué solía decir el Maestro? Ante el peligro, no llores. Pensar.",
  ui_story_5028_50280201_107_dialog_content = "Tal vez debería ganar algo de tiempo para que Kyllo y Caelestite se escapen.",
  ui_story_5028_50280201_108_dialog_content = "Pero no sé si soy lo suficientemente fuerte... Lo que sea, ¡tendré que serlo! No puedo retenerlos.",
  ui_story_5028_50280201_109_dialog_content = "Relájate, ¿quieres? ¿Sabes siquiera pelear?",
  ui_story_5028_50280201_110_dialog_content = "*Sollozo* Un poco. Pero solo para defensa propia, sobre todo.",
  ui_story_5028_50280201_111_dialog_content = "¡Está bien! Los enemigos al comienzo de una aventura siempre son más débiles.",
  ui_story_5028_50280201_112_dialog_content = "Destino. Eso es todo lo que es el destino.",
  ui_story_5028_50280201_113_dialog_content = "¡Usaré mis poderes para ayudarte!",
  ui_story_5028_50280201_114_dialog_content = "Si seguimos corriendo por el bosque, atraeremos más eclipses.",
  ui_story_5028_50280201_114X_dialog_content = "Deberíamos ocuparnos de estos siguiéndonos y luego decidir qué hacer.",
  ui_story_5028_50280201_115_dialog_content = "Pero hay tantos...",
  ui_story_5028_50280201_116_dialog_content = "¡Confía en mí!",
  ui_story_5028_50280201_117_dialog_content = "¡Y no estamos solos! Ahí está tu amigo también. ¡Si trabajamos juntos podemos vencerlos!",
  ui_story_5028_50280201_118_dialog_content = "¡Lo!",
  ui_story_5028_50280201_119_dialog_content = "*Olfatea* Está bien entonces.",
  ui_story_5028_50280201_120_dialog_content = "Por cierto, ¡deberías mostrar algo de respeto! Soy el mejor extrozoólogo del mundo, ¿sabes?",
  ui_story_5028_50280201_121_dialog_content = "¿Cómo se atreven a intentar asustarme apestosos Eclipsitas?",
  ui_story_5028_50280201_122_dialog_content = "¡Forma fila y prepárate para una paliza!",
  ui_story_5028_50280202_1_dialog_content = "Guau. ¡En realidad ganamos!",
  ui_story_5028_50280202_2_dialog_content = "¡Impresionante! Kyllo, ¿viste eso?",
  ui_story_5028_50280202_3_dialog_content = "¡Lo! ¡Lo!",
  ui_story_5028_50280202_4_dialog_content = "Jejeje. No esperaba que fueras tan buen luchador, Kyllo. ¡Estoy impresionado!",
  ui_story_5028_50280202_5_dialog_content = "¡Lo!",
  ui_story_5028_50280202_6_dialog_content = "(Debería escabullirme mientras ellos están ocupados felicitándose).",
  ui_story_5028_50280202_7_dialog_content = "Oh y...",
  ui_story_5028_50280202_8_dialog_content = "(Pero todavía hay eclipses por ahí. No estoy más seguro si me voy).",
  ui_story_5028_50280202_9_dialog_content = "(*Suspiro*)",
  ui_story_5028_50280202_10_dialog_content = "¿Eh, señor Caelestite?",
  ui_story_5028_50280202_11_dialog_content = "Aquí estoy.",
  ui_story_5028_50280202_12_dialog_content = "Gracias... por ayudarnos a Kyllo ya mí.",
  ui_story_5028_50280202_13_dialog_content = "Ah, no lo menciones. No fue nada.",
  ui_story_5028_50280202_14_dialog_content = "No hay absolutamente ninguna necesidad de agradecerme. Sabes qué, ¿por qué no los dejo a ambos aquí? Solo te detendré.",
  ui_story_5028_50280202_15_dialog_content = "No puede simplemente irse, Sr. Caelestite.",
  ui_story_5028_50280202_16_dialog_content = "No después de verme en tal desorden.",
  ui_story_5028_50280202_17_dialog_content = "¿Q-qué pasó justo ahora? ¿Donde está esto? Oh, he perdido la memoria.",
  ui_story_5028_50280202_18_dialog_content = "Y fingir amnesia no funcionará.",
  ui_story_5028_50280202_19_dialog_content = "Sé un buen chico y conviértete en mi compañero y mascota, como Kyllo aquí. Quédate, ayuda.",
  ui_story_5028_50280202_20_dialog_content = "(Jejeje. Y mostrando mi sonrisa más dulce, atrapo a la Caelestite.)",
  ui_story_5028_50280202_21_dialog_content = "¡De ninguna manera! Me niego.",
  ui_story_5028_50280202_22_dialog_content = "¡¿Eh?!",
  ui_story_5028_50280202_23_dialog_content = "Te ayudé justo ahora porque era lo correcto. Eso no me convierte en tu sirviente.",
  ui_story_5028_50280202_24_dialog_content = "Y todavía tenemos que discutir la forma en que esta bestia Kyllo me derribó y me secuestró.",
  ui_story_5028_50280202_25_dialog_content = "¿Por qué no nos ayudamos unos a otros a salir de este bosque primero? Entonces lo llamaremos parejo e iremos por caminos separados.",
  ui_story_5028_50280202_26_dialog_content = "*lloriqueo*",
  ui_story_5028_50280202_27_dialog_content = "(¿Fue demasiado duro?)",
  ui_story_5028_50280202_28_dialog_content = "(No, no lo fue. La chica probablemente está tratando de engañarme. Y tampoco confío en ese Kyllo).",
  ui_story_5028_50280202_29_dialog_content = "*Sollozo*",
  ui_story_5028_50280202_30_dialog_content = "Pero yo solo... solo quería un amigo...",
  ui_story_5028_50280202_31_dialog_content = "Lo...",
  ui_story_5028_50280202_32_dialog_content = "Todo el mundo dice que solo puedo entablar amistad con bestias maravillosas. Quería demostrar que eso no era cierto y que también puedo entablar amistad con Aurorains y Caelestites.",
  ui_story_5028_50280202_33_dialog_content = "Solo quiero cumplir el último deseo de mi Maestro...",
  ui_story_5028_50280202_34_dialog_content = "(¿Su maestro? ¿El que acaba de mencionar? ¿Y su último deseo? ¿Está muerto?)",
  ui_story_5028_50280202_35_dialog_content = "¡Achuu!",
  ui_story_5028_50280202_36_dialog_content = "Estoy bien, pequeña bola de pelo. Tal vez me estoy resfriando.",
  ui_story_5028_50280202_37_dialog_content = "¿Estás preocupado por mí? Entonces déjame usarte para limpiarme la nariz, ¿quieres?",
  ui_story_5028_50280202_38_dialog_content = "Ja ja. Por supuesto que estaba bromeando. Tengo que mantenerte limpio para vender tu piel mudada a los clientes.",
  ui_story_5028_50280202_39_dialog_content = "(Ella realmente no va a llorar, ¿verdad? Sus ojos están todos rojos).",
  ui_story_5028_50280202_40_dialog_content = "(Se ve incluso más joven que Revy y ella no es buena peleando.)",
  ui_story_5028_50280202_40X_dialog_content = "(La vida en el camino debe ser difícil para ella).",
  ui_story_5028_50280202_41_dialog_content = "Por eso te secuestré. Para que podamos ser amigos.",
  ui_story_5028_50280202_42_dialog_content = "(No llores. No llores. Hagas lo que hagas, no llores.)",
  ui_story_5028_50280202_43_dialog_content = "Lo siento mucho por haberte hecho todas esas cosas terribles. Realmente lo lamento.",
  ui_story_5028_50280202_44_dialog_content = "Si realmente me odia, Sr. Caelestite, déjeme aquí solo...",
  ui_story_5028_50280202_45_dialog_content = "Sólo déjame aquí para morir...",
  ui_story_5028_50280202_46_dialog_content = "Waaaaaaaaaaaaaaaaaaaaah!",
  ui_story_5028_50280202_47_dialog_content = "¡Lo siento lo siento!",
  ui_story_5028_50280202_48_dialog_content = "Lo siento, no debí haber sido tan malo contigo.",
  ui_story_5028_50280202_49_dialog_content = "Querías que seamos amigos, ¿verdad? ¡Cosa segura! estoy PlayerName.",
  ui_story_5028_50280202_50_dialog_content = "¿R-en serio? ¡Soy Fía!",
  ui_story_5028_50280202_51_dialog_content = "Está bien, Fia, entonces somos amigos.",
  ui_story_5028_50280202_52_dialog_content = "¿En serio?",
  ui_story_5028_50280202_53_dialog_content = "¡En realidad! Lo juro.",
  ui_story_5028_50280202_54_dialog_content = "¡Lo!",
  ui_story_5028_50280202_55_dialog_content = "Jejeje... Oye, PlayerName, esto te convierte en mi primer amigo.",
  ui_story_5028_50280202_56_dialog_content = "¡Estoy tan feliz de que seas mi amigo!",
  ui_story_5028_50280202_57_dialog_content = "¡Mira, Maestro! ¡Hice un amigo!",
  ui_story_5028_50280202_58_dialog_content = "¡Lo, lo!",
  ui_story_5028_50280202_59_dialog_content = "(¡Caray! Primero soy víctima de las lágrimas, ¡ahora es la sonrisa!)",
  ui_story_5028_50280202_60_dialog_content = "(¿Estaba tan sola como yo cuando estaba solo? No, al menos tenía a Soroz).",
  ui_story_5028_50280202_61_dialog_content = "(Aunque ella tiene este animal Kyllo.)",
  ui_story_5028_50280202_62_dialog_content = "(De todos modos, incluso si está actuando, no puedo dejar sola a una niña sollozante aquí).",
  ui_story_5028_50280202_63_dialog_content = "PlayerName, PlayerName, ¿Qué estás pensando?",
  ui_story_5028_50280202_64_dialog_content = "Oh nada. Solo que deberíamos regresar para poder llevarte a casa en el Coloso.",
  ui_story_5028_50280202_65_dialog_content = "¡Oh sí! Olvidé que Caelestites tiene Colossi.",
  ui_story_5028_50280202_66_dialog_content = "Podremos viajar en Colossus en lugar de caminar. ¡Podré completar las pruebas de mi Maestro en poco tiempo!",
  ui_story_5028_50280202_67_dialog_content = "Vamos, PlayerName, ¡vamos ya!",
  ui_story_5028_50280202_68_dialog_content = "¿Eh? ¿Qué juicios? Y suelta mi mano.",
  ui_story_5028_50280202_69_dialog_content = "¡Ay! ¡Deja de tirarme, todavía me duele la espalda!",
  ui_story_5028_50280202_70_dialog_content = "Y necesito dejar Revy saber lo que está pasando! ¡Oye!",
  ui_story_5028_50280202_71_dialog_content = "998... ¡Ja! 999... ¡Ja!",
  ui_story_5028_50280202_72_dialog_content = "1.000... ¡Ja!",
  ui_story_5028_50280202_73_dialog_content = "¿Cómo es que Navigator todavía no ha vuelto? He terminado la práctica.",
  ui_story_5028_50280202_74_dialog_content = "¿Quizás ha vuelto al Coloso? Déjame ir a comprobar.",
  ui_story_5028_50280202_75_dialog_content = "¿Eh?",
  ui_story_5028_50280202_76_dialog_content = "¿Dónde está el coloso?",
  ui_story_5028_50280202_77_dialog_content = "y donde esta PlayerName?",
  ui_story_5028_50280202_78_dialog_content = "¿Eh?",
  ui_story_5028_50280202_79_dialog_content = "¿Y qué diablos es esto?",
  ui_story_5028_50280301_1_dialog_content = "Prueba: incubar un huevo Drakolion",
  ui_story_5028_50280301_2_dialog_content = "los <color=#FFB400>Drakolion</color> tiene la cabeza de un dragón feroz.",
  ui_story_5028_50280301_3_dialog_content = "También tiene el cuerpo de un poderoso león y las alas de una majestuosa águila.",
  ui_story_5028_50280301_4_dialog_content = "Un solo latigazo de su poderosa cola es capaz de derribar a un rinoceronte.",
  ui_story_5028_50280301_5_dialog_content = "Pero lo más aterrador de todo son sus piernas musculosas.",
  ui_story_5028_50280301_5X_dialog_content = "Un Drakolion puede atrapar y someter a cualquier presa, incluso en tierra.",
  ui_story_5028_50280301_6_dialog_content = "Pero, afortunadamente, prefieren permanecer en el aire a cargar en tierra.",
  ui_story_5028_50280301_6X_dialog_content = "Son muy raramente vistos.",
  ui_story_5028_50280301_7_dialog_content = "los <color=#FFB400>exótico</color> Drakolion resulta ser el objetivo de este juicio.",
  ui_story_5028_50280301_8_dialog_content = "Oye, Fia, ¿de qué estás murmurando?",
  ui_story_5028_50280301_9_dialog_content = "Eso parece un libro genial. ¿Puedo ver?",
  ui_story_5028_50280301_10_dialog_content = "¡Shhh!",
  ui_story_5028_50280301_11_dialog_content = "¡Honestamente! Estoy tratando de hacer una narración aquí. No interrumpas.",
  ui_story_5028_50280301_12_dialog_content = "¡Lo!",
  ui_story_5028_50280301_13_dialog_content = "¿Qué quieres decir con una narración? Somos los únicos aquí.",
  ui_story_5028_50280301_14_dialog_content = "¿Para qué necesitamos una narración?",
  ui_story_5028_50280301_15_dialog_content = "Ja, porque hay ciertos procedimientos a seguir en este campo de trabajo, eso es todo.",
  ui_story_5028_50280301_16_dialog_content = "Antes de enfrentarse a una bestia maravillosa, es importante recitar todo lo que sabe sobre ella.",
  ui_story_5028_50280301_17_dialog_content = "Particularmente cuando se trata de una bestia maravillosa como el Drakolion, tienes que hacer toda la investigación que puedas sobre sus hábitats.",
  ui_story_5028_50280301_18_dialog_content = "Además, le da a todo el ambiente una sensación de ritual, lo que te ayuda a mantener la calma en caso de emergencia.",
  ui_story_5028_50280301_19_dialog_content = "¡Lo, lo!",
  ui_story_5028_50280301_20_dialog_content = "... Sinceramente, me preocupa más que la verdadera razón por la que te recitas a ti mismo es que no tienes idea de lo que estás haciendo.",
  ui_story_5028_50280301_21_dialog_content = "Ja. Relájate, he hecho mi investigación. Estoy absolutamente seguro de que encontraremos un Drakolion.",
  ui_story_5028_50280301_22_dialog_content = "Las alas de un águila majestuosa...",
  ui_story_5028_50280301_23_dialog_content = "Ya dijiste esa parte, no creo que necesites repasarla otra vez...",
  ui_story_5028_50280301_24_dialog_content = "¡Ay callaos! Por favor, deja de interrumpirme.",
  ui_story_5028_50280301_25_dialog_content = "Ya es bastante difícil tener que descifrar la letra atroz del Maestro. Es como si sumergiera un gusano en tinta y lo soltara en la página.",
  ui_story_5028_50280301_26_dialog_content = "Vaya. ¿Entonces heredaste ese cuaderno de tu maestro?",
  ui_story_5028_50280301_27_dialog_content = "¿Heredado? Escucha, ¿podrías quedarte callado? Estoy llegando a la parte importante.",
  ui_story_5028_50280301_28_dialog_content = "Los Drakolions son bestias extrañas, con un profundo amor por el cielo.",
  ui_story_5028_50280301_29_dialog_content = "Son reacios a aterrizar incluso cuando ponen huevos a menos que haya una amenaza para sus crías.",
  ui_story_5028_50280301_30_dialog_content = "Y cuando se ven amenazados, invocan rayos y usan sus garras para destripar a cualquier enemigo lo suficientemente tonto como para acercarse.",
  ui_story_5028_50280301_31_dialog_content = "Pero una vez que ponen su huevo, no muestran interés en si cae al suelo de manera segura o eclosiona.",
  ui_story_5028_50280301_32_dialog_content = "Quizás obligar a sus crías a enfrentarse solos al mundo hostil es la forma en que este rey de los cielos se asegura de que solo sobrevivan los más fuertes de su especie.",
  ui_story_5028_50280301_33_dialog_content = "Esta es también la razón por la cual los Drakolions son tan raros.",
  ui_story_5028_50280301_34_dialog_content = "Bien, ahora entiendo por qué tenemos que asegurarnos de que uno de sus huevos eclosione.",
  ui_story_5028_50280301_35_dialog_content = "A veces es mejor respetar los hábitos de una bestia maravillosa. Pero a veces, necesitamos echar una mano para que puedan crecer y ser grandes y fuertes.",
  ui_story_5028_50280301_36_dialog_content = "¡Excelente! ¡Este es el tipo de ensayo que me hace sentir como un verdadero extrozoólogo!",
  ui_story_5028_50280301_37_dialog_content = "¡Lo!",
  ui_story_5028_50280301_38_dialog_content = "¡Eso suena ridículamente peligroso! ¡Creo que me despediré ahora!",
  ui_story_5028_50280301_39_dialog_content = "¡Espera espera! ¡No te alejes!",
  ui_story_5028_50280301_40_dialog_content = "¡Lo, lo, lo!",
  ui_story_5028_50280301_41_dialog_content = "¡Ah, ja, ja! Según las notas de mi maestro, el huevo eclosionará inmediatamente después de aterrizar. Suponiendo que aterrice con seguridad, quiero decir.",
  ui_story_5028_50280301_42_dialog_content = "Así que todo lo que tenemos que hacer es asegurarnos de que no se rompa cuando aterrice.",
  ui_story_5028_50280301_43_dialog_content = "Oh, eso es todo, ¿eh? ¿Y qué hay de esa aterradora cosa del dragón?",
  ui_story_5028_50280301_44_dialog_content = "¿Qué tan peligroso es un Drakolion, diría usted? En tu opinión profesional.",
  ui_story_5028_50280301_45_dialog_content = "Sobre... digamos 50 puntos peligrosos?",
  ui_story_5028_50280301_46_dialog_content = "Bien, entonces 50 de 100. Un peligro de rango medio. Eso no suena tan mal.",
  ui_story_5028_50280301_47_dialog_content = "(¿Eh? No pensé PlayerName confiaría en mí tan fácilmente. ¡Ahora me siento culpable!)",
  ui_story_5028_50280301_48_dialog_content = "50... de 10.",
  ui_story_5028_50280301_49_dialog_content = "...",
  ui_story_5028_50280301_50_dialog_content = "Lo...",
  ui_story_5028_50280301_51_dialog_content = "¡Ah, claro! Está bien, me voy.",
  ui_story_5028_50280301_52_dialog_content = "¡No te vayas, no te vayas! ¡Por favor!",
  ui_story_5028_50280301_53_dialog_content = "Tengo cosas que podemos usar. Como, algo para cubrir nuestro olor.",
  ui_story_5028_50280301_54_dialog_content = "Si usamos eso, estaremos bien. Las notas dicen que los Drakolions tienen muy mala vista. Si no puede olernos, no sabrá que estamos allí.",
  ui_story_5028_50280301_55_dialog_content = "Oh...",
  ui_story_5028_50280301_56_dialog_content = "¿No tienes ideas más seguras?",
  ui_story_5028_50280301_57_dialog_content = "¿Tal vez podríamos usar a Soroz para atrapar el huevo?",
  ui_story_5028_50280301_58_dialog_content = "Teóricamente posible, aunque tengo una duda.",
  ui_story_5028_50280301_59_dialog_content = "¿Soroz es hombre o mujer? Porque necesito saber si vamos a evitar un ataque Drakolion.",
  ui_story_5028_50280301_60_dialog_content = "...",
  ui_story_5028_50280301_61_dialog_content = "...",
  ui_story_5028_50280301_62_dialog_content = "... Lo?",
  ui_story_5028_50280301_63_dialog_content = "Esa es una pregunta difícil de responder...",
  ui_story_5028_50280301_64_dialog_content = "Sabes qué, finge que no dije nada.",
  ui_story_5028_50280301_65_dialog_content = "Eres el experto, así que haremos las cosas a tu manera. Por aterrador que pueda ser.",
  ui_story_5028_50280301_66_dialog_content = "Relax. ¡Te mostraré de lo que es capaz un extrozoólogo talentoso!",
  ui_story_5028_50280301_67_dialog_content = "Lo...",
  ui_story_5028_50280301_68_dialog_content = "Ah—Ah—¡Achu!",
  ui_story_5028_50280301_69_dialog_content = "Esta crema para enmascarar el olor huele un poco familiar.",
  ui_story_5028_50280301_70_dialog_content = "Al menos mantiene alejados a los insectos. Todos nos están evitando, incluso mientras estamos agazapados aquí abajo en la hierba.",
  ui_story_5028_50280301_71_dialog_content = "Lo...",
  ui_story_5028_50280301_72_dialog_content = "Jejeje. Es un extracto hecho de estiércol de Kyllo. Funciona bien, ¿no?",
  ui_story_5028_50280301_73_dialog_content = "¿¡Qué!?",
  ui_story_5028_50280301_74_dialog_content = "¡Deberías haberlo dicho antes!",
  ui_story_5028_50280301_75_dialog_content = "Ahora siento toda la picazón. ¿Es venenoso?",
  ui_story_5028_50280301_76_dialog_content = "¡Por supuesto que no! Yo también lo unté, ¿recuerdas?",
  ui_story_5028_50280301_77_dialog_content = "Y mira, su grosor ayuda a retener la humedad, por lo que es bueno para tu piel.",
  ui_story_5028_50280301_78_dialog_content = "Utilizo la secreción de Kyllo para hacer toda una gama de productos para el cuidado de la piel.",
  ui_story_5028_50280301_78X_dialog_content = "Mantiene mi tez fresca y clara, incluso después de un día entero en el campo.",
  ui_story_5028_50280301_79_dialog_content = "¡Lo, lo!",
  ui_story_5028_50280301_80_dialog_content = "¡Shhh! Escuché algo.",
  ui_story_5028_50280301_81_dialog_content = "¿Es un Drakolion?",
  ui_story_5028_50280301_82_dialog_content = "Sí. Cuando están a punto de poner un huevo, vuelan a algún lugar que creen que será seguro y hacen el menor ruido posible.",
  ui_story_5028_50280301_83_dialog_content = "Pero todavía puedo escuchar el sonido de las alas, y estoy seguro de que es un Drakolion.",
  ui_story_5028_50280301_84_dialog_content = "<color=#e8d9bb>Ruido... Ruido...</color>",
  ui_story_5028_50280301_85_dialog_content = "De acuerdo, nunca he oído cómo suena un Drakolion en vuelo. Pero, ¿es posible que el sonido provenga de la maleza de allí?",
  ui_story_5028_50280301_86_dialog_content = "¡Argh! Debe ser algún animalito molesto.",
  ui_story_5028_50280301_87_dialog_content = "¡Kyllo, ve y persíguelo!",
  ui_story_5028_50280301_88_dialog_content = "¡Lo!",
  ui_story_5028_50280301_89_dialog_content = "PlayerName, ¿realmente no puedes oírlo? Es como si se rasguearan las cuerdas de un instrumento.",
  ui_story_5028_50280301_90_dialog_content = "<color=#e8d9bb>Ruido... Ruido... Ruido...</color>",
  ui_story_5028_50280301_91_dialog_content = "... ¡Mira!",
  ui_story_5028_50280301_92_dialog_content = "Cuerdas de instrumentos? Todo lo que puedo escuchar es la hierba y Kyllo, eso es todo.",
  ui_story_5028_50280301_93_dialog_content = "¡Lo! ¡Lo, lo!",
  ui_story_5028_50280301_94_dialog_content = "¡Eres tan tonto! ¿Quieres que te arranque un pelo y lo rasguee para que sepas de lo que hablo?",
  ui_story_5028_50280301_95_dialog_content = "<size=45>Lo-!</size>",
  ui_story_5028_50280301_96_dialog_content = "¡Kyllo, eres demasiado ruidoso!",
  ui_story_5028_50280301_97_dialog_content = "¡Gahhhhhh!",
  ui_story_5028_50280301_98_dialog_content = "¡Eclipsites!",
  ui_story_5028_50280301_99_dialog_content = "¿Por qué tiene que hacer eso ahora? Si el Drakolion nos ve cuando está tratando de poner un huevo, ¡estamos acabados!",
  ui_story_5028_50280301_100_dialog_content = "Hagamos esto rápido, PlayerName!",
  ui_story_5028_50280301_101_dialog_content = "¡Entendido! ¡Vamos!",
  ui_story_5028_50280301_102_dialog_content = "¡Lo!",
  ui_story_5028_50280302_1_dialog_content = "Está bien, bueno, al menos eso está resuelto.",
  ui_story_5028_50280302_2_dialog_content = "Con toda esta crema para enmascarar el olor, los Eclipsites no deberían haber sido capaces de encontrarnos.",
  ui_story_5028_50280302_3_dialog_content = "Oye, PlayerName, ¿estás seguro de que no hay nada en ti que les atraiga?",
  ui_story_5028_50280302_4_dialog_content = "¿Eres como una especie de faro o algo que atrae su atención de forma natural?",
  ui_story_5028_50280302_5_dialog_content = "Como polillas a una llama.",
  ui_story_5028_50280302_6_dialog_content = "Ahora que lo pienso, podrías tener razón.",
  ui_story_5028_50280302_7_dialog_content = "No importa a dónde vaya (la playa, las montañas, el desierto, las ruinas antiguas), siempre aparecen eclipses.",
  ui_story_5028_50280302_8_dialog_content = "Es como los extraños asesinatos que ocurren cada vez que un famoso detective está presente.",
  ui_story_5028_50280302_9_dialog_content = "<size=30>Una vez más, el Maestro me carga con una carga...</size>",
  ui_story_5028_50280302_10_dialog_content = "¿Qué?",
  ui_story_5028_50280302_11_dialog_content = "No importa. Al menos el Drakolion no se ha fijado en nosotros y parece que está a punto de poner su huevo.",
  ui_story_5028_50280302_12_dialog_content = "Está descendiendo. Escondámonos.",
  ui_story_5028_50280302_13_dialog_content = "¡Yo lo veo! ¿Pero seguramente el huevo se romperá si cae desde esa altura?",
  ui_story_5028_50280302_14_dialog_content = "¿Qué clase de práctica extraña es esta? Es un milagro que la especie no se haya extinguido.",
  ui_story_5028_50280302_15_dialog_content = "Todos los zoólogos de Astra se preguntan lo mismo.",
  ui_story_5028_50280302_16_dialog_content = "Pero eso es bestias maravillosas para ti. Su comportamiento no siempre tiene sentido.",
  ui_story_5028_50280302_17_dialog_content = "Lo que significa... que tenemos que pensar en algo, o el huevo se romperá.",
  ui_story_5028_50280302_18_dialog_content = "¡Lo!",
  ui_story_5028_50280302_19_dialog_content = "fia? ¿Qué estás haciendo?",
  ui_story_5028_50280302_20_dialog_content = "¡Voy a trepar a este árbol para atrapar el huevo!",
  ui_story_5028_50280302_21_dialog_content = "¡No seas estúpido! Es un árbol alto, pero no es lo suficientemente alto.",
  ui_story_5028_50280302_22_dialog_content = "¿Y cómo vas a usar la red allá arriba?",
  ui_story_5028_50280302_23_dialog_content = "¡Argh! Entonces, ¿qué debemos hacer entonces? No podemos evitarlo así.",
  ui_story_5028_50280302_24_dialog_content = "Solo ponen huevos una vez por década y ya están casi extintos.",
  ui_story_5028_50280302_25_dialog_content = "Obtuve toda la información que necesitaba de usted, pero todavía no pude protegerla, Maestro...",
  ui_story_5028_50280302_26_dialog_content = "Lo...",
  ui_story_5028_50280302_27_dialog_content = "¡Lo se!",
  ui_story_5028_50280302_28_dialog_content = "¿eh? Te refieres a...",
  ui_story_5028_50280302_29_dialog_content = "¿De verdad puedo?",
  ui_story_5028_50280302_30_dialog_content = "No tenemos otra opción, ¡solo podemos probar esto!",
  ui_story_5028_50280302_31_dialog_content = "PlayerName, ¡gracias por dejar que Soroz nos ayude!",
  ui_story_5028_50280302_32_dialog_content = "Bueno, no puedo dejar que el bebé Drakolion muera antes de que llegue a ver el mundo.",
  ui_story_5028_50280302_33_dialog_content = "No estoy seguro de lo que el Drakolion pensará de Soroz, ¡pero intentémoslo!",
  ui_story_5028_50280302_34_dialog_content = "Rugido-",
  ui_story_5028_50280302_35_dialog_content = "PlayerName! ¡El Drakolion parece haberse interesado en Soroz!",
  ui_story_5028_50280302_36_dialog_content = "De hecho, parece querer hacerse amigo de Soroz. Se sigue acercando.",
  ui_story_5028_50280302_37_dialog_content = "Bueno, casi allí. Sólo un poco más cerca... y luego puedo usar la red...",
  ui_story_5028_50280302_38_dialog_content = "(Espera, ¿qué es eso en su tobillo? No importa, me preocuparé de eso más tarde).",
  ui_story_5028_50280302_39_dialog_content = "¡Lo! ¡Lo!",
  ui_story_5028_50280302_40_dialog_content = "Rooarrrrr—",
  ui_story_5028_50280302_41_dialog_content = "¡Fia! ¡Está viniendo!",
  ui_story_5028_50280302_42_dialog_content = "¡Lo sé! ¡Acércanos un poco más y déjanos el resto a Kyllo y a mí!",
  ui_story_5028_50280302_43_dialog_content = "3.",
  ui_story_5028_50280302_44_dialog_content = "2.",
  ui_story_5028_50280302_45_dialog_content = "1.",
  ui_story_5028_50280302_46_dialog_content = "¡Fia!",
  ui_story_5028_50280302_47_dialog_content = "¡Lo!",
  ui_story_5028_50280302_48_dialog_content = "!",
  ui_story_5028_50280302_49_dialog_content = "¡Funcionó!",
  ui_story_5028_50280302_50_dialog_content = "Es tan brillante. ¿Va a eclosionar ahora mismo?",
  ui_story_5028_50280302_51_dialog_content = "PAGS...",
  ui_story_5028_50280302_52_dialog_content = "¿Mirar furtivamente?",
  ui_story_5028_50280302_53_dialog_content = "¡Lo, lo!",
  ui_story_5028_50280302_54_dialog_content = "Es... ¡Es tan lindo!",
  ui_story_5028_50280302_55_dialog_content = "¿Cómo algo tan pequeño se convierte en una de esas enormes criaturas?",
  ui_story_5028_50280302_56_dialog_content = "Es increíble. No es de extrañar que los Drakolions sean <color=#FFB400>exóticos</color>.",
  ui_story_5028_50280302_57_dialog_content = "¡Fia! ¿Funcionó?",
  ui_story_5028_50280302_58_dialog_content = "¡Lo hizo! ¡Todo gracias a ti y a Soroz! El Drakolion ya salió del cascarón.",
  ui_story_5028_50280302_59_dialog_content = "¡Lo!",
  ui_story_5028_50280302_60_dialog_content = "Sí, gracias a ti también, Kyllo.",
  ui_story_5028_50280302_61_dialog_content = "¡Lo, lo!",
  ui_story_5028_50280302_62_dialog_content = "¡Mirar furtivamente!",
  ui_story_5028_50280302_63_dialog_content = "¡Chicos, dejemos las felicitaciones para más tarde!",
  ui_story_5028_50280302_64_dialog_content = "El Drakolion se aferró a Soroz y no lo suelta, lo que significa que no podemos aterrizar.",
  ui_story_5028_50280302_65_dialog_content = "Ah, me olvidé de mencionar.",
  ui_story_5028_50280302_65X_dialog_content = "Son muy protectores de su especie. ¡Probablemente piense que estamos secuestrando a la cría!",
  ui_story_5028_50280302_66_dialog_content = "¿¡Qué!? ¡Estamos tan buenos como muertos entonces!",
  ui_story_5028_50280302_67_dialog_content = "No, espera. Ese no es un grito beligerante.",
  ui_story_5028_50280302_68_dialog_content = "Suena como... Creo que está enamorado de Soroz.",
  ui_story_5028_50280302_69_dialog_content = "¿¡Que qué!?",
  ui_story_5028_50280302_70_dialog_content = "y ninguna señal de PlayerName aquí, tampoco.",
  ui_story_5028_50280302_71_dialog_content = "¿Eh? Estás Revy, ¿no es así? ¿Qué haces vagando por aquí?",
  ui_story_5028_50280302_72_dialog_content = "Vaya, Smokey.",
  ui_story_5028_50280302_73_dialog_content = "Estoy buscando la Caelestita.",
  ui_story_5028_50280302_74_dialog_content = "PlayerName y yo estábamos jugando a la pelota cerca.",
  ui_story_5028_50280302_75_dialog_content = "Pero nos separamos. Dejó una nota, pero creo que podría haber sido secuestrado.",
  ui_story_5028_50280302_76_dialog_content = "¿Qué?",
  ui_story_5028_50280302_77_dialog_content = "¿Qué acabas de decir? PlayerName ¿Fue secuestrado?",
  ui_story_5028_50280302_78_dialog_content = "¿Dónde está la nota?",
  ui_story_5028_50280302_79_dialog_content = "Oh, lo perdí mientras lidiaba con algunos eclipses.",
  ui_story_5028_50280302_80_dialog_content = "Que divertido",
  ui_story_5028_50280302_81_dialog_content = "Realmente es muy desafortunado. Me pregunto quién se lo llevó esta vez.",
  ui_story_5028_50280302_82_dialog_content = "¿Me ayudarás a encontrarlo?",
  ui_story_5028_50280302_83_dialog_content = "Vice y Gram se enfadarán conmigo si se enteran de que lo he perdido.",
  ui_story_5028_50280302_84_dialog_content = "Bueno, no tengo nada más que hacer. A ver si podemos encontrar al tonto.",
  ui_story_5028_50280401_1_dialog_content = "Juicio: Crisis del viñedo",
  ui_story_5028_50280401_2_dialog_content = "Uf... ¡Uf! ¡Decir ah!",
  ui_story_5028_50280401_3_dialog_content = "¡Hola, Fía! Fia, más despacio.",
  ui_story_5028_50280401_4_dialog_content = "¿Adónde vamos?",
  ui_story_5028_50280401_5_dialog_content = "Estamos rodeados de vides. ¿Qué estamos haciendo esta vez, incubando un dragón de uva?",
  ui_story_5028_50280401_6_dialog_content = "Hola",
  ui_story_5028_50280401_7_dialog_content = "Shhh. Estoy organizando mis notas sobre la eclosión de Drakolion.",
  ui_story_5028_50280401_8_dialog_content = "No podía creer lo rápido que creció. Creció tan grande como Kyllo instantáneamente y fue inmediatamente autosuficiente.",
  ui_story_5028_50280401_9_dialog_content = "*Suspiro*... No esperaba que volara en busca de su propio territorio tan rápido.",
  ui_story_5028_50280401_9X_dialog_content = "¡Ni siquiera había tenido la oportunidad de disfrutar adecuadamente de su ternura!",
  ui_story_5028_50280401_10_dialog_content = "Eh. Creo que deberíamos estar agradecidos de haber escapado del Drakolion con nuestras vidas.",
  ui_story_5028_50280401_11_dialog_content = "En serio, ya no puedo caminar. Tomemos un descanso.",
  ui_story_5028_50280401_12_dialog_content = "¿Un descanso? ¿Ya? Aunque ya casi llegamos...",
  ui_story_5028_50280401_13_dialog_content = "no se que hacer contigo, PlayerName. Toma, abre de par en par y bebe esto.",
  ui_story_5028_50280401_14_dialog_content = "¿Q-qué estás haciendo? ¡No estoy bebiendo nada!",
  ui_story_5028_50280401_15_dialog_content = "Vamos. ¡Sé bueno!",
  ui_story_5028_50280401_16_dialog_content = "¡Quedarse atrás!",
  ui_story_5028_50280401_17_dialog_content = "Kyllo, ayúdame a sostener PlayerName ¡abajo!",
  ui_story_5028_50280401_18_dialog_content = "¡Lo, lo!",
  ui_story_5028_50280401_19_dialog_content = "*Grito ahogado* ¡Glug glug glug!",
  ui_story_5028_50280401_20_dialog_content = "¡Es picante! No, espera. eso es leche? Está cambiando de nuevo... ¡Ahora está tan helado!",
  ui_story_5028_50280401_21_dialog_content = "¿Qué diablos me hiciste beber?",
  ui_story_5028_50280401_22_dialog_content = "Bebida energética de patente de Fia, elaborada con leche de buey de fuego y tallos de castaweed.",
  ui_story_5028_50280401_23_dialog_content = "También un poco de menta helada, que agregué especialmente. Ese fue el bit al final. Solo crece en Northland, ya sabes. Vigorizante, ¿no?",
  ui_story_5028_50280401_24_dialog_content = "Le doy todos los ingredientes a Kyllo y lo revuelve todo en su estómago. Eso hace que la mezcla sea más suave que hacerlo a mano.",
  ui_story_5028_50280401_25_dialog_content = "¡Con solo un sorbo, estarás lo más animado posible!",
  ui_story_5028_50280401_25X_dialog_content = "Sus ingredientes son muy preciados, para que lo sepas.",
  ui_story_5028_50280401_26_dialog_content = "¡Lo!",
  ui_story_5028_50280401_27_dialog_content = "Qué asco. Kyllo, ¡¿por qué la ayudas con este tipo de cosas?!",
  ui_story_5028_50280401_28_dialog_content = "Lo?",
  ui_story_5028_50280401_29_dialog_content = "¡Y en cuanto a ti, Fia!",
  ui_story_5028_50280401_30_dialog_content = "¿Eh?",
  ui_story_5028_50280401_31_dialog_content = "¡No puedes simplemente hacer tus propios brebajes y usarme como sujeto de prueba! Eso es ilegal. ¡Muy ilegal!",
  ui_story_5028_50280401_32_dialog_content = "¿Q-qué? ¿Cómo es posible?",
  ui_story_5028_50280401_33_dialog_content = "N-no le cuentes a nadie sobre este incidente, ¿de acuerdo? Soy demasiado joven y ambicioso para ir a prisión.",
  ui_story_5028_50280401_34_dialog_content = "Siempre y cuando prometas no verter una porquería rara en mi garganta...",
  ui_story_5028_50280401_35_dialog_content = "Bien bien. Pero fue por tu propio bien...",
  ui_story_5028_50280401_36_dialog_content = "Mmm. Sin embargo, parece estar funcionando.",
  ui_story_5028_50280401_37_dialog_content = "Me siento mucho mejor, renovado y lleno de energía.",
  ui_story_5028_50280401_38_dialog_content = "¡Mira, funciona! Espera, necesito escribir la receta que usé esta vez.",
  ui_story_5028_50280401_39_dialog_content = "Espera, ¿es la primera vez que se lo das a beber a alguien? ¡Soy el único Caelestite que queda en el continente!",
  ui_story_5028_50280401_40_dialog_content = "Si muriera en algún lugar como este solo porque me obligaron a beber un brebaje extraño...",
  ui_story_5028_50280401_41_dialog_content = "¡Ese es el loco final trágico que solo se lee en la ficción!",
  ui_story_5028_50280401_42_dialog_content = "Ahhaha. Por supuesto que no era la primera vez. De todos modos, ¿cómo te sientes?",
  ui_story_5028_50280401_42X_dialog_content = "¿Te gustaría exprimir a Kyllo un poco más?",
  ui_story_5028_50280401_43_dialog_content = "¿¡Lo!?",
  ui_story_5028_50280401_44_dialog_content = "¡Absolutamente no! Tu puedes tenerlo.",
  ui_story_5028_50280401_45_dialog_content = "¡Y ni se te ocurra volver a darme de comer algo tan cuestionable!",
  ui_story_5028_50280401_46_dialog_content = "Honestamente, un Caelestite grande y fuerte, asustado de una pequeña bebida energética. Eso es un poco vergonzoso.",
  ui_story_5028_50280401_47_dialog_content = "Honestamente, te daría una lección si no te necesitara para salvar a Soroz.",
  ui_story_5028_50280401_48_dialog_content = "Jejeje. Relax. Nos alejamos sanos y salvos del Drakolion, ¿no?",
  ui_story_5028_50280401_49_dialog_content = "Si está enamorado de Soroz, no le hará daño a Soroz.",
  ui_story_5028_50280401_50_dialog_content = "Dices eso, ¿pero crees que obligar a Soroz a volar con un Drakolion para siempre es mejor?",
  ui_story_5028_50280401_51_dialog_content = "Ejem.",
  ui_story_5028_50280401_52_dialog_content = "¡Waah!",
  ui_story_5028_50280401_53_dialog_content = "¿Quién era ese? ¿Un eclipse? ¿Una bestia salvaje? ¿Un monstruo?",
  ui_story_5028_50280401_54_dialog_content = "Lamento decepcionarte, pero nada de lo anterior. Solo soy un auroriano.",
  ui_story_5028_50280401_55_dialog_content = "Supongo que serías el mejor alumno del Sr. Vic.",
  ui_story_5028_50280401_56_dialog_content = "Vic?",
  ui_story_5028_50280401_57_dialog_content = "(Vamos, Fia, tienes que hacerlo mejor que esto. Imagina que un anciano amable te asuste).",
  ui_story_5028_50280401_58_dialog_content = "Ejem. Hola señor. Soy discípulo de Vic. Fia, la extrozoóloga.",
  ui_story_5028_50280401_59_dialog_content = "Fia, ¿no sigues entrenando?",
  ui_story_5028_50280401_60_dialog_content = "Un experto en formación sigue siendo un experto.",
  ui_story_5028_50280401_61_dialog_content = "¡Perdóname! Yo debería haber sabido.",
  ui_story_5028_50280401_62_dialog_content = "Entonces, mi maestro—",
  ui_story_5028_50280401_63_dialog_content = "En mi juventud, yo era un Lumo Guard. Luchó en bastantes guerras, si puedo decirlo yo mismo.",
  ui_story_5028_50280401_64_dialog_content = "Esta rodilla sufre de una vieja herida de guerra, en realidad. Lo tengo el día Señor Schwartz y luché codo con codo contra los eclipses.",
  ui_story_5028_50280401_65_dialog_content = "Señor, usted—",
  ui_story_5028_50280401_66_dialog_content = "Ah, pero lo que realmente quería ser, por supuesto, era un autor. Solía escabullirme de mis deberes para escribir.",
  ui_story_5028_50280401_67_dialog_content = "Terminé siendo atrapado y dado de alta temprano. Me enviaron aquí, para cultivar uvas.",
  ui_story_5028_50280401_68_dialog_content = "Por favor escucha-",
  ui_story_5028_50280401_69_dialog_content = "¡He escrito muchas novelas exitosas!",
  ui_story_5028_50280401_69X_dialog_content = "Tales como El caballero ya está muerto, Judge x Family, Karma Rider Vice, y así.",
  ui_story_5028_50280401_70_dialog_content = "¡Señor! Por favor, díganos qué tenemos que hacer primero.",
  ui_story_5028_50280401_71_dialog_content = "¡Ay, ay, ay! Si, eso. Lo siento mucho. Te lo diré enseguida.",
  ui_story_5028_50280401_72_dialog_content = "¡Estúpido, molesto, idiota, Maestro! ¡Maldito sea!",
  ui_story_5028_50280401_73_dialog_content = "¡Cómo se atreve a hacerme pasar toda la noche cuidando la viña de un viejo tonto!",
  ui_story_5028_50280401_74_dialog_content = "¡Estoy tratando de ser un extrozoólogo! ¡No un guardia de seguridad que persigue a los ladrones!",
  ui_story_5028_50280401_75_dialog_content = "Ey, despierta. Tu reloj.",
  ui_story_5028_50280401_76_dialog_content = "Blech, estás babeando...",
  ui_story_5028_50280401_77_dialog_content = "¡Obtener! ¡Arriba!",
  ui_story_5028_50280401_78_dialog_content = "¿Eh? ¿Hay un ladrón?",
  ui_story_5028_50280401_79_dialog_content = "Sí, un ladrón robó tu Soroz directamente de las nubes.",
  ui_story_5028_50280401_80_dialog_content = "¿Qué? ¿En serio?",
  ui_story_5028_50280401_81_dialog_content = "¡No en realidad no! Es tu turno de vigilar. Estoy agotado.",
  ui_story_5028_50280401_82_dialog_content = "<color=#e8d9bb>Mucho más tarde</color>",
  ui_story_5028_50280401_83_dialog_content = "Ronquido...",
  ui_story_5028_50280401_84_dialog_content = "¡Ja, ja, ja!",
  ui_story_5028_50280401_85_dialog_content = "¿Qué fue eso?",
  ui_story_5028_50280401_86_dialog_content = "Hola. Munch munch.",
  ui_story_5028_50280401_87_dialog_content = "¡Fia!",
  ui_story_5028_50280401_88_dialog_content = "¿Q-Qué?",
  ui_story_5028_50280401_89_dialog_content = "Mierda...?",
  ui_story_5028_50280401_90_dialog_content = "¡Despierta!",
  ui_story_5028_50280401_91_dialog_content = "¡Se acabaron todas las uvas!",
  ui_story_5028_50280401_92_dialog_content = "¡¿Qué?!?!",
  ui_story_5028_50280401_93_dialog_content = "¡El culpable se fue por ahí! ¡Apresúrate!",
  ui_story_5028_50280401_94_dialog_content = "¡Qué diablo astuto!",
  ui_story_5028_50280401_95_dialog_content = "¡Desapareció en el bosque, así como así!",
  ui_story_5028_50280401_96_dialog_content = "No hay nada que podamos hacer. Nunca nos pondremos al día.",
  ui_story_5028_50280401_97_dialog_content = "Tal vez hay más de uno de ellos. Deberíamos volver al viñedo.",
  ui_story_5028_50280401_98_dialog_content = "No. Jajaja-",
  ui_story_5028_50280401_99_dialog_content = "¿Estás bien, Fía? Sé que el ladrón escapó, pero la risa histérica parece un poco...",
  ui_story_5028_50280401_100_dialog_content = "No, no es eso. Acabo de pensar en un chiste realmente vergonzoso.",
  ui_story_5028_50280401_101_dialog_content = "¿Eh?",
  ui_story_5028_50280401_102_dialog_content = "Ya sabes cómo dicen: \"Pasea por el desierto de Rediesel y seguro que te encuentras con un gusano de arena\".",
  ui_story_5028_50280401_103_dialog_content = "Tengo uno nuevo: \"Pasea por un bosque oscuro con un Caelestite y seguro que te encuentras con...\"",
  ui_story_5028_50280401_104_dialog_content = "¡Gahhhhhh!",
  ui_story_5028_50280401_105_dialog_content = "¡Eso no es divertido! No tiene nada de divertido y atrae a los eclipses. ¡Correr!",
  ui_story_5028_50280401_106_dialog_content = "¡Guau! ¡Se hizo realidad! ¡Y espera, estúpido Caelestite!",
  ui_story_5028_50280401_107_dialog_content = "¡Espérame!",
  ui_story_5028_50280402_1_dialog_content = "¡Uf, puf!",
  ui_story_5028_50280402_2_dialog_content = "¿Por qué estos malditos eclipses no se dan por vencidos?",
  ui_story_5028_50280402_3_dialog_content = "¡Graagh!",
  ui_story_5028_50280402_4_dialog_content = "¡Cuidado!",
  ui_story_5028_50280402_5_dialog_content = "¡Oye!",
  ui_story_5028_50280402_6_dialog_content = "Estoy bien. Gracias, PlayerName.",
  ui_story_5028_50280402_7_dialog_content = "¡Oh, no! ¡El cuaderno de mi amo!",
  ui_story_5028_50280402_8_dialog_content = "Ve y consíguelo, rápido, antes de que aparezcan más Eclipsites. Me quedaré aquí.",
  ui_story_5028_50280402_9_dialog_content = "Pero...",
  ui_story_5028_50280402_10_dialog_content = "¡Ve!",
  ui_story_5028_50280402_11_dialog_content = "Graaah!",
  ui_story_5028_50280402_12_dialog_content = "Este Eclipsite me está ignorando por completo, va directo a Fia.",
  ui_story_5028_50280402_13_dialog_content = "(Necesito encontrar una oportunidad para golpear su punto débil).",
  ui_story_5028_50280402_14_dialog_content = "Graaah!",
  ui_story_5028_50280402_15_dialog_content = "(¡No puedo esperar más o Fia estará rodeada!)",
  ui_story_5028_50280402_16_dialog_content = "¡Ja!",
  ui_story_5028_50280402_17_dialog_content = "¡No esperaban esto, verdad, asquerosos Eclipsitas!",
  ui_story_5028_50280402_18_dialog_content = "¡Ay, ay, ay! Son tan duros como las rocas.",
  ui_story_5028_50280402_19_dialog_content = "¡Graagh!",
  ui_story_5028_50280402_20_dialog_content = "¡Guau! Estaba demasiado apresurado. ¡Es hora de buscar a Fia y salir!",
  ui_story_5028_50280402_21_dialog_content = "Lo tengo, PlayerName. ¡Vamos!",
  ui_story_5028_50280402_22_dialog_content = "¡Decir ah! Finalmente los sacudimos.",
  ui_story_5028_50280402_23_dialog_content = "PlayerName, ¿estás bien? Tu brazo está hinchado.",
  ui_story_5028_50280402_24_dialog_content = "No es nada. Abordé un Eclipsite y era un poco resistente.",
  ui_story_5028_50280402_25_dialog_content = "Todo es mi culpa por ser descuidado. ¡Lo siento mucho! ¡Le pondré un poco de pomada ahora mismo!",
  ui_story_5028_50280402_26_dialog_content = "Está bien. Mientras recuperemos el cuaderno de su difunto maestro.",
  ui_story_5028_50280402_27_dialog_content = "¿Eh? ¿Maestro \"tarde\"?",
  ui_story_5028_50280402_28_dialog_content = "Correcto. Sí, fingí que estaba muerto.",
  ui_story_5028_50280402_29_dialog_content = "¡Lo siento! En realidad está vivo.",
  ui_story_5028_50280402_30_dialog_content = "¿Eh?",
  ui_story_5028_50280402_31_dialog_content = "Vale, me puse ungüento y lo vendé. La hinchazón debería bajar pronto.",
  ui_story_5028_50280402_32_dialog_content = "<size=30>Y lo siento.</size>",
  ui_story_5028_50280402_33_dialog_content = "¿Qué?",
  ui_story_5028_50280402_34_dialog_content = "<size=30>Dije \"lo siento.</size>",
  ui_story_5028_50280402_35_dialog_content = "Fia, estás susurrando. No puedo oírte.",
  ui_story_5028_50280402_36_dialog_content = "*Inhala*",
  ui_story_5028_50280402_37_dialog_content = "<size=45>¡Lo siento! ¡Lo siento! ¡Lo siento! me disculpo vale!!!</size>",
  ui_story_5028_50280402_38_dialog_content = "Guau. De donde vino eso?",
  ui_story_5028_50280402_39_dialog_content = "Lo siento, mentí. Te lo compensaré y nunca volverá a suceder.",
  ui_story_5028_50280402_40_dialog_content = "Pero, sinceramente, era un maestro inútil. Simplemente me mandoneó y me hizo la vida difícil.",
  ui_story_5028_50280402_41_dialog_content = "No como tu, PlayerName. Fuiste honesto y amable y me ayudaste.",
  ui_story_5028_50280402_42_dialog_content = "Y entré en pánico y mentí, pero realmente quería desesperadamente un amigo. ¡En realidad!",
  ui_story_5028_50280402_43_dialog_content = "Espero puedas perdonarme.",
  ui_story_5028_50280402_44_dialog_content = "¡Y en cuanto a mi estúpido maestro, bien podría explotar donde está! ¡Hmph!",
  ui_story_5028_50280402_45_dialog_content = "¡Achuu!",
  ui_story_5028_50280402_46_dialog_content = "Alguien debe estar hablando de mí. ¿Quién, me pregunto?",
  ui_story_5028_50280402_47_dialog_content = "Siento algo bastante siniestro...",
  ui_story_5028_50280402_48_dialog_content = "Ah, ya entiendo. En realidad, me di cuenta en ese momento que estabas fingiendo las lágrimas. Pero no estaba dispuesto a abandonarte allí.",
  ui_story_5028_50280402_49_dialog_content = "Pero honestamente, Fia, desear que alguien explote es demasiado, ¿no?",
  ui_story_5028_50280402_50_dialog_content = "No puedes decir cosas así, incluso si estás bromeando.",
  ui_story_5028_50280402_51_dialog_content = "Y aunque su letra puede parecer garabatos de pollo, tu maestro dedicó mucho tiempo y esfuerzo a ese cuaderno. Es muy detallado.",
  ui_story_5028_50280402_52_dialog_content = "No te lo habría dado si no te tuviera en alta estima.",
  ui_story_5028_50280402_53_dialog_content = "Oh... bueno, sí, supongo que tienes razón.",
  ui_story_5028_50280402_54_dialog_content = "No debería desearle la muerte a nadie, ni siquiera a él. Me disculpo con él también, incluso si está demasiado lejos para escucharlo.",
  ui_story_5028_50280402_55_dialog_content = "Y nunca volveré a decir algo así. Asi que...",
  ui_story_5028_50280402_56_dialog_content = "Entonces, ¿podrías dejar de acariciarme la cabeza? ¡Sé que somos amigos, pero soy tímido y Kyllo está mirando!",
  ui_story_5028_50280402_57_dialog_content = "Oh, lo siento. Es solo, ya sabes... Es algo natural, con la diferencia de altura.",
  ui_story_5028_50280402_58_dialog_content = "¿Me estás llamando corto?",
  ui_story_5028_50280402_59_dialog_content = "Ejem. Bueno, de todos modos... ¿Tienes alguna idea sobre ese ladrón de uvas?",
  ui_story_5028_50280402_60_dialog_content = "Bueno, me pareció como un <color=#FFB400>Bica</color>. Ese es un tipo de bestia maravillosa.",
  ui_story_5028_50280402_61_dialog_content = "Según el cuaderno, les gustan los alimentos de forma redonda y pueden tragarlos enteros sin importar el tamaño.",
  ui_story_5028_50280402_62_dialog_content = "Verá, tienen cuerpos muy flexibles, que se expanden para adaptarse al tamaño de su comida.",
  ui_story_5028_50280402_63_dialog_content = "Tienen piernas poderosas y son corredores rápidos.",
  ui_story_5028_50280402_64_dialog_content = "Pero no son criaturas inteligentes. Definitivamente una de las bestias maravillosas más estúpidas.",
  ui_story_5028_50280402_65_dialog_content = "¿Alimentos redondos? Déjame pensar.",
  ui_story_5028_50280402_66_dialog_content = "<size=30>¿Esto realmente va a funcionar?</size>",
  ui_story_5028_50280402_67_dialog_content = "<size=30>¿Simplemente poner una sandía en una jaula como esta? Quiero decir, claro, se ve sabroso.</size>.",
  ui_story_5028_50280402_68_dialog_content = "<size=30>¿Pero la Bica caerá en la trampa tan fácilmente?</size>",
  ui_story_5028_50280402_69_dialog_content = "<size=30>Relax. Si lo que dice el cuaderno es cierto, no podrá resistir nada tan grande y redondo.</size>",
  ui_story_5028_50280402_70_dialog_content = "<size=30>Así que confía en mí y ten fe en las notas de tu maestro.</size>",
  ui_story_5028_50280402_71_dialog_content = "<size=30>Bien entonces. Oye, algo viene.</size>",
  ui_story_5028_50280402_72_dialog_content = "Hai—Hai—",
  ui_story_5028_50280402_73_dialog_content = "¿Hola?",
  ui_story_5028_50280402_74_dialog_content = "Hola...",
  ui_story_5028_50280402_75_dialog_content = "¡Se lo comió!",
  ui_story_5028_50280402_76_dialog_content = "¡Lo!",
  ui_story_5028_50280402_77_dialog_content = "Supongo que el pequeño es realmente tonto.",
  ui_story_5028_50280402_78_dialog_content = "¿¡Hola!? ¿¡Hola!?",
  ui_story_5028_50280402_79_dialog_content = "No tengas miedo. No te vamos a lastimar.",
  ui_story_5028_50280402_80_dialog_content = "¿Hola?",
  ui_story_5028_50280402_81_dialog_content = "Bueno, solo queríamos preguntar. ¿Podría dejar de robar las uvas del Sr. Peng?",
  ui_story_5028_50280402_82_dialog_content = "¿Hai, hai?",
  ui_story_5028_50280402_83_dialog_content = "Déjame intentarlo.",
  ui_story_5028_50280402_84_dialog_content = "No tengas miedo. No te vamos a lastimar.",
  ui_story_5028_50280402_85_dialog_content = "Hola...?",
  ui_story_5028_50280402_86_dialog_content = "PlayerName, abre la jaula. No se escapará.",
  ui_story_5028_50280402_87_dialog_content = "Está bien, si estás seguro.",
  ui_story_5028_50280402_88_dialog_content = "Hola...",
  ui_story_5028_50280402_89_dialog_content = "¿Qué? ¿Dices que la sandía es sabrosa? ¿Estás realmente preocupado por eso en un momento como este?",
  ui_story_5028_50280402_90_dialog_content = "¡Ja, ja, ja!",
  ui_story_5028_50280402_91_dialog_content = "Dice que escapó de las garras de un monstruo aterrador.",
  ui_story_5028_50280402_92_dialog_content = "Debes estar aterrorizado, pobrecito. Pero eso no significa que puedas venir aquí y robar uvas.",
  ui_story_5028_50280402_93_dialog_content = "Fía, puedes...",
  ui_story_5028_50280402_94_dialog_content = "Hola.",
  ui_story_5028_50280402_95_dialog_content = "¿Vaya? ¿Estarás a salvo conmigo y habrá sandía para comer?",
  ui_story_5028_50280402_96_dialog_content = "Bueno, eso es dulce de tu parte.",
  ui_story_5028_50280402_97_dialog_content = "PlayerName, vamos a adoptarlo. Eso evitará que robe uvas. Y no será intimidado por otros animales.",
  ui_story_5028_50280402_98_dialog_content = "Bueno, si ustedes dos están de acuerdo, no tengo objeciones.",
  ui_story_5028_50280402_99_dialog_content = "Kyllo, no te importaría que Bica se uniera a nosotros, ¿verdad?",
  ui_story_5028_50280402_100_dialog_content = "¡Lo!",
  ui_story_5028_50280402_101_dialog_content = "Excelente. ¡Tenemos un nuevo compañero!",
  ui_story_5028_50280402_102_dialog_content = "He terminado con los carteles por aquí.",
  ui_story_5028_50280402_103_dialog_content = "Y estoy acabado de este lado.",
  ui_story_5028_50280402_104_dialog_content = "Los carteles de personas desaparecidas no sirven de mucho, pero nunca se sabe. Podríamos obtener una pista.",
  ui_story_5028_50280402_105_dialog_content = "¿Quién está ahí?",
  ui_story_5028_50280402_106_dialog_content = "Jejeje! vi todo, Smokey.",
  ui_story_5028_50280402_107_dialog_content = "Difícil de creer que hayas sucumbido a pegar anuncios para ganarte la vida ahora.",
  ui_story_5028_50280402_108_dialog_content = "Con este chico Illumina, nada menos.",
  ui_story_5028_50280402_109_dialog_content = "Escucha, si te faltan chas, ¿por qué no te presto algunas?",
  ui_story_5028_50280402_110_dialog_content = "Te prometo que no te cobraré demasiados intereses. Lo llamaremos... una tarifa amigable.",
  ui_story_5028_50280402_111_dialog_content = "Tch, hablas demasiado.",
  ui_story_5028_50280402_112_dialog_content = "Oye Revy, crees que tus armas Illuminan disparan más rápido, o la boca de esta mujer?",
  ui_story_5028_50280402_113_dialog_content = "No estoy seguro. No uso armas.",
  ui_story_5028_50280402_114_dialog_content = "PlayerName Está perdido. Smokey me está ayudando a buscar.",
  ui_story_5028_50280402_115_dialog_content = "¿Vaya? Diría que es extraño, pero en realidad no lo es. Y es sorprendente, pero no realmente.",
  ui_story_5028_50280402_116_dialog_content = "Pero si estás buscando Navigator, Smokey, entonces yo también lo haré. No dejaré que lo encuentres primero.",
  ui_story_5028_50280402_117_dialog_content = "Por favor, no.",
  ui_story_5028_50280402_118_dialog_content = "Le recomiendo que primero busque un médico para su trastorno crónico de competitividad. Vuelve y encuéntranos después de unos meses de terapia.",
  ui_story_5028_50280402_119_dialog_content = "Solo causarás problemas. Y apenas conoces a Caelestite.",
  ui_story_5028_50280402_120_dialog_content = "¿A menos que tengas la vista puesta en él por alguna razón? ¿Necesitas otro miembro para tu pésimo séquito?",
  ui_story_5028_50280402_121_dialog_content = "Oh, relájate, Smokey. No es el Caelestite en el que tengo la vista puesta.",
  ui_story_5028_50280402_122_dialog_content = "Me pregunto quién tiene la desgracia de ser oh tan bendecido.",
  ui_story_5028_50280402_123_dialog_content = "Eh. voy a ver si PlayerName está detrás de esos contenedores de basura.",
  ui_story_5028_50280501_1_dialog_content = "Prueba: Secreto junto al mar",
  ui_story_5028_50280501_2_dialog_content = "Qué sol tan deslumbrante y tórrido...",
  ui_story_5028_50280501_3_dialog_content = "Y la brisa marina es brumosa pero vigorizante.",
  ui_story_5028_50280501_4_dialog_content = "¡Y mira las multitudes!",
  ui_story_5028_50280501_5_dialog_content = "No puedo creer que estoy aquí de nuevo.",
  ui_story_5028_50280501_6_dialog_content = "¡Estoy hirviendo! Y está demasiado lleno aquí.",
  ui_story_5028_50280501_7_dialog_content = "¡Lo!",
  ui_story_5028_50280501_8_dialog_content = "Es realmente el momento perfecto para un viaje a la playa.",
  ui_story_5028_50280501_9_dialog_content = "¡Ay!",
  ui_story_5028_50280501_10_dialog_content = "¿Estás bien?",
  ui_story_5028_50280501_11_dialog_content = "Estoy bien gracias.",
  ui_story_5028_50280501_12_dialog_content = "Apuesto a que estás pensando: \"Si tan solo hubiera sido una chica bonita\".",
  ui_story_5028_50280501_13_dialog_content = "¡Yo no soy!",
  ui_story_5028_50280501_14_dialog_content = "¿O tal vez te gustan más los chicos en forma como él?",
  ui_story_5028_50280501_15_dialog_content = "¡No! Para.",
  ui_story_5028_50280501_16_dialog_content = "Sabes, creo que tu maestro debe preocuparse mucho por ti.",
  ui_story_5028_50280501_17_dialog_content = "Esto parece más unas vacaciones junto a la playa, no una especie de prueba.",
  ui_story_5028_50280501_18_dialog_content = "Sí claro, como si ese estúpido hombre fuera tan generoso.",
  ui_story_5028_50280501_19_dialog_content = "Está tan lleno aquí que lo odio. Y ni siquiera me dijo por qué me enviaría a un lugar como este.",
  ui_story_5028_50280501_20_dialog_content = "Todo lo que hizo fue decirme que cepillara esas pequeñas bolas de pelo, que afeitara esas pequeñas bolas de pelo. Luego vendería la piel.",
  ui_story_5028_50280501_21_dialog_content = "Y se iba bebiendo y divirtiéndose con el dinero...",
  ui_story_5028_50280501_22_dialog_content = "Y yo me quedaría en casa. Haciendo forraje para los Fatwrens. Limpiando después del Cocodeer. Ser conducido por el Speedhound para una carrera.",
  ui_story_5028_50280501_23_dialog_content = "¿Puedes imaginar? Una joven adorable como yo, utilizada por él como sirvienta.",
  ui_story_5028_50280501_24_dialog_content = "Y ahora aquí estoy, enviado a hacer trabajo de campo con las instrucciones más malas.",
  ui_story_5028_50280501_25_dialog_content = "Lo, lo",
  ui_story_5028_50280501_26_dialog_content = "¿Por qué decidiste ser su aprendiz entonces?",
  ui_story_5028_50280501_27_dialog_content = "Además, sigues haciendo las tareas que te da, incluso si te quejas constantemente.",
  ui_story_5028_50280501_28_dialog_content = "Sí. Fue un poco culpa del destino que lo conocí.",
  ui_story_5028_50280501_29_dialog_content = "Estaba obsesionado con este libro cuando era un niño llamado \"<color=#FFB400>1001 criaturas fantásticas</color>.\"",
  ui_story_5028_50280501_30_dialog_content = "Se podría decir que ese libro definió mi infancia.",
  ui_story_5028_50280501_30X_dialog_content = "Fue lo que me dio esta afinidad con los animales y me permitió comunicarme con ellos.",
  ui_story_5028_50280501_31_dialog_content = "Pero en Umbraton, hay muchos Aurorianos y básicamente no hay bestias maravillosas. No me gustó eso, así que me decidí.",
  ui_story_5028_50280501_32_dialog_content = "Decidí que buscaría al autor de ese libro y le pediría que me dijera dónde encontrar todas esas maravillosas bestias con las que soñaba todas las noches.",
  ui_story_5028_50280501_33_dialog_content = "Hice mis maletas, me despedí de mis padres y me dirigí al bosque donde se decía que vivía el autor.",
  ui_story_5028_50280501_34_dialog_content = "Pasé días buscándolo y no encontré nada. Entonces, un día, estaba sentado junto a mi tienda asando castafruit cuando apareció este hombre.",
  ui_story_5028_50280501_35_dialog_content = "Simplemente se arrastró fuera de la maleza y vino hacia mí, luciendo medio muerto de hambre.",
  ui_story_5028_50280501_36_dialog_content = "No me digas que eso fue...",
  ui_story_5028_50280501_37_dialog_content = "Sí. Pero en ese momento no tenía ni idea de que era él.",
  ui_story_5028_50280501_38_dialog_content = "Después de comer, me dijo al azar: \"Soy el mejor extrozoólogo del continente. Estoy haciendo una investigación ecológica cerca\".",
  ui_story_5028_50280501_39_dialog_content = "Parecía tanto como una especie de estafador que casi volví corriendo a la ciudad para llamar a los guardias.",
  ui_story_5028_50280501_40_dialog_content = "Pero luego me mostró las notas apenas legibles pero definitivamente genuinas que tenía sobre él, así como todo su extraño equipo.",
  ui_story_5028_50280501_41_dialog_content = "Con solo un silbido, pudo sacar una variedad de bestias maravillosas que habitaban en el bosque circundante.",
  ui_story_5028_50280501_42_dialog_content = "PlayerName, ¿recuerdas cuando conocimos a Bica?",
  ui_story_5028_50280501_43_dialog_content = "Te diste cuenta de que podía comunicarme con las bestias maravillosas, ¿no es así? Como el vínculo psíquico que tienes con los aurorianos.",
  ui_story_5028_50280501_44_dialog_content = "Así fue como pude entender a Bica y la cría de Drakolion. Y... bueno, me gusta más interactuar con bestias maravillosas que con aurorianos.",
  ui_story_5028_50280501_45_dialog_content = "Honestamente, debo haberme dejado llevar por lo alto de estar rodeado de bestias maravillosas en ese momento.",
  ui_story_5028_50280501_46_dialog_content = "No ayudó que siguiera diciéndome que mi habilidad para comunicarme con ellos me convertiría en un gran extrozoólogo.",
  ui_story_5028_50280501_47_dialog_content = "La idea de ser extrozoólogo fue como un sueño hecho realidad. No pude resistir la tentación.",
  ui_story_5028_50280501_48_dialog_content = "Incluso ahora, si pudiera elegir de nuevo, creo que seguiría eligiendo ser su aprendiz.",
  ui_story_5028_50280501_49_dialog_content = "Creí de todo corazón desde ese momento que él era el gran extrozoólogo Vic, autor del libro que tanto amaba.",
  ui_story_5028_50280501_50_dialog_content = "Elegí esta vida para mí, pero aun así, ¡tengo que decir que es un pésimo mentor!",
  ui_story_5028_50280501_51_dialog_content = "Ja ja. Pero has estado haciendo lo que amas todo este tiempo.",
  ui_story_5028_50280501_52_dialog_content = "¡Ay!",
  ui_story_5028_50280501_53_dialog_content = "¡Cuidado!",
  ui_story_5028_50280501_54_dialog_content = "Oh, lo siento. Me resbalé.",
  ui_story_5028_50280501_55_dialog_content = "No hay problema. Mientras estés bien.",
  ui_story_5028_50280501_56_dialog_content = "(¿Otra vez?)",
  ui_story_5028_50280501_57_dialog_content = "Lo siento. Entonces, er... En realidad, creo...",
  ui_story_5028_50280501_58_dialog_content = "Así es la vida. Las cosas no siempre salen bien. Ya eres más afortunado que mucha gente.",
  ui_story_5028_50280501_59_dialog_content = "Wow, verte tratar de parecer todo maduro como un adulto es bastante vergonzoso.",
  ui_story_5028_50280501_60_dialog_content = "¿La niña bonita que cayó en tus brazos te provocó una conmoción cerebral?",
  ui_story_5028_50280501_61_dialog_content = "¡Oh, por el amor de Dios, ella no cayó en mis brazos! Solo evité que se cayera.",
  ui_story_5028_50280501_62_dialog_content = "Por cierto, tu tono... ¿son celos?",
  ui_story_5028_50280501_63_dialog_content = "Decir ah. Como si tuviera tiempo para tonterías tan tediosas. Estoy bastante feliz con mis maravillosas bestias como compañía, gracias.",
  ui_story_5028_50280501_64_dialog_content = "Hay más sal en tus palabras que el océano.",
  ui_story_5028_50280501_65_dialog_content = "Tú-!",
  ui_story_5028_50280501_66_dialog_content = "Bien, de vuelta al negocio. Si puedes hablar con bestias maravillosas, eso significa que serás un excelente extrozoólogo.",
  ui_story_5028_50280501_67_dialog_content = "Al igual que mi capacidad para formar vínculos psíquicos con los aurorianos me convierte en un buen comandante en el campo de batalla.",
  ui_story_5028_50280501_68_dialog_content = "Si bien eso es cierto, hay excepciones. Mis habilidades no funcionan en Kyllo, por ejemplo.",
  ui_story_5028_50280501_69_dialog_content = "¡Lo!",
  ui_story_5028_50280501_70_dialog_content = "¿Por qué?",
  ui_story_5028_50280501_71_dialog_content = "No sé... El Maestro dice que es un tipo especial de bestia maravillosa. Un exótico.",
  ui_story_5028_50280501_72_dialog_content = "¡Lo!",
  ui_story_5028_50280501_73_dialog_content = "¿Exótico? ¿Seguramente solo algo como un Drakolion sería considerado exótico?",
  ui_story_5028_50280501_74_dialog_content = "Mira, incluso tú no crees lo que dice.",
  ui_story_5028_50280501_75_dialog_content = "Lo... Lo...",
  ui_story_5028_50280501_76_dialog_content = "No estés triste, Kyllo.",
  ui_story_5028_50280501_77_dialog_content = "Puede que no pueda entenderte, pero sé que eres un buen pequeño Kyllo.",
  ui_story_5028_50280501_78_dialog_content = "¡Lo!",
  ui_story_5028_50280501_79_dialog_content = "Inútil, quizás. Y bastante inútil.",
  ui_story_5028_50280501_80_dialog_content = "¡Lo!",
  ui_story_5028_50280501_81_dialog_content = "¡Ahhhhh!",
  ui_story_5028_50280501_82_dialog_content = "¿Por qué todo el mundo se cae?",
  ui_story_5028_50280501_83_dialog_content = "Sabía que había algo malo en este lugar. ¡Vayamos y veamos!",
  ui_story_5028_50280501_84_dialog_content = "¡Oye! Fia, no corras—",
  ui_story_5028_50280501_85_dialog_content = "¡Waah!",
  ui_story_5028_50280501_86_dialog_content = "¡Oye!",
  ui_story_5028_50280501_87_dialog_content = "G-gracias, PlayerName.",
  ui_story_5028_50280501_88_dialog_content = "Honestamente, ¿por qué corriste tan rápido sabiendo lo fácil que es resbalar aquí?",
  ui_story_5028_50280501_89_dialog_content = "Lo siento... Me emocioné. ¿Podrías ponerme abajo?",
  ui_story_5028_50280501_90_dialog_content = "Ah bien.",
  ui_story_5028_50280501_91_dialog_content = "¡Ay, lo sabía!",
  ui_story_5028_50280501_92_dialog_content = "¿Qué?",
  ui_story_5028_50280501_93_dialog_content = "¿No puedes verlo? La cosa se pegó a mi pie.",
  ui_story_5028_50280501_94_dialog_content = "Esta cosa translúcida es un <color=#FFB400>glooey</color>.",
  ui_story_5028_50280501_95_dialog_content = "Glú.",
  ui_story_5028_50280501_96_dialog_content = "Por lo general, habitan en el agua, pero suben a la tierra para respirar.",
  ui_story_5028_50280501_97_dialog_content = "Pero ser transparentes significa que son fáciles de pisar por accidente.",
  ui_story_5028_50280501_98_dialog_content = "Pero hay demasiados aurorianos por aquí. No creo que este lugar sea seguro para ellos nunca más.",
  ui_story_5028_50280501_99_dialog_content = "Deben haber desembarcado todos para migrar a un nuevo hogar.",
  ui_story_5028_50280501_100_dialog_content = "Pero se mueven demasiado lento y todo el mundo sigue resbalando sobre ellos. Si esto continúa, Glooeys y turistas terminarán lastimados.",
  ui_story_5028_50280501_101_dialog_content = "(Ella siempre se pone seria tan pronto como comienza a hablar de bestias maravillosas).",
  ui_story_5028_50280501_102_dialog_content = "De eso debe tratarse nuestra prueba: ¡ayudar a los Glooey a mudarse a un nuevo hogar!",
  ui_story_5028_50280501_103_dialog_content = "Sí. Recojamos los que fueron esparcidos por la multitud. Entonces podemos escoltarlos a un lugar seguro.",
  ui_story_5028_50280501_104_dialog_content = "Kyllo, deja de jugar con Glooey. ¡Ven y ayuda!",
  ui_story_5028_50280501_105_dialog_content = "¡Lo!",
  ui_story_5028_50280501_106_dialog_content = "Uf. ¿Ese es el último?",
  ui_story_5028_50280501_107_dialog_content = "gloo...",
  ui_story_5028_50280501_108_dialog_content = "Sí. Parece que todos se arrastran en la misma dirección.",
  ui_story_5028_50280501_109_dialog_content = "Estarán buscando una sección más tranquila de la costa para habitar. Sólo tenemos que asegurarnos de que lleguen allí.",
  ui_story_5028_50280501_110_dialog_content = "Aférrate. Creo que veo eclipses más adelante. ¿Podrías pedirles a los Glooey que se desvíen alrededor de ellos?",
  ui_story_5028_50280501_111_dialog_content = "No puedo, son demasiado tercos. Es por eso que no se apartan del camino y son pisoteados todo el tiempo.",
  ui_story_5028_50280501_112_dialog_content = "Y son solo unos pocos apestosos eclipses. ¿Por qué debemos escondernos?",
  ui_story_5028_50280501_113_dialog_content = "Déjamelos a mí esta vez. ¡Lucharé contra ellos!",
  ui_story_5028_50280502_1_dialog_content = "<color=#e8d9bb>*Olas rompiendo*</color>",
  ui_story_5028_50280502_2_dialog_content = "Es mucho más tranquilo aquí. Ni siquiera puedo oír las gaviotas.",
  ui_story_5028_50280502_3_dialog_content = "Creo que este será un buen hogar para los Glooey.",
  ui_story_5028_50280502_4_dialog_content = "Glú... Glú...",
  ui_story_5028_50280502_5_dialog_content = "La próxima vez, ¡ten más cuidado! Asegúrese de migrar antes de que lleguen los turistas, no después.",
  ui_story_5028_50280502_6_dialog_content = "¡Oye! Los turistas que resbalan y caen son inocentes, ya sabes.",
  ui_story_5028_50280502_7_dialog_content = "Pero entre las masas de eclipses y los cambios ambientales drásticos, los hábitats de bestias maravillosas son cada vez más difíciles de encontrar.",
  ui_story_5028_50280502_8_dialog_content = "Muchos de ellos protegen a los aurorianos todo el tiempo, ¿lo sabías?",
  ui_story_5028_50280502_9_dialog_content = "Muchas bestias maravillosas viven cerca de las ciudades, donde sirven como primera línea de defensa de los aurorianos, detectando y luchando contra los invasores de Eclipsite.",
  ui_story_5028_50280502_10_dialog_content = "Vaya, no sabía eso.",
  ui_story_5028_50280502_11_dialog_content = "De todos modos, esa es una prueba más completada. ¡Otro día productivo para ayudar a las maravillosas bestias!",
  ui_story_5028_50280502_12_dialog_content = "(¿Eh? Hay algo pegajoso en mi pierna.)",
  ui_story_5028_50280502_13_dialog_content = "gloo...",
  ui_story_5028_50280502_14_dialog_content = "¿Dices que viste un monstruo aterrador por aquí, pero nadie más te cree? ¿Así que te gustaría quedarte conmigo?",
  ui_story_5028_50280502_15_dialog_content = "Jejeje. Tus líneas de recogida son un poco cliché.",
  ui_story_5028_50280502_16_dialog_content = "Pero claro, por qué no. ¡Puedes unirte a los demás!",
  ui_story_5028_50280502_17_dialog_content = "PlayerName, Mira. ¡Tenemos otro nuevo compañero!",
  ui_story_5028_50280502_18_dialog_content = "¡Lo!",
  ui_story_5028_50280502_19_dialog_content = "¿Otro? ¿Eres siempre tan popular con ellos?",
  ui_story_5028_50280502_20_dialog_content = "¡Hola!",
  ui_story_5028_50280502_21_dialog_content = "Por supuesto. Voy a ser un extrozoólogo, necesito hacerme amigo de todas las bestias maravillosas.",
  ui_story_5028_50280502_22_dialog_content = "Pero le daré algunos a mi amo para que los cuide si termino con demasiados. Estar conmigo podría no ser siempre seguro para ellos, después de todo.",
  ui_story_5028_50280502_23_dialog_content = "Ya veo. Bueno, ¿puedo molestar a nuestra experta residente para que me diga cuántas pruebas más tiene que completar?",
  ui_story_5028_50280502_24_dialog_content = "Mmm. Permítame verificar.",
  ui_story_5028_50280502_25_dialog_content = "¡Impresionante! Vaya. ¡Maldito!",
  ui_story_5028_50280502_26_dialog_content = "Lo?",
  ui_story_5028_50280502_27_dialog_content = "¿Qué?",
  ui_story_5028_50280502_28_dialog_content = "Bueno, podrías decir que terminé, pero también es posible que nunca termine.",
  ui_story_5028_50280502_29_dialog_content = "¿De qué estás hablando?",
  ui_story_5028_50280502_30_dialog_content = "Um, ¡he terminado todas las pruebas peligrosas!",
  ui_story_5028_50280502_31_dialog_content = "Pero, ¿cómo voy a terminar este: memorizar la Enciclopedia Exótica del Maestro Vic?",
  ui_story_5028_50280502_32_dialog_content = "Puaj. He estado trabajando en él durante una semana y solo memoricé dos páginas y media.",
  ui_story_5028_50280502_33_dialog_content = "Lo...",
  ui_story_5028_50280502_34_dialog_content = "Hmm, la lucha y la fuerza bruta no serán suficientes para este.",
  ui_story_5028_50280502_35_dialog_content = "Puede que sea un caelestita, pero todavía no tengo forma de inculcar toda esa información en tu cabeza.",
  ui_story_5028_50280502_36_dialog_content = "... ¡Mira!",
  ui_story_5028_50280502_37_dialog_content = "Suspiro...",
  ui_story_5028_50280502_38_dialog_content = "¡Lo! ¡Lo!",
  ui_story_5028_50280502_39_dialog_content = "¿eh? Kyllo, detente, ¿qué estás haciendo?",
  ui_story_5028_50280502_40_dialog_content = "¡Deja de tirar del cuaderno, lo vas a romper!",
  ui_story_5028_50280502_41_dialog_content = "¡Lo!",
  ui_story_5028_50280502_42_dialog_content = "Dije, no—¡Ah!",
  ui_story_5028_50280502_43_dialog_content = "Fía, ¿estás bien?",
  ui_story_5028_50280502_44_dialog_content = "¿Estás buscando pelea, Kyllo?",
  ui_story_5028_50280502_45_dialog_content = "Espera, está hojeando el cuaderno.",
  ui_story_5028_50280502_46_dialog_content = "¿Qué?",
  ui_story_5028_50280502_47_dialog_content = "¡Lo! ¡Lo!",
  ui_story_5028_50280502_48_dialog_content = "Esta página... ¿trata de un conejo?",
  ui_story_5028_50280502_49_dialog_content = "¿Un conejo?",
  ui_story_5028_50280502_50_dialog_content = "Ya estamos acá.",
  ui_story_5028_50280502_51_dialog_content = "¿Eh? ¿Aquí es donde termina la pista por la que pagaste todo ese dinero?",
  ui_story_5028_50280502_52_dialog_content = "Imagínate caer en una estafa así después de tantos años en Umbraton.",
  ui_story_5028_50280502_53_dialog_content = "¿O solo querías llevarme a una cita de juegos junto al mar? Lamento decepcionarte, pero no traje mi traje de baño.",
  ui_story_5028_50280502_54_dialog_content = "Ja ja. Da la casualidad de que tengo el mío puesto.",
  ui_story_5028_50280502_55_dialog_content = "Apuesto a que te arrepientes de no usar ese diminuto traje de baño tuyo ahora, ¿no es así?",
  ui_story_5028_50280502_56_dialog_content = "Ahora estás atascado luciendo demasiado vestido para ir a la playa solo como un tonto.",
  ui_story_5028_50280502_57_dialog_content = "No tienes idea de cuánto tiempo he esperado para ver esa mirada de envidia en tu rostro.",
  ui_story_5028_50280502_58_dialog_content = "¡Tú! Voy a tirarte al mar, luego ve a buscar a Caelestite.",
  ui_story_5028_50280502_59_dialog_content = "Ja ja. Seamos honestos, ¿a quién le importa Caelestite? Acabo de llegar porque tenía tiempo para matar.",
  ui_story_5028_50280502_60_dialog_content = "¿No es esa también la razón por la que vienes?",
  ui_story_5028_50280502_61_dialog_content = "Oh, por favor, mis motivaciones no son tan superficiales. Hazme un favor y no proyectes.",
  ui_story_5028_50280502_62_dialog_content = "¡Veo esto como una oportunidad para demostrar de una vez por todas que soy mejor que tú!",
  ui_story_5028_50280502_63_dialog_content = "¡No confiando en un traje de baño diminuto, sino usando mis habilidades como cazarrecompensas profesional!",
  ui_story_5028_50280502_64_dialog_content = "¿Vaya? Esa es una gran charla para alguien que olvidó llevar un traje de baño a la playa.",
  ui_story_5028_50280502_65_dialog_content = "¡Ooh genial! Yo también quiero un traje de baño.",
  ui_story_5028_50280502_66_dialog_content = "¡Sonríe para la cámara!",
  ui_story_5028_50280502_67_dialog_content = "<color=#e8d9bb>¡Hacer clic!</color>",
  ui_story_5028_50280502_68_dialog_content = "Lester?",
  ui_story_5028_50280502_69_dialog_content = "Oye, ¿no es esto? Smokey!?",
  ui_story_5028_50280502_70_dialog_content = "¿Qué estás haciendo aquí? ¿Sigues en tu viaje?",
  ui_story_5028_50280502_71_dialog_content = "Por supuesto. Ustedes dos también parecen familiares, ¿están todos aquí para unas vacaciones en la playa?",
  ui_story_5028_50280502_72_dialog_content = "Aquí, mira la foto que te tomé.",
  ui_story_5028_50280502_73_dialog_content = "Oh gracias.",
  ui_story_5028_50280502_74_dialog_content = "... Déjame ver.",
  ui_story_5028_50280502_75_dialog_content = "Supongo que podrías llamarlo un mini-descanso. Además, también estamos buscando a un amigo que ha sido secuestrado o se ha perdido o algo así.",
  ui_story_5028_50280502_76_dialog_content = "Oye, en realidad lo conoces, el Caelestite.",
  ui_story_5028_50280502_77_dialog_content = "¿Falta la Caelestita? ¿Falta la única Caelestita que queda en el continente?",
  ui_story_5028_50280502_78_dialog_content = "Sí, el único o lo que sea, de todos modos se ha ido.",
  ui_story_5028_50280502_79_dialog_content = "Ya veo. Bueno, mantendré mis ojos bien abiertos para él.",
  ui_story_5028_50280502_80_dialog_content = "Y si me lo encuentro, lo traeré de vuelta para ustedes.",
  ui_story_5028_50280601_1_dialog_content = "Prueba: Memoriza la Enciclopedia Exótica",
  ui_story_5028_50280601_2_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5028_50280601_3_dialog_content = "<color=#e8d9bb>¡Bang, bang!</color>",
  ui_story_5028_50280601_4_dialog_content = "¡Suficiente! Alto el fuego.",
  ui_story_5028_50280601_5_dialog_content = "Asustarás a la presa.",
  ui_story_5028_50280601_6_dialog_content = "Tch, ¿qué pasa con esos dos? ¿Los vamos a dejar ir?",
  ui_story_5028_50280601_7_dialog_content = "No hay tiempo. Tenemos que atrapar eso <color=#FFB400>conejo peko</color> pronto para <color=#FFB400>Gary</color>.",
  ui_story_5028_50280601_8_dialog_content = "Si hacemos enojar al jefe, estaremos en serios problemas.",
  ui_story_5028_50280601_9_dialog_content = "Mmm.",
  ui_story_5028_50280601_10_dialog_content = "Ahh—Ahh—",
  ui_story_5028_50280601_11_dialog_content = "¡Achuu!",
  ui_story_5028_50280601_12_dialog_content = "Shh.",
  ui_story_5028_50280601_13_dialog_content = "Se fueron.",
  ui_story_5028_50280601_14_dialog_content = "Hola",
  ui_story_5028_50280601_15_dialog_content = "Menos mal que Kyllo tuvo la previsión de encontrar este arbusto cubierto de nieve para que nos escondiéramos debajo.",
  ui_story_5028_50280601_16_dialog_content = "¡Lo!",
  ui_story_5028_50280601_17_dialog_content = "¡Achuuu!",
  ui_story_5028_50280601_18_dialog_content = "¡Achu! ¡Achu! ¡Achu!",
  ui_story_5028_50280601_19_dialog_content = "¿Estás bien? Toma, límpiate la nariz.",
  ui_story_5028_50280601_20_dialog_content = "*Olfatea* Gracias.",
  ui_story_5028_50280601_21_dialog_content = "Odio este lugar. Mis manos y pies están congelados y rígidos.",
  ui_story_5028_50280601_22_dialog_content = "Nunca hubiera venido a un lugar tan frío si no fuera por querer atrapar uno de esos conejos Peko mencionados en el cuaderno.",
  ui_story_5028_50280601_23_dialog_content = "Toma, toma mi abrigo. Oh, y tengo una bufanda de respaldo.",
  ui_story_5028_50280601_24_dialog_content = "No, dudo que duraras mucho sin ellos tampoco.",
  ui_story_5028_50280601_25_dialog_content = "Come esto.",
  ui_story_5028_50280601_26_dialog_content = "¡¿Mm?!",
  ui_story_5028_50280601_27_dialog_content = "Es una pastilla hecha de gusano de arena en polvo, aceite combustible y hierba solar.",
  ui_story_5028_50280601_28_dialog_content = "Te ayuda a mantenerte caliente en ambientes fríos.",
  ui_story_5028_50280601_29_dialog_content = "Pero este es el único que me queda desde que me quedé sin polvo de gusanos de arena recientemente.",
  ui_story_5028_50280601_30_dialog_content = "Me siento mucho más cálido. ¿Pero qué hay de ti?",
  ui_story_5028_50280601_31_dialog_content = "Usaré Glooey como aislamiento adicional en mi cuerpo.",
  ui_story_5028_50280601_32_dialog_content = "gloo...",
  ui_story_5028_50280601_33_dialog_content = "Si me derrumbo por el frío, puedes sacarme de la montaña y pedir ayuda.",
  ui_story_5028_50280601_34_dialog_content = "Pero si colapsas, no puedo hacer nada más que dejarte aquí.",
  ui_story_5028_50280601_35_dialog_content = "Correcto. Está bien, si pasa algo, te sacaré de este lugar seguro.",
  ui_story_5028_50280601_36_dialog_content = "Aunque ahora que lo pienso, no estoy seguro de que seas lo suficientemente fuerte para llevarme. Tal vez deberías escupir la píldora para que Kyllo pueda tomarla.",
  ui_story_5028_50280601_37_dialog_content = "Demasiado tarde, ya está en mi estómago.",
  ui_story_5028_50280601_38_dialog_content = "Ja ja. Sólo estaba bromeando.",
  ui_story_5028_50280601_39_dialog_content = "Lo?",
  ui_story_5028_50280601_40_dialog_content = "Vale, ahora que todos nos sentimos mejor, deberíamos empezar a movernos.",
  ui_story_5028_50280601_41_dialog_content = "Tenemos que encontrar al conejo Peko antes que esos cazadores.",
  ui_story_5028_50280601_42_dialog_content = "¿Es este conejo realmente tan raro? Seguro que logró atraer a muchos cazadores a este lugar dejado de la mano de Dios.",
  ui_story_5028_50280601_43_dialog_content = "Y parecen organizados y profesionales. Su jefe debe haber gastado una fortuna.",
  ui_story_5028_50280601_44_dialog_content = "Hmph. No importa cuantos idiotas manden.",
  ui_story_5028_50280601_45_dialog_content = "Mano de obra, armas, perros... Nada de eso les hará ningún bien. Tampoco esas trampas que pusieron por todos los cerros.",
  ui_story_5028_50280601_46_dialog_content = "Un conejo Peko nunca sería atrapado de esta manera.",
  ui_story_5028_50280601_47_dialog_content = "Bueno, si los cazadores profesionales no pueden conseguirlo, ¿cómo vamos a hacerlo nosotros?",
  ui_story_5028_50280601_48_dialog_content = "Relax. ¡No lo olvides, soy un extrozoólogo experimentado!",
  ui_story_5028_50280601_49_dialog_content = "Puedo atrapar un conejo Peko tan fácilmente como chasquear los dedos.",
  ui_story_5028_50280601_50_dialog_content = "Argh... Mis dedos están congelados otra vez.",
  ui_story_5028_50280601_51_dialog_content = "¿Has encontrado el cuaderno? ¿Debería ayudarte a buscar?",
  ui_story_5028_50280601_52_dialog_content = "¡No, gracias! Lo tengo.",
  ui_story_5028_50280601_53_dialog_content = "Están alertas y son inteligentes, lo que los hace difíciles de atrapar. Les gusta comer libros.",
  ui_story_5028_50280601_54_dialog_content = "¡Perfecto! Podemos usar un libro como cebo—",
  ui_story_5028_50280601_55_dialog_content = "Si crees que es tan fácil como lanzar un libro como cebo y capturar uno, deberíamos dejarlo ahora mismo.",
  ui_story_5028_50280601_56_dialog_content = "Finge que no dije nada.",
  ui_story_5028_50280601_57_dialog_content = "Son demasiado mañosos. Un libro tirado en la nieve los hará desconfiar.",
  ui_story_5028_50280601_58_dialog_content = "Pero tal vez podamos usar su curiosidad contra ellos. La hierba es más verde del otro lado y todo eso.",
  ui_story_5028_50280601_59_dialog_content = "¿Cómo podemos hacer eso? Oye, PlayerName, dame ese libro que has estado leyendo últimamente.",
  ui_story_5028_50280601_60_dialog_content = "¿Qué es esto? ¿\"La chica a mi lado a veces oculta sus sentimientos en Eclipsian\"?",
  ui_story_5028_50280601_61_dialog_content = "¿Por qué su título es tan obscenamente largo?",
  ui_story_5028_50280601_62_dialog_content = "Sí. Fue un regalo del Sr. Peng, el hombre de la viña. Él lo escribió.",
  ui_story_5028_50280601_63_dialog_content = "Incluso lo firmó. Dijo que valdría mucho en unos pocos años.",
  ui_story_5028_50280601_64_dialog_content = "Ah, claro. Bueno, prefiero arriesgarme a esto que al cuaderno del Maestro.",
  ui_story_5028_50280601_65_dialog_content = "Suspiro...",
  ui_story_5028_50280601_66_dialog_content = "De alguna manera parece que nos insultaste a mí y al Sr. Peng a pesar de que claramente no dijiste nada...",
  ui_story_5028_50280601_67_dialog_content = "Menos charla, más trabajo. Tenemos que atrapar ese conejo antes de que lo hagan los cazadores.",
  ui_story_5028_50280601_68_dialog_content = "Escóndete, empezaré a leer.",
  ui_story_5028_50280601_69_dialog_content = "Cuando aparezca el Peko, presiona el botón.",
  ui_story_5028_50280601_70_dialog_content = "¿Eso no te atrapará en la red también?",
  ui_story_5028_50280601_71_dialog_content = "¿Y qué? No me morderá.",
  ui_story_5028_50280601_72_dialog_content = "Y si lo hace, te devolveré el mordisco. Más difícil.",
  ui_story_5028_50280601_73_dialog_content = "<color=#e8d9bb>Algún tiempo después</color>",
  ui_story_5028_50280601_74_dialog_content = "¿Peko?",
  ui_story_5028_50280601_75_option_content = "Enlace mental con Fia",
  ui_story_5028_50280601_76_dialog_content = "Viene algo. Quédate quieto.",
  ui_story_5028_50280601_77_dialog_content = "Entiendo. Y no pierdas tu oportunidad.",
  ui_story_5028_50280601_78_dialog_content = "Lo...",
  ui_story_5028_50280601_79_dialog_content = "Peko peko...",
  ui_story_5028_50280601_80_dialog_content = "(Jejeje, eso es todo. Sigue tu curiosidad y ven a mí.)",
  ui_story_5028_50280601_81_dialog_content = "Peko...",
  ui_story_5028_50280601_82_dialog_content = "No es bueno. Esta pequeña bestia sospechosa sigue saltando alrededor del borde de la red, sin querer ir más allá.",
  ui_story_5028_50280601_83_dialog_content = "Si lo activamos ahora, es probable que se escape, y nunca tendremos otra oportunidad como esta.",
  ui_story_5028_50280601_84_dialog_content = "Solo hay una opción. Voy a hacer un agarre para ello. Apoyar, PlayerName.",
  ui_story_5028_50280601_85_dialog_content = "Ahora...",
  ui_story_5028_50280601_86_dialog_content = "¿Peko?",
  ui_story_5028_50280601_87_dialog_content = "¡Congelar!",
  ui_story_5028_50280601_88_dialog_content = "Peko!!",
  ui_story_5028_50280601_89_dialog_content = "¡Te tengo!",
  ui_story_5028_50280601_90_dialog_content = "¡Lo tengo! ¡Lo tengo!",
  ui_story_5028_50280601_91_dialog_content = "Peko peko peko peko!!",
  ui_story_5028_50280601_92_dialog_content = "Guau, le acabas de gritar al conejo Peko y lo aterrorizaste para que se sometiera.",
  ui_story_5028_50280601_93_dialog_content = "No sé si tener esa idea en una fracción de segundo te vuelve inteligente o loco.",
  ui_story_5028_50280601_94_dialog_content = "Jejeje, lo tomaré como un cumplido. Y no te quedes ahí, sácanos a los dos de aquí.",
  ui_story_5028_50280601_95_dialog_content = "Jejeje. Ahora podré completar la prueba final.",
  ui_story_5028_50280601_96_dialog_content = "Pe... Peko...",
  ui_story_5028_50280601_97_dialog_content = "¡Lo!",
  ui_story_5028_50280601_98_dialog_content = "¿Cómo te va a ayudar el conejo Peko con la prueba?",
  ui_story_5028_50280601_99_dialog_content = "Según el cuaderno, los conejos Peko pueden absorber el conocimiento de los libros y luego transferirlo a otros.",
  ui_story_5028_50280601_100_dialog_content = "He llegado a un punto en el que algo así ni siquiera me sorprende. Entonces, ¿cómo funciona esto realmente?",
  ui_story_5028_50280601_101_dialog_content = "Vamos a ver. Primero, prepare el libro que contiene la información que necesita para transferir y enviarlo al Peko.",
  ui_story_5028_50280601_102_dialog_content = "Bueno, supongo que puedo aceptar que eso es normal. Para una bestia maravillosa.",
  ui_story_5028_50280601_103_dialog_content = "¿Y entonces?",
  ui_story_5028_50280601_104_dialog_content = "Luego... calentar un poco de aceite en una sartén... agregar la cebolla, el jengibre y el ajo... freír hasta que estén fragantes...",
  ui_story_5028_50280601_105_dialog_content = "?",
  ui_story_5028_50280601_106_dialog_content = "Peko!!",
  ui_story_5028_50280601_107_dialog_content = "!!",
  ui_story_5028_50280601_108_dialog_content = "Agregue un poco de azúcar y cocine hasta que se caramelice. Luego despellejar...",
  ui_story_5028_50280601_109_dialog_content = "¿Me estás diciendo que se supone que debemos estofarlo?",
  ui_story_5028_50280601_110_dialog_content = "Suena así... pero... ¿cómo es eso siquiera? ¡Ese estúpido!",
  ui_story_5028_50280601_111_dialog_content = "¿Quizás comer solo una pierna funcionaría?",
  ui_story_5028_50280601_112_dialog_content = "Peko peko peko!",
  ui_story_5028_50280601_113_dialog_content = "No hagas bromas así, el Peko ya está aterrorizado.",
  ui_story_5028_50280601_114_dialog_content = "Espera, creo que está tratando de advertirnos de algo.",
  ui_story_5028_50280601_115_dialog_content = "¿De que? Les dimos a los cazadores el deslizamiento.",
  ui_story_5028_50280601_116_dialog_content = "esta diciendo... <color=#FFB400>¡Eclipsitos!</color>",
  ui_story_5028_50280602_1_dialog_content = "¡Cada vez! ¡Estas plagas!",
  ui_story_5028_50280602_2_dialog_content = "¿Por qué están en todas partes? Debería reconsiderar mi carrera. Sería mucho más fácil ser eclipsitólogo.",
  ui_story_5028_50280602_3_dialog_content = "Gracias a Dios que nos advirtió, o estaríamos rodeados.",
  ui_story_5028_50280602_4_dialog_content = "Peko peko!",
  ui_story_5028_50280602_5_dialog_content = "Bueno, definitivamente no podemos comerlo. Entonces, ¿qué hay de tu juicio?",
  ui_story_5028_50280602_6_dialog_content = "Tendré que pensar en otra cosa. No sería un gran extrozoólogo si dañara a las bestias maravillosas para mi propio beneficio.",
  ui_story_5028_50280602_7_dialog_content = "Nunca lo haría, incluso si eso significa nunca completar mi prueba.",
  ui_story_5028_50280602_8_dialog_content = "Ah, pero ¿qué voy a hacer?",
  ui_story_5028_50280602_9_dialog_content = "Peko...",
  ui_story_5028_50280602_10_dialog_content = "Lo...",
  ui_story_5028_50280602_11_dialog_content = "gloo...",
  ui_story_5028_50280602_12_dialog_content = "Gracias por consolarme.",
  ui_story_5028_50280602_13_dialog_content = "Tiene que haber alguna otra manera.",
  ui_story_5028_50280602_14_dialog_content = "Debe haber una forma de que nos ayude sin que le hagamos daño.",
  ui_story_5028_50280602_15_dialog_content = "¡Lo se!",
  ui_story_5028_50280602_16_dialog_content = "Peko, ¿quieres escuchar mi plan perfecto?",
  ui_story_5028_50280602_17_dialog_content = "Peko!",
  ui_story_5028_50280602_17X1_dialog_content = "¡Agh!",
  ui_story_5028_50280602_18_dialog_content = "¿Hmm? Se está acurrucando contra ti en felicidad.",
  ui_story_5028_50280602_19_dialog_content = "Jejeje! ¡Esa es mi afinidad con los animales!",
  ui_story_5028_50280602_19X1_dialog_content = "Está bien, está bien... Entonces, ¿cuál es tu plan?",
  ui_story_5028_50280602_19X2_dialog_content = "Sería difícil para otros, pero es pan comido para mí.",
  ui_story_5028_50280602_19X3_dialog_content = "¿Recuerda? Puedo entender bestias maravillosas.",
  ui_story_5028_50280602_19X4_dialog_content = "Entonces, todo lo que tengo que hacer es esconder a Peko en mi regazo o en mi bolsillo durante el juicio.",
  ui_story_5028_50280602_19X5_dialog_content = "¡Puede susurrarme las respuestas!",
  ui_story_5028_50280602_19X6_dialog_content = "¡De esta manera, pasaré la prueba y sorprenderé a mi estúpido maestro!",
  ui_story_5028_50280602_19X7_dialog_content = "Podría realmente ser tan simple? Realmente no lo compro...",
  ui_story_5028_50280602_20_dialog_content = "Peko peko!",
  ui_story_5028_50280602_20X1_dialog_content = "¿Puedes esconderte dentro de mi bolsillo...",
  ui_story_5028_50280602_20X2_dialog_content = "¿Y decirme las respuestas correctas en secreto?",
  ui_story_5028_50280602_20X3_dialog_content = "¡Peko-Peko!",
  ui_story_5028_50280602_20X4_dialog_content = "Jejeje! ¡Excelente!",
  ui_story_5028_50280602_21_dialog_content = "¡Ayudará y quiere viajar con nosotros!",
  ui_story_5028_50280602_22_dialog_content = "Peko!",
  ui_story_5028_50280602_22X1_dialog_content = "¡Esto es perfecto! ¡Ahora podemos volver con mi amo!",
  ui_story_5028_50280602_23_dialog_content = "Quiero decir, prácticamente ya tenemos un zoológico entero siguiéndonos. Estoy seguro de que uno más no hará daño.",
  ui_story_5028_50280602_24_dialog_content = "Jejeje... Eres una persona de muy buen corazón, PlayerName.",
  ui_story_5028_50280602_25_dialog_content = "¿Qué? ¿Dices que eres un conejo Peko afortunado porque fuiste rescatado de las garras de un monstruo aterrador en el pasado?",
  ui_story_5028_50280602_26_dialog_content = "¡Eso es increíble! Estoy seguro de que vas a ser todo un amuleto de la suerte para nuestro viaje. ¡Contamos contigo!",
  ui_story_5028_50280602_27_dialog_content = "Peko!",
  ui_story_5028_50280602_28_dialog_content = "Revy! ¡Cobrar!",
  ui_story_5028_50280602_29_dialog_content = "<color=#e8d9bb>¡Bang, bang!</color>",
  ui_story_5028_50280602_30_dialog_content = "¡Quémalo todo! Mantícora!",
  ui_story_5028_50280602_31_dialog_content = "¡L-Vamos a salir de aquí! ¡Estos tipos están locos!",
  ui_story_5028_50280602_32_dialog_content = "¡Escuchen! el-el <color=#FFB400>Látigo de hierro</color> y nuestro jefe <color=#FFB400>Gary</color> ¡Nunca te perdonaré por esto!",
  ui_story_5028_50280602_33_dialog_content = "Huyeron.",
  ui_story_5028_50280602_34_dialog_content = "Vinimos en busca de un Caelestite, pero todo lo que encontramos fue una banda de cazadores violentos...",
  ui_story_5028_50280602_35_dialog_content = "¿Qué estaban buscando aquí? Me pregunto si tiene que ver con PlayerNameel predicamento?",
  ui_story_5028_50280602_36_dialog_content = "Tch... Debería haber agarrado e interrogado a uno de ellos mientras teníamos la oportunidad.",
  ui_story_5028_50280602_37_dialog_content = "¡Yoohoo! ¿no es así? PlayerName¿los amigos?",
  ui_story_5028_50280602_38_dialog_content = "¿Lola? ¿Qué estás haciendo acá?",
  ui_story_5028_50280602_39_dialog_content = "Estaba entregando el correo cuando escuché disparos, así que vine a investigar. ¿Alguno de ustedes está herido?",
  ui_story_5028_50280602_40_dialog_content = "Estábamos buscando al Caelestita cuando un grupo de cazadores nos atacó nada más verlo.",
  ui_story_5028_50280602_41_dialog_content = "Sin víctimas. Los cazadores se han ido hace mucho tiempo.",
  ui_story_5028_50280602_42_dialog_content = "¿Eh? ¿Dijiste \"la Caelestita\"? Esto significa PlayerName ha desaparecido?",
  ui_story_5028_50280602_43_dialog_content = "Espera, ahora que lo mencionas... ¡Creo que vi señales de un campamento improvisado en mi camino hacia aquí! ¿Tal vez podamos encontrar algunas pistas allí?",
  ui_story_5028_50280602_44_dialog_content = "Déjame llevarte allí primero, luego seguiré mi camino.",
  ui_story_5028_50280602_45_dialog_content = "¿Por qué parece que nos hemos convertido en una especie de grupo turístico?",
  ui_story_5028_50280602_46_dialog_content = "¿No es más divertido así? Tomando todo tipo de vistas, pateando el trasero de todo tipo de enemigos...",
  ui_story_5028_50280602_47_dialog_content = "Oh sí, son unas verdaderas vacaciones...",
  ui_story_5028_50280701_1_dialog_content = "Prueba: resiste la tentación más dulce",
  ui_story_5028_50280701_2_dialog_content = "Nubes del blanco más suave, y verdes ramas tiernas ♪",
  ui_story_5028_50280701_3_dialog_content = "Fia y sus amigos marchan hacia lugares nunca antes vistos ♫",
  ui_story_5028_50280701_4_dialog_content = "Con un Caelestite a cuestas, el mundo está bastante sereno ♪",
  ui_story_5028_50280701_5_dialog_content = "Lo, lo, lo ♫",
  ui_story_5028_50280701_6_dialog_content = "Parece que estás de muy buen humor.",
  ui_story_5028_50280701_7_dialog_content = "¡Jejeje! ¡Nunca pensé que estaríamos a un paso de completar todas las pruebas tan rápido!",
  ui_story_5028_50280701_8_dialog_content = "Y todo es gracias a ti, PlayerName! ¡Tú, Kyllo y los demás son la razón por la que todo ha ido tan bien!",
  ui_story_5028_50280701_9_dialog_content = "Estoy igual de sorprendido.",
  ui_story_5028_50280701_10_dialog_content = "Al principio, pensé que no serías capaz de manejar muchas dificultades y que te rendirías rápidamente para que yo me liberara de las garras de esta misión abandonada por Dios.",
  ui_story_5028_50280701_11_dialog_content = "Apuesto a que nunca imaginaste que me apasionarían tanto las bestias maravillosas, ¿eh?",
  ui_story_5028_50280701_12_dialog_content = "Ahora, si pudiéramos hacer algo con la forma beligerante en que hablas con la gente...",
  ui_story_5028_50280701_13_dialog_content = "No no. Esa es mi peculiaridad especial, ¡sin ella perdería tanto carisma!",
  ui_story_5028_50280701_14_dialog_content = "Tiene sentido, supongo. Eso es parte de lo que te hace, bueno... tú.",
  ui_story_5028_50280701_15_dialog_content = "¡Jejeje!",
  ui_story_5028_50280701_16_dialog_content = "(De hecho, sé que debajo de su exterior, Fia es una persona amable y gentil de corazón).",
  ui_story_5028_50280701_16X_dialog_content = "(Estas pequeñas criaturas también lo saben).",
  ui_story_5028_50280701_17_dialog_content = "(Por simples que sean, son lo suficientemente inteligentes como para distinguir lo real de lo falso... y la amabilidad de la crueldad).",
  ui_story_5028_50280701_18_dialog_content = "(Su estrecha relación es prueba suficiente de que Fia es una niña dulce y considerada).",
  ui_story_5028_50280701_19_dialog_content = "... ¿eh? ¿Por qué te distraes?",
  ui_story_5028_50280701_20_dialog_content = "¿Tienes sed? Toma, toma un poco de mi agua.",
  ui_story_5028_50280701_21_dialog_content = "Deberíamos estar a medio día a pie de la casa de mi amo. Sólo aguanta un poco más.",
  ui_story_5028_50280701_22_dialog_content = "¡Vaya! N-No gracias, no tengo sed.",
  ui_story_5028_50280701_23_dialog_content = "Me preguntaba... ¿Qué planeas hacer una vez que finalice tu aprendizaje?",
  ui_story_5028_50280701_24_dialog_content = "Planes futuros, ¿eh? Creo que viajaré por todo el mundo y aprenderé todo lo que pueda sobre bestias maravillosas. ¡Después de eso, debería ser capaz de escribir un libro que eclipsará el trabajo de mi maestro!",
  ui_story_5028_50280701_25_dialog_content = "Eso definitivamente suena como tú, está bien...",
  ui_story_5028_50280701_26_dialog_content = "¡Jejeje! ¿Cuáles son tus planes? PlayerName?",
  ui_story_5028_50280701_27_dialog_content = "Averigua qué hacer con el Drakolion, supongo.",
  ui_story_5028_50280701_28_dialog_content = "No quiero tener que lidiar con un enorme dragón volador por el resto de mi vida, ¿sabes?",
  ui_story_5028_50280701_29_dialog_content = "Relájate, te ayudaré a resolver las cosas.",
  ui_story_5028_50280701_30_dialog_content = "El Drakolion probablemente liberará al Coloso después de que termine su temporada de apareamiento.",
  ui_story_5028_50280701_31_dialog_content = "Seguro espero eso.",
  ui_story_5028_50280701_32_dialog_content = "Soroz ha estado volando en círculos sobre nosotros todo este tiempo. Debe estar agotado.",
  ui_story_5028_50280701_33_dialog_content = "Confía en mí, ¡tengo la ciencia y los conocimientos para respaldar mis teorías!",
  ui_story_5028_50280701_34_dialog_content = "¡Lo!",
  ui_story_5028_50280701_35_dialog_content = "Bien bien.",
  ui_story_5028_50280701_36_dialog_content = "... ¿Eh? ¿Que es eso?",
  ui_story_5028_50280701_37_dialog_content = "Se ve como un <color=#FFB400>estatua</color> De algún tipo.",
  ui_story_5028_50280701_38_dialog_content = "Creo que nunca antes había visto una estatua como esta.",
  ui_story_5028_50280701_39_dialog_content = "(Qué extraño... Esta estatua me llena de una poderosa sensación de comodidad y familiaridad).",
  ui_story_5028_50280701_40_dialog_content = "Er... ¿Crees que deberíamos ir a ofrecer una oración, o algo así? Podemos pedir que te bendiga con un final tranquilo para tus pruebas.",
  ui_story_5028_50280701_41_dialog_content = "Supongo que no estaría de más... ¡Vamos!",
  ui_story_5028_50280701_42_dialog_content = "(A medida que nos acercamos a la estatua, esa vertiginosa sensación de comodidad se vuelve más abrumadora).",
  ui_story_5028_50280701_43_dialog_content = "Puede que no sepa tu nombre, pero por favor... Concédeme tu bendición, para que pueda completar mis pruebas y convertirme en un verdadero extrozoólogo.",
  ui_story_5028_50280701_44_dialog_content = "Y por favor bendice al Drakolion con un nuevo amor, para que Soroz finalmente pueda regresar a PlayerNamelado de",
  ui_story_5028_50280701_45_dialog_content = "Y también bendice a Kyllo...",
  ui_story_5028_50280701_46_dialog_content = "Por favor.",
  ui_story_5028_50280701_47_dialog_content = "...",
  ui_story_5028_50280701_48_dialog_content = "¿Eh? Espera... Algo no se siente bien.",
  ui_story_5028_50280701_49_dialog_content = "¡Felicidades, Fía!",
  ui_story_5028_50280701_50_dialog_content = "¡Felicitaciones por completar sus ensayos y convertirse en el mejor extrozoólogo del mundo!",
  ui_story_5028_50280701_51_dialog_content = "Eh...? ¡¿Maestro?! ¿Soy el más grande?",
  ui_story_5028_50280701_52_dialog_content = "¡Así es! Ahora por favor tome asiento.",
  ui_story_5028_50280701_53_dialog_content = "Mis logros palidecen en comparación con los tuyos, Fia. Cuando se trata de bestias maravillosas, ¡nadie más en el mundo se acerca a saber tanto como tú!",
  ui_story_5028_50280701_54_dialog_content = "¡La diferencia entre nosotros es como el día y la noche! ¡Solo espero que encuentres en tu corazón aceptarme como tu aprendiz, para que pueda aprender todo lo que pueda de ti!",
  ui_story_5028_50280701_55_dialog_content = "Jejeje... No soy TAN genial, ¡pero lo pensaré!",
  ui_story_5028_50280701_56_dialog_content = "Señorita Fía.",
  ui_story_5028_50280701_57_dialog_content = "¿Eh? ¿Quién eres tú?",
  ui_story_5028_50280701_58_dialog_content = "Tus grandes hazañas son conocidas en toda la tierra, y yo soy uno de tus seguidores.",
  ui_story_5028_50280701_59_dialog_content = "Tus seguidores están listos para ayudarte y apoyarte en tu próxima aventura.",
  ui_story_5028_50280701_60_dialog_content = "¡Fia! ¡Fia! ¡Fia!",
  ui_story_5028_50280701_61_dialog_content = "¡Guau! ¿Son todos mis fans?",
  ui_story_5028_50280701_62_dialog_content = "Jeje! Supongo que, naturalmente, los grandes logros atraen admiradores como imanes.",
  ui_story_5028_50280701_63_dialog_content = "Espera... Creo que me olvidé de alguien importante.",
  ui_story_5028_50280701_64_dialog_content = "PlayerName! donde esta PlayerName?",
  ui_story_5028_50280701_65_dialog_content = "<color=#e8d9bb>Mientras tanto...</color>",
  ui_story_5028_50280701_66_dialog_content = "Eh... ¿Por qué estoy de vuelta en el Coloso? ¿Dónde estoy?",
  ui_story_5028_50280701_67_dialog_content = "¡Tanto Lumamber! ¡Esto es genial! No estoy soñando, ¿verdad?",
  ui_story_5028_50280701_68_dialog_content = "¡Ah! Lo que sea. ¡Voy a reclutar aurorianos con Lumamber ahora mismo! ¡Déjame empezar con 100 tirones!",
  ui_story_5028_50280701_69_dialog_content = "<color=#e8d9bb>Golpear-!</color>",
  ui_story_5028_50280701_70_dialog_content = "<color=#e8d9bb>Chunda chunda-!</color>",
  ui_story_5028_50280701_71_dialog_content = "¿Hmm? ¿Alguien está peleando...?",
  ui_story_5028_50280701_72_dialog_content = "¡Despierta, idiota!",
  ui_story_5028_50280701_73_dialog_content = "¿Por qué escucho que alguien me regaña?",
  ui_story_5028_50280701_74_dialog_content = "¡J-Solo diez tirones más!",
  ui_story_5028_50280701_75_dialog_content = "¡Graagh!",
  ui_story_5028_50280701_76_dialog_content = "¡Ahh!",
  ui_story_5028_50280701_77_dialog_content = "¡¿E-Eclipsites?!",
  ui_story_5028_50280701_78_dialog_content = "¿Q-Qué está pasando?",
  ui_story_5028_50280701_79_dialog_content = "F-Fia? Dónde estamos...? ¿Y de dónde vienen estos eclipses? ¡¿Y quien eres tu?!",
  ui_story_5028_50280701_80_dialog_content = "¡Deja de balbucear y levántate y lucha!",
  ui_story_5028_50280701_81_dialog_content = "<size=45>Graaagh!</size>",
  ui_story_5028_50280701_82_dialog_content = "¡Fia!",
  ui_story_5028_50280701_83_dialog_content = "G-Entendido! PlayerName, ¡hagámoslo! Kyllo!",
  ui_story_5028_50280702_1_dialog_content = "No puedo creer que nos hayan atacado los eclipses.",
  ui_story_5028_50280702_2_dialog_content = "¿Pero cómo? Lo último que recuerdo fue rezarle a esa estatua.",
  ui_story_5028_50280702_3_dialog_content = "Entonces, de repente... soñé que me convertía en el mejor extrozoólogo del mundo.",
  ui_story_5028_50280702_4_dialog_content = "Sí, lo mismo aquí... Solo que yo estaba soñando con brillantes montones de púrpura y oro...",
  ui_story_5028_50280702_5_dialog_content = "Y luego, muchos Aurorianos que he conocido llegaron a mi lado, e incluso me hice muy amigo de algunos que ya no están con nosotros.",
  ui_story_5028_50280702_6_dialog_content = "Ustedes dos realmente tienen algunas fantasías interesantes...",
  ui_story_5028_50280702_7_dialog_content = "Dijiste que estabas rezando a una estatua antes, ¿verdad?",
  ui_story_5028_50280702_8_dialog_content = "¿Sí, por qué?",
  ui_story_5028_50280702_9_dialog_content = "Rezaste a un ídolo extraño... ¿Y ni siquiera sabías qué era?",
  ui_story_5028_50280702_10_dialog_content = "Si realmente eres tan ajeno al peligro, puedes olvidarte de convertirte en un extrozoólogo.",
  ui_story_5028_50280702_11_dialog_content = "Todavía estás a tiempo de recibir la educación obligatoria en Illumina. Al menos podrías conseguir un trabajo en una fábrica de armas en algún lugar después de graduarte.",
  ui_story_5028_50280702_12_dialog_content = "¿¡¿Qué dijiste?!?",
  ui_story_5028_50280702_13_dialog_content = "¡¿Quién diablos te crees que eres, hablándome así?!",
  ui_story_5028_50280702_14_dialog_content = "¡No creas que puedes decir lo que quieras solo porque me ayudaste una vez!",
  ui_story_5028_50280702_15_dialog_content = "¡Listo para atacar, Kyllo!",
  ui_story_5028_50280702_16_dialog_content = "...",
  ui_story_5028_50280702_17_dialog_content = "Kyllo?",
  ui_story_5028_50280702_18_dialog_content = "Esas maravillosas bestias no están con nosotros... No puedo sentirlas en absoluto.",
  ui_story_5028_50280702_19_dialog_content = "Estúpido.",
  ui_story_5028_50280702_20_dialog_content = "No tengo por qué decirte quién soy.",
  ui_story_5028_50280702_21_dialog_content = "Pero puedo decir... Quieres convertirte en un extrozoólogo a pesar de ser tan ingenuo y descuidado.",
  ui_story_5028_50280702_22_dialog_content = "¿Dónde estás, Kyllo? No estás jugando al escondite, ¿verdad?",
  ui_story_5028_50280702_23_dialog_content = "¡Si yo fuera tú, ya lo dejaría!",
  ui_story_5028_50280702_24_dialog_content = "No son juguetes para que juegues como quieras, ni mascotas para que las mimes y mimes.",
  ui_story_5028_50280702_25_dialog_content = "Sin dedicación o determinación, nunca superarás los obstáculos que se te presenten... Ni siquiera llegarás a la mitad del camino antes de que te rompas.",
  ui_story_5028_50280702_26_dialog_content = "Kyllo... Kyllo...",
  ui_story_5028_50280702_27_dialog_content = "Tu inmadurez también dañará a todos los demás, incluidos tus supuestos \"amigos\".",
  ui_story_5028_50280702_28_dialog_content = "T-Tú... Sabes dónde están, ¿no?",
  ui_story_5028_50280702_29_dialog_content = "Por favor, te lo ruego... ¡Dime dónde están Kyllo y los demás!",
  ui_story_5028_50280702_30_dialog_content = "¿No escuchaste nada de lo que acabo de decir, tonto?",
  ui_story_5028_50280702_31_dialog_content = "No hay señales de Kyllo y los demás aquí... O de nuestros suministros y equipo, para el caso.",
  ui_story_5028_50280702_32_dialog_content = "¡Ahora no es el momento de preocuparse por esas cosas! Por favor... ¡Dime dónde están!",
  ui_story_5028_50280702_33_dialog_content = "Mi Maestro me confió a ellos... Son mis amigos más queridos, así que si sabes algo acerca de dónde podrían estar, incluso la más mínima pista... ¡Necesito que me lo digas!",
  ui_story_5028_50280702_34_dialog_content = "... Esa mirada estúpida en tu cara es realmente vergonzosa.",
  ui_story_5028_50280702_35_dialog_content = "Me voy. Puedes quedarte aquí por el resto de tu vida, por lo que a mí respecta.",
  ui_story_5028_50280702_36_dialog_content = "Esos \"amigos\" problemáticos no esperarán todo el día mientras sigues deprimido y sintiendo lástima por ti mismo.",
  ui_story_5028_50280702_37_dialog_content = "Los niños son realmente un dolor...",
  ui_story_5028_50280702_38_dialog_content = "¡Fia!",
  ui_story_5028_50280702_39_dialog_content = "¡Sí!",
  ui_story_5028_50280702_40_dialog_content = "Puede que nuestras cosas se hayan ido, ¡pero lo que más importa ahora es encontrar a Kyllo y a los demás!",
  ui_story_5028_50280702_41_dialog_content = "¡Espera, Fía!",
  ui_story_5028_50280702_42_dialog_content = "Parece que esa chica dejó algo atrás...",
  ui_story_5028_50280702_43_dialog_content = "Es una brújula... Y algún otro equipo esencial para sobrevivir en la naturaleza.",
  ui_story_5028_50280702_44_dialog_content = "No es mi propio equipo, pero parece bastante nuevo... Apuesto a que le pertenece. Debe habérnoslo dejado a propósito.",
  ui_story_5028_50280702_45_dialog_content = "Ella dijo muchas cosas malas en este momento, pero en realidad podría ser una buena persona.",
  ui_story_5028_50280702_46_dialog_content = "¡Sí! Tendré que agradecerle adecuadamente la próxima vez que nos encontremos.",
  ui_story_5028_50280702_47_dialog_content = "Sabes, parece un poco familiar... Siento que la he visto en alguna parte antes.",
  ui_story_5028_50280702_48_dialog_content = "Kyllo!",
  ui_story_5028_50280702_49_dialog_content = "Lo!!!",
  ui_story_5028_50280702_50_dialog_content = "gloo...",
  ui_story_5028_50280702_51_dialog_content = "¡Hiya!",
  ui_story_5028_50280702_52_dialog_content = "Peko!",
  ui_story_5028_50280702_53_dialog_content = "Gracias a Dios... ¡Nos estaban esperando en la estatua todo el tiempo!",
  ui_story_5028_50280702_54_dialog_content = "Pero, ¿qué nos hizo quedarnos dormidos en primer lugar? ¿Y cómo terminamos allí?",
  ui_story_5028_50280702_55_dialog_content = "¡Lo! ¡Lo, lo!",
  ui_story_5028_50280702_56_dialog_content = "Parece que Kyllo está apuntando hacia la estatua...",
  ui_story_5028_50280702_57_dialog_content = "¿Quizás hay algo mal con eso?",
  ui_story_5028_50280702_58_dialog_content = "Ugh...",
  ui_story_5028_50280702_59_dialog_content = "Se... ¡Se movió hace un momento! ¡La estatua se movió!",
  ui_story_5028_50280702_60_dialog_content = "No... ¡Esa cosa no es una estatua!",
  ui_story_5028_50280702_61_dialog_content = "Es un <color=#FFB400>Búho Lutumi</color>, un tipo de bestia maravillosa! Aunque nunca esperé encontrarme con uno aquí...",
  ui_story_5028_50280702_62_dialog_content = "Mi maestro me dijo una vez que son tan raros que es posible que ya se hayan extinguido. Incluso la Enciclopedia Exótica apenas tiene información sobre ellos...",
  ui_story_5028_50280702_63_dialog_content = "Todo lo que sabemos es que pretende ser una estatua y tienta a sus víctimas a adorar en trance.",
  ui_story_5028_50280702_63X_dialog_content = "Una vez que se duermen, Lutumi Owl les roba cualquier objeto de valor que pueda encontrar.",
  ui_story_5028_50280702_64_dialog_content = "Gaah... Graaah...",
  ui_story_5028_50280702_65_dialog_content = "¿Valores? Pero, ¿para qué los necesita?",
  ui_story_5028_50280702_66_dialog_content = "Lo más probable es que se sienta atraído por objetos brillantes como monedas, como muchos otros animales.",
  ui_story_5028_50280702_67_dialog_content = "¡Coo!",
  ui_story_5028_50280702_68_dialog_content = "¡Oh no, se está escapando!",
  ui_story_5028_50280702_69_dialog_content = "¡Lo!",
  ui_story_5028_50280702_70_dialog_content = "¡Buen trabajo, Kylo! ¡No lo dejes escapar!",
  ui_story_5028_50280702_71_dialog_content = "¡Ajá! ¡Entendido!",
  ui_story_5028_50280702_72_dialog_content = "¡Gaaah!",
  ui_story_5028_50280702_73_option_content = "Sacude el búho Lutumi",
  ui_story_5028_50280702_74_dialog_content = "Mirar, PlayerName! ¡Algunas de nuestras cosas cayeron de su cuerpo!",
  ui_story_5028_50280702_75_option_content = "sigue temblando",
  ui_story_5028_50280702_76_dialog_content = "¡Cau cau!",
  ui_story_5028_50280702_77_dialog_content = "<color=#e8d9bb>¡Agitar agitar agitar!</color>",
  ui_story_5028_50280702_78_dialog_content = "¡Gaaah!",
  ui_story_5028_50280702_79_dialog_content = "¡Siguen apareciendo más cosas! Una lata de Illumina, algo de Nightium... ¡Y mira, hasta una piedra preciosa de Northland!",
  ui_story_5028_50280702_80_dialog_content = "Quién sabe cuántas personas han sido víctimas de este tipo a lo largo de los años... Dejemos sus cosas aquí.",
  ui_story_5028_50280702_81_dialog_content = "Jejeje... Muy bien, pájaro travieso, es hora de tomar una decisión.",
  ui_story_5028_50280702_82_dialog_content = "¿Gruñido?",
  ui_story_5028_50280702_83_dialog_content = "¿Quieres que reparta tu castigo aquí y ahora?",
  ui_story_5028_50280702_84_dialog_content = "¡¡Cau cau cau!!",
  ui_story_5028_50280702_85_dialog_content = "¿O abandonarás tus hábitos de ladrón y te unirás a mí en mi viaje?",
  ui_story_5028_50280702_86_dialog_content = "Ugh...",
  ui_story_5028_50280702_87_dialog_content = "¡Gaaah!",
  ui_story_5028_50280702_88_dialog_content = "¡Jejeje, eso pensé! ¡Ahora pongámonos en movimiento!",
  ui_story_5028_50280702_89_dialog_content = "Estamos en camino a ver a mi Maestro. ¡Estoy seguro de que estará encantado de verte y de ver lo lejos que ha llegado su querido aprendiz!",
  ui_story_5028_50280702_90_dialog_content = "Uf...",
  ui_story_5028_50280702_91_dialog_content = "Purr...",
  ui_story_5028_50280702_92_dialog_content = "Zzz... Gram! ¡¡Otro!!",
  ui_story_5028_50280702_93_dialog_content = "¿Nos quedamos dormidos?",
  ui_story_5028_50280702_94_dialog_content = "¡Despierta! ¡Despierta!",
  ui_story_5028_50280702_95_dialog_content = "¡Nos hemos estado enamorando!",
  ui_story_5028_50280702_96_dialog_content = "Je... Parece que a todos nos jodió el truco de esa estúpida estatua.",
  ui_story_5028_50280702_97_dialog_content = "Seguía diciendo que no deberíamos haberle rezado, pero nooo...",
  ui_story_5028_50280702_98_dialog_content = "El romance es una tontería. ¿Estás empezando a delirar por la vejez o algo así?",
  ui_story_5028_50280702_99_dialog_content = "Solo mira esto... Todas nuestras cosas se han ido.",
  ui_story_5028_50280702_100_dialog_content = "¡¿De qué estás hablando?! Solo recé para vencerte algún día...",
  ui_story_5028_50280702_101_dialog_content = "Si tienes tiempo para burlarte de mí, ¿por qué no lo usas para encontrar nuestro equipo perdido?",
  ui_story_5028_50280702_102_dialog_content = "¿Dónde está esa estatua que necesita una patada en el culo?",
  ui_story_5028_50280702_103_dialog_content = "¿Se fue?",
  ui_story_5028_50280702_104_dialog_content = "Espera, veo algo allí.",
  ui_story_5028_50280702_105_dialog_content = "Oye, Smokey... ¿No es esta tu púa de guitarra de metal?",
  ui_story_5028_50280702_106_dialog_content = "Eso es todo. Er, quiero decir... ¡En realidad es un abridor de botellas!",
  ui_story_5028_50280702_107_dialog_content = "¿Está todo lo demás aquí?",
  ui_story_5028_50280702_108_dialog_content = "Las cosas están aquí. La estatua no lo es.",
  ui_story_5028_50280702_109_dialog_content = "Además... Huelo Caelestita.",
  ui_story_5028_50280801_1_dialog_content = "¡Oh, maaaasterrrr! ¿Adivina quién ha vuelto?",
  ui_story_5028_50280801_2_dialog_content = "¡Tomó algo de tiempo, pero finalmente completé tus locas pruebas!",
  ui_story_5028_50280801_X2_dialog_content = "Pero a pesar de lo que me dijiste, Kyllo nunca \"evolucionó\". ¿Que pasa con eso?",
  ui_story_5028_50280801_3_dialog_content = "Perdonanos...",
  ui_story_5028_50280801_4_dialog_content = "(¡Este lugar... está terriblemente desordenado!)",
  ui_story_5028_50280801_5_dialog_content = "(Todos estos libros quedaron esparcidos por todo el lugar... ¡¿Su Maestro no sabe cómo recoger lo que ensucia?!)",
  ui_story_5028_50280801_6_dialog_content = "Entonces, ¿qué dices, Maestro? ¿Mi aprendizaje finalmente está completo, o...?",
  ui_story_5028_50280801_7_dialog_content = "¿Que pasó aquí? ¡Que desastre!",
  ui_story_5028_50280801_8_dialog_content = "Oh... ¿Quieres decir que no siempre es así?",
  ui_story_5028_50280801_9_dialog_content = "No... quiero decir, sus líos tienen cierto orden.",
  ui_story_5028_50280801_10_dialog_content = "Lo que puede parecer una pila aleatoria de libros es en realidad una selección cuidadosamente ordenada de información valiosa.",
  ui_story_5028_50280801_11_dialog_content = "Clasifica todos los libros en montones según sus categorías.",
  ui_story_5028_50280801_12_dialog_content = "También tiende a dejar los libros que no ha terminado de leer bien abiertos en la parte superior de las pilas. Por eso parecen desorganizados.",
  ui_story_5028_50280801_13_dialog_content = "¡Pero mira! La categoría de esta pila es Entomología, pero los dos primeros libros tratan sobre criaturas acuáticas.",
  ui_story_5028_50280801_14_dialog_content = "Mi maestro calvo de mediana edad puede no parecer muy confiable, ¡pero nunca extraviaría sus libros de esta manera!",
  ui_story_5028_50280801_15_dialog_content = "¿Eso significa que... alguien más estaba aquí, jugando con los libros de Vic?",
  ui_story_5028_50280801_16_dialog_content = "Es muy posible... ¡Pero la prioridad es encontrarlo de inmediato!",
  ui_story_5028_50280801_17_dialog_content = "¡Maestro! ¡¿Adónde te escapaste esta vez?! ¡Ven afuera!",
  ui_story_5028_50280801_18_dialog_content = "<size=45>¡¿Hola?!</size>",
  ui_story_5028_50280801_19_option_content = "Vic!",
  ui_story_5028_50280801_20_dialog_content = "...",
  ui_story_5028_50280801_21_dialog_content = "no creo que este aqui...",
  ui_story_5028_50280801_22_dialog_content = "Los cajones han sido sacados y su silla está fuera de lugar... Y las puertas del armario, que explícitamente me prohíbe incluso tocar... están abiertas.",
  ui_story_5028_50280801_23_dialog_content = "Parece que Vic se fue a toda prisa.",
  ui_story_5028_50280801_24_dialog_content = "Y la habitación está en total desorden. no me digas...",
  ui_story_5028_50280801_25_dialog_content = "Me temo que tienes razón en esto. Vic puede haber sido secuestrado...",
  ui_story_5028_50280801_26_dialog_content = "¡Debe haber estado mintiéndome todo este tiempo, así que se escapó en lugar de esperar a que yo regresara!",
  ui_story_5028_50280801_27_dialog_content = "¿Eh?",
  ui_story_5028_50280801_28_dialog_content = "¡No puede haber otra explicación!",
  ui_story_5028_50280801_29_dialog_content = "¿N-No crees que al menos deberíamos considerar la posibilidad de que haya sido secuestrado?",
  ui_story_5028_50280801_30_dialog_content = "¡¿Qué?!",
  ui_story_5028_50280801_31_dialog_content = "¿Eh? Eh... ¡P-Por supuesto! ¡Ya lo había pensado!",
  ui_story_5028_50280801_32_dialog_content = "Es solo que... Realmente no puedo pensar en nadie que quisiera secuestrar a alguien como mi Maestro, ¿sabes?",
  ui_story_5028_50280801_33_dialog_content = "Inestable como es, bebe como un pez, y ni siquiera tiene dos Nightium para frotar en su billetera...",
  ui_story_5028_50280801_34_dialog_content = "Uh... ¿Realmente deberías estar hablando de él así? Él es tu Maestro, después de todo...",
  ui_story_5028_50280801_35_dialog_content = "De todos modos, ¿qué crees que deberíamos hacer ahora?",
  ui_story_5028_50280801_36_dialog_content = "Bueno, si no encontramos a mi maestro, nunca podré graduarme como extrozoólogo de pleno derecho.",
  ui_story_5028_50280801_37_dialog_content = "Así que supongo que deberíamos empezar buscándolo.",
  ui_story_5028_50280801_38_dialog_content = "Entonces busquemos en el área cualquier pista que nos pueda señalar en la dirección de Vic.",
  ui_story_5028_50280801_39_dialog_content = "Hmph. El Maestro realmente debe disfrutar haciendo que otras personas se preocupen.",
  ui_story_5028_50280801_40_dialog_content = "¡Bien entonces! ¡Hora de buscar pistas!",
  ui_story_5028_50280801_41_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_5028_50280801_42_dialog_content = "<color=#e8d9bb>¡Pam! ¡Aplastar!</color>",
  ui_story_5028_50280801_43_dialog_content = "¡Pará pará pará!",
  ui_story_5028_50280801_44_dialog_content = "¿Llamas a esto \"búsqueda de pistas\"? ¡Prácticamente estás demoliendo la escena del crimen!",
  ui_story_5028_50280801_45_dialog_content = "¡Acabo de derribar algunas cosas, eso es todo! ¡Te juro que busco lo más que puedo!",
  ui_story_5028_50280801_46_dialog_content = "A este ritmo, tu \"mirada\" nos va a hacer caer la casa sobre la cabeza...",
  ui_story_5028_50280801_47_dialog_content = "¡No soy tan imprudente!",
  ui_story_5028_50280801_48_dialog_content = "Hmm... Déjame encargarme de esto.",
  ui_story_5028_50280801_49_dialog_content = "De lo contrario, la casa, así como las pistas, serían destruidas.",
  ui_story_5028_50280801_50_dialog_content = "¡Por qué tú...!",
  ui_story_5028_50280801_51_dialog_content = "Y al final tendríamos un día bastante ajetreado.",
  ui_story_5028_50280801_52_dialog_content = "Ahora, ¿dónde debo comenzar mi búsqueda?",
  ui_story_5028_50280801_53_option_content = "inspeccionar el escritorio",
  ui_story_5028_50280801_54_dialog_content = "Todos sus cajones han sido sacados. Parece que alguien rebuscó apresuradamente en su contenido...",
  ui_story_5028_50280801_55_dialog_content = "Mi maestro suele tirar cosas en los cajones, pero los cajones tienen categorías, al igual que sus libros.",
  ui_story_5028_50280801_56_dialog_content = "¿Qué se supone que contiene este cajón vacío?",
  ui_story_5028_50280801_57_dialog_content = "Déjame pensar... Parecía tener algunas notas sobre bestias maravillosas allí.",
  ui_story_5028_50280801_58_dialog_content = "Cuando mi Maestro me confió por primera vez a Kyllo, sacó esas notas y las revisó antes de tomar su decisión final.",
  ui_story_5028_50280801_59_dialog_content = "Solo que no veo sus notas por ningún lado...",
  ui_story_5028_50280801_60_dialog_content = "¡Espera, hay un trozo de papel debajo del escritorio!",
  ui_story_5028_50280801_61_dialog_content = "¡Muéstrame!",
  ui_story_5028_50280801_62_dialog_content = "Es un dibujo de un círculo con una \"X\" dentro...",
  ui_story_5028_50280801_63_dialog_content = "La letra parece apresurada y la tinta todavía está ligeramente fresca... ¡Esto no puede haber sido escrito hace tanto tiempo!",
  ui_story_5028_50280801_64_dialog_content = "¿Podría ser esto un mensaje secreto de algún tipo?",
  ui_story_5028_50280801_65_dialog_content = "No estoy seguro...",
  ui_story_5028_50280801_66_option_content = "Inspeccionar las estanterías",
  ui_story_5028_50280801_67_dialog_content = "Los libros en este estante están ordenados ordenadamente.",
  ui_story_5028_50280801_68_dialog_content = "Pero eso es porque a mi Maestro realmente no le importa leer estos libros... Y como él no es del tipo que limpia regularmente, todos estos libros tienen una gruesa capa de polvo sobre ellos.",
  ui_story_5028_50280801_69_dialog_content = "¡Mira, ese libro en el estante superior no acumula polvo! Como si lo hubieran leído regularmente...",
  ui_story_5028_50280801_70_dialog_content = "¡Deberíamos echar un vistazo más de cerca!",
  ui_story_5028_50280801_71_dialog_content = "Grr... ¡No puedo llegar hasta allí!",
  ui_story_5028_50280801_72_dialog_content = "¡Ptui!",
  ui_story_5028_50280801_73_dialog_content = "¡No es gracioso! ¡Parar de reír!",
  ui_story_5028_50280801_74_dialog_content = "Si eres tan alto, PlayerName, sólo consígueme eso.",
  ui_story_5028_50280801_75_dialog_content = "Yo-ho! Aquí tienes.",
  ui_story_5028_50280801_76_dialog_content = "¿Mmm? Hay una vieja foto metida entre las páginas de este libro.",
  ui_story_5028_50280801_77_dialog_content = "Parece el Maestro Vic, pero la otra mitad de la foto ha sido arrancada...",
  ui_story_5028_50280801_78_dialog_content = "Debe ser muy importante para mi Maestro si lo ha guardado todo este tiempo.",
  ui_story_5028_50280801_79_dialog_content = "La otra persona en la foto... Me pregunto quién podría ser.",
  ui_story_5028_50280801_80_dialog_content = "Llevamos tanto tiempo buscando que parece que se me van a caer las piernas, pero apenas hemos avanzado...",
  ui_story_5028_50280801_81_dialog_content = "¿Qué hacemos ahora?",
  ui_story_5028_50280801_82_dialog_content = "...",
  ui_story_5028_50280801_83_dialog_content = "¿Eh, Fia...?",
  ui_story_5028_50280801_84_dialog_content = "¿Sientes de repente un escalofrío bajando por tu espalda? Porque lo hago...",
  ui_story_5028_50280801_85_dialog_content = "Yo... yo también lo siento...",
  ui_story_5028_50280801_86_dialog_content = "Acaso...",
  ui_story_5028_50280801_87_dialog_content = "¡Ahhh!",
  ui_story_5028_50280801_88_dialog_content = "¡¡Es ella otra vez!!",
  ui_story_5028_50280801_89_dialog_content = "Una cosa es si has venido a robar el lugar, ya que aquí no hay nada de valor...",
  ui_story_5028_50280801_90_dialog_content = "Pero destrozar la casa así... es absolutamente imperdonable.",
  ui_story_5028_50280801_91_dialog_content = "Será un proceso laborioso organizar todos estos libros...",
  ui_story_5028_50280801_92_dialog_content = "Con las puertas de los gabinetes abiertas, esas colecciones adentro acumularon mucho polvo. Tomará días limpiar este desastre...",
  ui_story_5028_50280801_93_dialog_content = "Lo que es peor, el mapa de las bestias maravillosas y esos preciosos manuscritos, los cuales me tomó años de ardua investigación compilar... ¡no se ven por ninguna parte!",
  ui_story_5028_50280801_94_dialog_content = "¡Sí! ¡No podría estar mas de acuerdo!",
  ui_story_5028_50280801_95_dialog_content = "¡P-Pero no se preocupe, señorita!",
  ui_story_5028_50280801_96_dialog_content = "Haremos todo lo posible para...",
  ui_story_5028_50280801_97_dialog_content = "No.",
  ui_story_5028_50280801_98_dialog_content = "¿Para compensarme? Por favor... ¡Nunca podrías esperar pagar por mis valiosos archivos!",
  ui_story_5028_50280801_99_dialog_content = "¡¿Esperar lo?! ¡Sin embargo, no los robamos!",
  ui_story_5028_50280801_100_dialog_content = "¡Está diciendo la verdad! Vinimos buscando al Maestro Vic, pero está desaparecido... ¡Y la casa estaba así cuando llegamos aquí!",
  ui_story_5028_50280801_101_dialog_content = "Uh, excepto por algunas cosas con las que me topé mientras buscaba pistas: una silla, dos jarrones, tres vasos de vidrio...",
  ui_story_5028_50280801_102_dialog_content = "¡Espera por favor, Fia!",
  ui_story_5028_50280801_103_dialog_content = "Guárdalo. Los atrapé ladrones con las manos en la masa.",
  ui_story_5028_50280801_104_dialog_content = "Inicialmente, pensé que solo eran dos entusiastas normales de las bestias maravillosas... pero ahora sé que no son más que criminales de mala muerte.",
  ui_story_5028_50280801_105_dialog_content = "Solo declárate culpable y paga lo que debes.",
  ui_story_5028_50280801_110_dialog_content = "¿Estás escuchando, matón? ¡Ya te dijimos que no fuimos nosotros!",
  ui_story_5028_50280801_112_dialog_content = "¡¿Ay?!",
  ui_story_5028_50280801_113_dialog_content = "¡¿Q-Qué diablos?! ¡¡No puedes empezar a atacar así aquí!!",
  ui_story_5028_50280801_114_dialog_content = "Yo tampoco quiero pelear contigo. Después de todo, solo mover mis dedos o mis tentáculos es lo suficientemente agotador.",
  ui_story_5028_50280801_X114_dialog_content = "Así que les daré una última oportunidad para que se expliquen.",
  ui_story_5028_50280801_115_dialog_content = "No fuimos nosotros, lo juro—",
  ui_story_5028_50280801_116_dialog_content = "¡Ahhh!",
  ui_story_5028_50280801_117_dialog_content = "<color=#e8d9bb>¡Kaboom!</color>",
  ui_story_5028_50280801_118_dialog_content = "E-Hay un gran agujero donde ese tentáculo golpeó hace un momento...",
  ui_story_5028_50280801_119_dialog_content = "¡Habría estado perdido si eso me golpeara!",
  ui_story_5028_50280801_120_dialog_content = "Así es. Estarías en un mundo de dolor.",
  ui_story_5028_50280801_121_dialog_content = "¡Deténgase, por favor! ¡Realmente no vinimos aquí a robar nada!",
  ui_story_5028_50280801_122_dialog_content = "¡Solo estábamos buscando pistas! ¡Estamos intentando localizar a Vic!",
  ui_story_5028_50280801_123_dialog_content = "Maestro... ¿ha desaparecido? Pero si ustedes dos no son los culpables, ¿quién debería serlo?",
  ui_story_5028_50280801_124_dialog_content = "Nosotros tampoco sabemos...",
  ui_story_5028_50280801_125_dialog_content = "¡Pero logramos encontrar algunas pistas!",
  ui_story_5028_50280801_126_dialog_content = "Pistas, ¿eh? Encontrar pistas podría ser demasiado doloroso, y razonar podría ser un dolor aún mayor. También podrías escupirlo.",
  ui_story_5028_50280801_127_dialog_content = "Así que díganme, ¿qué han encontrado ustedes dos?",
  ui_story_5028_50280801_128_dialog_content = "Shifu dejó esto atrás, un dibujo de un círculo con una \"X\" dentro. ¡Creemos que fue dibujado recientemente!",
  ui_story_5028_50280801_129_dialog_content = "Sí. También encontramos esta fotografía dentro de un libro.",
  ui_story_5028_50280801_130_dialog_content = "Espera... ¿Vic es el Maestro al que te has estado refiriendo todo este tiempo?",
  ui_story_5028_50280801_131_dialog_content = "¡Oh, sí!",
  ui_story_5028_50280801_132_dialog_content = "Sí, estudié con él por un tiempo. Ahora que he terminado con sus pruebas, ¡mi aprendizaje está a punto de completarse!",
  ui_story_5028_50280801_133_dialog_content = "Kyllo aquí está mi prueba: ¡me fue confiada por mi Maestro!",
  ui_story_5028_50280801_134_dialog_content = "Eh... ¿Kyllo?",
  ui_story_5028_50280801_135_dialog_content = "Lo? Lo, lo...",
  ui_story_5028_50280801_136_dialog_content = "¡Ahí tienes! ¿Qué haces durmiendo entre esos libros? ¡Ven afuera!",
  ui_story_5028_50280801_137_dialog_content = "Ese es el Kyllo de Vic exactamente. Y tampoco te ha rechazado...",
  ui_story_5028_50280801_138_dialog_content = "Bueno, ya que está dispuesto a confiar en ti, no tengo muchas razones para seguir dudando de ti.",
  ui_story_5028_50280801_139_dialog_content = "¡Oh, así que AHORA me crees!",
  ui_story_5028_50280801_140_dialog_content = "Por desgracia... Parece que se ha metido en problemas mientras yo estaba buscando bestias maravillosas.",
  ui_story_5028_50280801_141_dialog_content = "El cuidado de los niños es definitivamente la parte más difícil.",
  ui_story_5028_50280801_142_dialog_content = "¡No soy un niño pequeño!",
  ui_story_5028_50280801_143_dialog_content = "¿Quién eres exactamente? ¿Y cómo sabes tanto de mi Maestro?",
  ui_story_5028_50280801_144_dialog_content = "¿Quién soy? Eh, ¿quién soy yo en realidad ...",
  ui_story_5028_50280801_145_dialog_content = "Sé que las relaciones entre las personas pueden ser una verdadera molestia para recordar a veces...",
  ui_story_5028_50280801_146_dialog_content = "En pocas palabras, si Vic es la persona a la que llamas Maestro, entonces eso me convierte más o menos en tu superior.",
  ui_story_5028_50280801_147_dialog_content = "Me llamo <color=#FFB400>Shira</color>.",
  ui_story_5028_50280801_148_dialog_content = "Shira",
  ui_story_5028_50280801_X148_dialog_content = "21 años",
  ui_story_5028_50280801_X149_dialog_content = "La misteriosa niña pulpo",
  ui_story_5028_50280801_149_dialog_content = "¡¿M-Mi mayor?! ¡¿Pero por qué mi Maestro nunca me habló de ti?!",
  ui_story_5028_50280801_150_dialog_content = "Después de todo, nunca explica nada perfectamente claro.",
  ui_story_5028_50280801_151_dialog_content = "A veces, incluso yo tengo problemas para darme cuenta si me miente más de lo que me enseña.",
  ui_story_5028_50280801_152_dialog_content = "Tratar con él puede ser totalmente exasperante a veces.",
  ui_story_5028_50280801_153_dialog_content = "Gracias por todo el trabajo duro.",
  ui_story_5028_50280801_154_dialog_content = "Pero está bien... Ya estoy acostumbrado.",
  ui_story_5028_50280801_155_dialog_content = "Bueno, volvamos al tema que nos ocupa. Todavía no estoy seguro del significado de esta foto.",
  ui_story_5028_50280801_156_dialog_content = "Vic podría haber mencionado algo al respecto antes, pero eso se me olvidó.",
  ui_story_5028_50280801_157_dialog_content = "Oye... ¿No se supone que tienes muy buena memoria o algo así?",
  ui_story_5028_50280801_158_dialog_content = "¿De qué otra manera podrías recordar tanto conocimiento detallado sobre tantas bestias maravillosas?",
  ui_story_5028_50280801_159_dialog_content = "Demasiado doloroso recordar algo irrelevante para las bestias maravillosas.",
  ui_story_5028_50280801_160_dialog_content = "¡Oye!",
  ui_story_5028_50280801_161_dialog_content = "Sin embargo... Sé exactamente lo que significa este símbolo.",
  ui_story_5028_50280801_162_dialog_content = "Es un mensaje oculto dejado por Vic. Significa que ha sido secuestrado.",
  ui_story_5028_50280801_163_dialog_content = "Hay muchos bandidos en el área, por lo que solía dejar símbolos como este para que pudiera ir a buscarlo y rescatarlo.",
  ui_story_5028_50280801_164_dialog_content = "¡Así que realmente ha sido secuestrado!",
  ui_story_5028_50280801_165_dialog_content = "Maldición... Deberían enviar una nota de rescate en cualquier momento, ¿verdad?",
  ui_story_5028_50280801_166_dialog_content = "\"Si alguna vez quieres volver a ver a tu Maestro, trae diez millones de Nightium a la siguiente ubicación...\" Nunca podría permitírmelo...",
  ui_story_5028_50280801_167_dialog_content = "Lo que es peor, si pateaba el balde... ¡Nunca podría graduarme como extrozoólogo!",
  ui_story_5028_50280801_168_dialog_content = "¡¡¡No creo que tus aspiraciones profesionales sean nuestro mayor problema en este momento!!!",
  ui_story_5028_50280801_169_dialog_content = "Aún así... no puedo entenderlo.",
  ui_story_5028_50280801_170_dialog_content = "A Vic le roban muy a menudo, pero está arruinado como una broma.",
  ui_story_5028_50280801_171_dialog_content = "Y por lo general, esos ladrones solo causan un alboroto antes de irse sin nada. En el peor de los casos, podrían maltratarlo por sus problemas.",
  ui_story_5028_50280801_172_dialog_content = "Pero esta vez, parece que alguien irrumpió y lo secuestró...",
  ui_story_5028_50280801_173_dialog_content = "¿Por qué alguien se tomaría todas estas molestias?",
  ui_story_5028_50280801_174_dialog_content = "Después de todo, Vic no podía ofrecer nada de valor más que consumir comida y agua.",
  ui_story_5028_50280801_175_dialog_content = "En este punto, no sé si sentirme mal por tu Maestro o por sus secuestradores...",
  ui_story_5028_50280801_176_dialog_content = "Hmph... Te sugiero que te preocupes más por ti mismo en un momento como este.",
  ui_story_5028_50280801_177_dialog_content = "S-Si tu lo dices...",
  ui_story_5028_50280801_178_dialog_content = "En cuanto a quién pudo haberlo hecho, no me digan...",
  ui_story_5028_50280801_179_dialog_content = "Oh no...",
  ui_story_5028_50280801_180_dialog_content = "¡Hey espera!",
  ui_story_5028_50280801_181_dialog_content = "¿Quién crees que secuestró a mi Maestro? ¡¡¡Oye!!!",
  ui_story_5028_50280801_182_dialog_content = "Increíble... Simplemente se retiró de nuestra vista en un instante.",
  ui_story_5028_50280801_183_dialog_content = "Mi Maestro ha desaparecido, y mi superior se escapó sin decir una palabra más.",
  ui_story_5028_50280801_184_dialog_content = "¡Puaj! ¡¡No entiendo por qué ambos tienen que ser así!!",
  ui_story_5028_50280801_185_dialog_content = "Tratemos de alcanzar a Shira, ¿de acuerdo?",
  ui_story_5028_50280801_186_dialog_content = "Parece que salió corriendo en dirección a la ciudad. Vayamos por ese camino primero.",
  ui_story_5028_50280801_187_dialog_content = "Hay mucha gente en la calle. Alguien debe haber visto en qué dirección se fue.",
  ui_story_5028_50280801_188_dialog_content = "¡Sí!",
  ui_story_5028_50280901_1_dialog_content = "Perdóname, pero ¿viste pasar por aquí a una chica de pelo blanco con tentáculos?",
  ui_story_5028_50280901_4_dialog_content = "Bueno, ¡si no es la pequeña Fia!",
  ui_story_5028_50280901_5_dialog_content = "¿Y quien es este? ¿Un amigo?",
  ui_story_5028_50280901_6_dialog_content = "¿Eh? ¿No es ese el tipo que vendía periódicos?",
  ui_story_5028_50280901_7_dialog_content = "Esto de aquí, es PlayerName, mi compañero.",
  ui_story_5028_50280901_8_dialog_content = "Estamos en medio de una búsqueda ahora mismo. ¿Tienes alguna pista?",
  ui_story_5028_50280901_12_dialog_content = "No sé nada sobre una mujer joven, ¡pero creo que tu amo Vic necesita ayuda!",
  ui_story_5028_50280901_13_dialog_content = "S-Sí, como extrozoólogo profesional, estoy muy al tanto de su desaparición... Lo estamos buscando ahora mismo.",
  ui_story_5028_50280901_14_dialog_content = "Lo sabía.",
  ui_story_5028_50280901_15_dialog_content = "Vi que un hombre alto se lo llevó no hace mucho.",
  ui_story_5028_50280901_16_dialog_content = "Le he contado a la gente de Shadowlord sobre el caso. Me pregunto si hicieron algo al respecto...",
  ui_story_5028_50280901_17_dialog_content = "Un hombre alto, ¿eh? ¿Recuerdas cómo era?",
  ui_story_5028_50280901_18_dialog_content = "Lo siento, pero él estaba de espaldas a mí. Todo lo que pude ver fue que llevaba a tu Maestro fuera de la ciudad en su espalda.",
  ui_story_5028_50280901_19_dialog_content = "Pero recuerdo claramente su atuendo. Muy parecidos a los que usan los bandidos cercanos.",
  ui_story_5028_50280901_20_dialog_content = "¿Bandidos?",
  ui_story_5028_50280901_21_dialog_content = "También somos plenamente conscientes de esta situación. Puedes dejarme el resto ahora.",
  ui_story_5028_50280901_22_dialog_content = "No seas grosera, Fía.",
  ui_story_5028_50280901_23_dialog_content = "En el peor de los casos, pagar al Señor de las Sombras por su ayuda es siempre una opción...",
  ui_story_5028_50280901_24_dialog_content = "No se preocupe, somos más que capaces de manejar esto nosotros mismos.",
  ui_story_5028_50280901_25_dialog_content = "Muy bien entonces. ¡La mejor de las suertes!",
  ui_story_5028_50280901_26_dialog_content = "Por desgracia... Me encantaría llamar para pedir ayuda...",
  ui_story_5028_50280901_27_dialog_content = "Pero mi Maestro no tiene forma de permitírselo...",
  ui_story_5028_50280901_28_dialog_content = "¿Podemos realmente esperar enfrentarnos a esos bandidos solo con nosotros dos?",
  ui_story_5028_50280901_29_dialog_content = "¿Qué quieres decir con \"solo nosotros dos\"?",
  ui_story_5028_50280901_30_dialog_content = "¡No lo olvides, soy un extrozoólogo profesional! ¡Tengo toneladas de bestias maravillosas que pueden prestarnos su fuerza!",
  ui_story_5028_50280901_31_dialog_content = "Peko peko!",
  ui_story_5028_50280901_32_dialog_content = "gloo...",
  ui_story_5028_50280901_33_dialog_content = "Mm-hmm! Ustedes también quieren rescatar a mi Maestro, ¿verdad?",
  ui_story_5028_50280901_34_dialog_content = "¡Con tu ayuda, sé que podemos lograrlo!",
  ui_story_5028_50280901_35_dialog_content = "¡Lo, lo!",
  ui_story_5028_50280901_36_dialog_content = "No puedo entender lo que dices por ahora, pero tienes mi palabra: ¡haré lo que sea necesario para rescatar a mi Maestro!",
  ui_story_5028_50280901_37_dialog_content = "Un misterioso bandido obsesionado con el conocimiento secuestró a Vic a pesar de lo pobre que es...",
  ui_story_5028_50280901_38_dialog_content = "Me pregunto cómo vamos a localizarlos.",
  ui_story_5028_50280901_39_dialog_content = "¿Realmente tendremos que confiar en el Señor de las Sombras para obtener ayuda?",
  ui_story_5028_50280901_40_dialog_content = "Tiene que haber una mejor manera...",
  ui_story_5028_50280901_41_dialog_content = "Déjame pensar.",
  ui_story_5028_50280901_42_dialog_content = "Aparte de sus objetivos, supongo que los bandidos deberían vigilar de cerca a otras bandas.",
  ui_story_5028_50280901_43_dialog_content = "Después de todo, solo les importa su territorio, no la ley.",
  ui_story_5028_50280901_44_dialog_content = "Si logramos poner nuestras manos sobre un bandido, ¡podríamos obtener información sobre el paradero de mi Maestro!",
  ui_story_5028_50280901_45_dialog_content = "¡Suena como un plan! Sólo... ¿Dónde se supone que vamos a encontrar a un bandido?",
  ui_story_5028_50280901_46_dialog_content = "¿Dónde encontrar un bandido, dices?",
  ui_story_5028_50280901_47_dialog_content = "¡Eso es fácil!",
  ui_story_5028_50280901_48_dialog_content = "Tú y yo tenemos que fingir que somos un par de viajeros ricos e ingenuos. PlayerName!",
  ui_story_5028_50280901_49_dialog_content = "Comencemos con...",
  ui_story_5028_50280901_50_dialog_content = "Espera... ¿N-No puedes querer decir...?",
  ui_story_5028_50280901_51_dialog_content = "Nuh-uh! ¡De ninguna manera! ¡De ninguna manera!",
  ui_story_5028_50280901_52_dialog_content = "¡¿Tienes idea de lo duro que he trabajado para juntar tanto Nightium desde que dejé el mundo clandestino?!",
  ui_story_5028_50280901_53_dialog_content = "P-pero PlayerName... ¿No quieres ayudarme a rescatar a mi Maestro?",
  ui_story_5028_50280901_54_dialog_content = "...",
  ui_story_5028_50280901_55_dialog_content = "¿Soportas que nunca me convierta en un extrozoólogo?",
  ui_story_5028_50280901_56_dialog_content = "...",
  ui_story_5028_50280901_57_dialog_content = "Boo-hoo... Está bien... Tendré que encontrar otra manera...",
  ui_story_5028_50280901_58_dialog_content = "¡Salvaré a mi Maestro, solo! Incluso si soy capturado y torturado por esos bandidos, no te pediré ayuda nunca más. PlayerName!",
  ui_story_5028_50280901_X58_dialog_content = "Boohoo!!!",
  ui_story_5028_50280901_X59_dialog_content = "...",
  ui_story_5028_50280901_X60_dialog_content = "¡¡¡Por quéyyyyyy!!!",
  ui_story_5028_50280901_59_dialog_content = "<color=#e8d9bb>Algún tiempo después...</color>",
  ui_story_5028_50280901_60_dialog_content = "Manzanas de caramelo! Taiyaki! ¡Especialidades de la Isla de las Nubes!",
  ui_story_5028_50280901_61_dialog_content = "¡Tú allí! ¿Te sientes un poco hambriento?",
  ui_story_5028_50280901_62_dialog_content = "¿Cómo lo supiste? ¡Tomaremos diez de todo! ¡Su trato!",
  ui_story_5028_50280901_63_dialog_content = "¡S-sí! Yo invito...!",
  ui_story_5028_50280901_64_dialog_content = "¡Sabía que eran chicos tranquilos! ¡Un momento por favor!",
  ui_story_5028_50280901_65_dialog_content = "Guau... ¡Mira todos estos sabrosos bocadillos!",
  ui_story_5028_50280901_66_dialog_content = "(¡¿Por qué acepté ser parte de este estúpido plan?!)",
  ui_story_5028_50280901_67_dialog_content = "(Vice no dejará pasar esto una vez que descubra que gasté tanto dinero...)",
  ui_story_5028_50280901_68_dialog_content = "Om-nom-nom... ¡Delicioso!",
  ui_story_5028_50280901_69_dialog_content = "¡Tendré otro!",
  ui_story_5028_50280901_70_dialog_content = "¡De inmediato, señorita!",
  ui_story_5028_50280901_71_dialog_content = "(Por favor... Ese fue el valor de diez días de pago en este momento...)",
  ui_story_5028_50280901_72_dialog_content = "...",
  ui_story_5028_50280901_73_dialog_content = "(Espera... ¿Esa persona de ahí nos está mirando?)",
  ui_story_5028_50280901_74_dialog_content = "Estamos siendo observados. Creo que finalmente hemos captado la atención de un bandido.",
  ui_story_5028_50280901_75_dialog_content = "Tiempo perfecto. ¡Yo también estoy a punto de terminar de comer bocadillos! Tiempo para el siguiente paso.",
  ui_story_5028_50280901_76_dialog_content = "*Tose*",
  ui_story_5028_50280901_77_dialog_content = "Ah, ¡esos realmente fueron todo un placer! ¿Hacemos algunas compras ahora?",
  ui_story_5028_50280901_78_dialog_content = "Naturalmente, me comprarás lo que mi corazoncito desee, ¿verdad?",
  ui_story_5028_50280901_79_dialog_content = "¡¿E-Es este realmente el siguiente paso?!",
  ui_story_5028_50280901_80_dialog_content = "<size=45>¡¡¡EJEM!!!</size>",
  ui_story_5028_50280901_81_dialog_content = "¡Ay! ¡Está bien, está bien, deja de patearme!",
  ui_story_5028_50280901_82_dialog_content = "¡Yo... lo entiendo! Prometo...",
  ui_story_5028_50280901_83_dialog_content = "¡Te compro todo lo que quieras!",
  ui_story_5028_50280901_84_dialog_content = "Ahora eso es lo que me gusta escuchar!",
  ui_story_5028_50280901_85_dialog_content = "(¡Nunca podré hablar para salir de esto!)",
  ui_story_5028_50280901_86_dialog_content = "(Perdóname, Vice. Me estoy quedando sin dinero... De nuevo...)",
  ui_story_5028_50280901_87_dialog_content = "(Perdóname, Soroz. Falta la cuota de mantenimiento del próximo mes... De nuevo...)",
  ui_story_5028_50280901_88_dialog_content = "...",
  ui_story_5028_50280901_89_dialog_content = "Mira allá. ¿No parece eso PlayerName?",
  ui_story_5028_50280901_90_dialog_content = "Eso no solo se parece a él... ¡ES él!",
  ui_story_5028_50280901_91_dialog_content = "Desafortunadamente, está demasiado lejos para que mi látigo lo alcance. Qué pena...",
  ui_story_5028_50280901_93_dialog_content = "Navegador-!",
  ui_story_5028_50280901_94_dialog_content = "Esperanos-!",
  ui_story_5028_50280901_95_dialog_content = "Es posible que no pueda oírnos desde esta distancia. Después de todo, esta calle es bastante bulliciosa.",
  ui_story_5028_50280901_96_dialog_content = "Entonces deja de balbucear. Solo ponte al día con él.",
  ui_story_5028_50280901_97_dialog_content = "<color=#e8d9bb>fuera de la ciudad</color>",
  ui_story_5028_50280901_98_dialog_content = "(Fia en realidad me está conduciendo hacia las afueras de la ciudad, donde hay menos gente alrededor...)",
  ui_story_5028_50280901_99_dialog_content = "¡Sí, este lugar debería estar bien!",
  ui_story_5028_50280901_100_dialog_content = "Estoy francamente agotado, PlayerName. ¡Detengámonos aquí y descansemos un rato!",
  ui_story_5028_50280901_101_dialog_content = "Er, está bien...",
  ui_story_5028_50280901_102_dialog_content = "¿Pero esto no nos pondrá aún más en peligro?",
  ui_story_5028_50280901_103_dialog_content = "Mientras yo esté aquí, ¿de qué tienes que preocuparte?",
  ui_story_5028_50280901_104_dialog_content = "Ustedes dos parecen estar pasándolo muy bien, ¿eh?",
  ui_story_5028_50280901_105_dialog_content = "¡Ese es el tipo que nos ha estado siguiendo todo este tiempo!",
  ui_story_5028_50280901_106_dialog_content = "Je, si ya te diste cuenta de eso, entonces no perderé más tiempo cortando palabras...",
  ui_story_5028_50280901_107_dialog_content = "¿Por qué no vienen a dar un paseo conmigo dos niños que parecen ricos?",
  ui_story_5028_50280901_108_dialog_content = "Parece que no tenemos elección, PlayerName... Vamos con él por ahora.",
  ui_story_5028_50280901_109_dialog_content = "¡¿Qué?!",
  ui_story_5028_50280901_110_dialog_content = "¿Ves, amigo? Esta niña lo entiende. Ahora coloca tus manos detrás de tu espalda para que podamos atarte bien...",
  ui_story_5028_50280901_111_dialog_content = "(¿Qué diablos está pasando? ¡Necesito saberlo antes de que sea demasiado tarde!)",
  ui_story_5028_50280901_112_option_content = "(¡Fuerza de impulso!)",
  ui_story_5028_50280901_113_dialog_content = "(Fia, ¿puedes oírme? ¡¿Qué está pasando exactamente ahora?!)",
  ui_story_5028_50280901_114_dialog_content = "(¡¡Guau! ¡¡N-No esto otra vez!!)",
  ui_story_5028_50280901_115_dialog_content = "(Cálmate. Solo quiero que me lleven a su escondite).",
  ui_story_5028_50280901_116_dialog_content = "(Esto nos ahorrará una tonelada de tiempo y energía).",
  ui_story_5028_50280901_117_dialog_content = "(¡¿Me estás tomando el pelo?!)",
  ui_story_5028_50280901_118_dialog_content = "(Solo siéntate y disfruta del espectáculo, ¡créeme! Ahora mismo, tenemos que ser un poco pacientes...)",
  ui_story_5028_50280901_119_dialog_content = "¡Hoy es nuestro día de suerte después de todo, muchachos! A pesar de que algunos otros idiotas nos ganaron en nuestra primera marca...",
  ui_story_5028_50280901_120_dialog_content = "¡Nuestros premios de consolación no se ven nada mal! ¡Jajaja!",
  ui_story_5028_50280901_121_dialog_content = "¿Has terminado de atarlos? Bien, ahora vamos...",
  ui_story_5028_50280901_122_dialog_content = "¡Uh!",
  ui_story_5028_50280901_123_dialog_content = "Buscar gente es un verdadero dolor...",
  ui_story_5028_50280901_124_dialog_content = "Nunca desearía quedar atrapado en la caza de bandidos durante mi tiempo de descanso... No hasta que tenga que hacerlo.",
  ui_story_5028_50280901_125_dialog_content = "Shira!? ¿Qué estás haciendo aquí?",
  ui_story_5028_50280901_126_dialog_content = "¿Qué estoy haciendo aquí? ¿Qué estás haciendo aquí?",
  ui_story_5028_50280901_127_dialog_content = "Creí haberte dicho que dejaras de causarme más problemas.",
  ui_story_5028_50280901_128_dialog_content = "Pero aun así te pareció oportuno perseguirme... ¡y ahora estás bromeando con estos bandidos!",
  ui_story_5028_50280901_129_option_content = "¡Estamos siendo secuestrados!",
  ui_story_5028_50280901_130_option_content = "¡Obviamente no es \"hacer payasadas\"!",
  ui_story_5028_50280901_131_dialog_content = "Esto es parte de nuestro plan, ¡pero ahora lo arruinaste!",
  ui_story_5028_50280901_133_dialog_content = "¿Plan? Atornillarlo. Todavía seguiré con lo mío.",
  ui_story_5028_50280901_134_dialog_content = "Solo espero que ustedes dos dejen de interponerse en mi camino.",
  ui_story_5028_50280901_136_dialog_content = "Ugh, ugh... Maldita sea... ¡¿Cómo puede esta chica ser tan poderosa?!",
  ui_story_5028_50280901_137_dialog_content = "¡Vamos, muchachos! ¡Enseñémosle una lección que no olvidará pronto!",
  ui_story_5028_50280901_138_dialog_content = "Tampoco los quiero idiotas en mi camino.",
  ui_story_5028_50280901_139_dialog_content = "Todo lo que quiero escuchar es una respuesta amable y honesta, ¿entiendes?",
  ui_story_5028_50280901_140_dialog_content = "¡Urgh...!",
  ui_story_5028_50280901_141_dialog_content = "Ahora dime... ¿Dónde diablos está Vic?",
  ui_story_5028_50280901_142_dialog_content = "Hazlo breve y dulce, hombre. Ahogarte así es bastante agotador, ¿sabes?",
  ui_story_5028_50280901_143_dialog_content = "Urgh... E-Era <color=#FFB400>Gary</color>... Era él y su banda de cazadores... ¡El Látigo de Hierro!",
  ui_story_5028_50280901_144_dialog_content = "Así que fue él todo el tiempo.",
  ui_story_5028_50280901_145_dialog_content = "Gary? ¿Por qué ese nombre suena tan familiar...?",
  ui_story_5028_50280901_146_dialog_content = "No hay tiempo. Necesitamos atrapar a ese Peko Rabbit pronto para Gary.",
  ui_story_5028_50280901_147_dialog_content = "¡Ahora recuerdo! ¡Escuchamos a esos dos bandidos mencionar a alguien llamado Gary mientras buscábamos un conejo Peko!",
  ui_story_5028_50280901_148_dialog_content = "¿Vaya? ¿En serio? No recuerdo nada de eso en absoluto...",
  ui_story_5028_50280901_149_dialog_content = "Gary... Así que él es el culpable detrás de la disminución del número de bestias maravillosas.",
  ui_story_5028_50280901_150_dialog_content = "¿Conoces a este chico?",
  ui_story_5028_50280901_151_dialog_content = "No hay una manera fácil de decir esto. Además, no tiene nada que ver contigo.",
  ui_story_5028_50280901_152_dialog_content = "¿Dónde se esconde Gary?",
  ui_story_5028_50280901_153_dialog_content = "¡Hay una cueva en la montaña a unas seis millas al norte! Ese es su escondite...",
  ui_story_5028_50280901_154_dialog_content = "¡Uf!",
  ui_story_5028_50280901_155_dialog_content = "Que dolor...",
  ui_story_5028_50280901_156_dialog_content = "¡Oye! ¡No vuelvas a salir corriendo así!",
  ui_story_5028_50280901_157_dialog_content = "Vamos, PlayerName! ¡Después de ella!",
  ui_story_5028_50280901_158_dialog_content = "¡No podemos darnos el lujo de perderla esta vez!",
  ui_story_5028_50280901_159_dialog_content = "¡Cierto, okey!",
  ui_story_5028_50280901_160_dialog_content = "<color=#e8d9bb>Unos minutos después...</color>",
  ui_story_5028_50280901_161_dialog_content = "Todas estas personas han sido noqueadas.",
  ui_story_5028_50280901_162_dialog_content = "¿Eh? Me pregunto por qué estos tipos están tirados por aquí.",
  ui_story_5028_50280901_163_dialog_content = "¿Los reconoces, Smokey?",
  ui_story_5028_50280901_164_dialog_content = "Son solo unos bandidos errantes que aparecieron cerca de Umbraton recientemente. Todos pueden quemarse hasta quedar crujientes, por lo que a mí respecta.",
  ui_story_5028_50280901_165_dialog_content = "Um... Estos signos de batalla aún están muy frescos.",
  ui_story_5028_50280901_166_dialog_content = "Si nos damos prisa, podríamos ser capaces de seguir el ritmo PlayerName.",
  ui_story_5028_50280901_168_dialog_content = "Cojamos el ritmo.",
  ui_story_5028_50280901_169_dialog_content = "Qué podría PlayerName estar a la altura?",
  ui_story_5028_50280901_170_dialog_content = "<color=#e8d9bb>Fuera de la Fortaleza de los Bandidos</color>",
  ui_story_5028_50280901_171_dialog_content = "Este debería ser el lugar.",
  ui_story_5028_50280901_172_dialog_content = "Vaya... Eres muy rápido, ¿sabes?",
  ui_story_5028_50280901_173_dialog_content = "Esa abertura de allí debe ser la entrada a su escondite, ¿verdad?",
  ui_story_5028_50280901_174_dialog_content = "¡E-Espéranos!",
  ui_story_5028_50280901_175_dialog_content = "¡Lo! ¡Lo, lo!",
  ui_story_5028_50280901_176_dialog_content = "¿Por qué estás señalando <color=#FFB400>esa dirección</color>, shira?",
  ui_story_5028_50280901_177_dialog_content = "¿Hay un montón de bestias maravillosas?",
  ui_story_5028_50280901_178_dialog_content = "¿Dónde? ¡Déjame ver!",
  ui_story_5028_50280901_179_dialog_content = "Y no solo bestias maravillosas... ¡También hay muchos eclipses!",
  ui_story_5028_50280901_180_dialog_content = "Graaah-!!",
  ui_story_5028_50280901_181_dialog_content = "¡Oh no, nos han visto!",
  ui_story_5028_50280901_182_dialog_content = "¡Vamos, Kyllo!",
  ui_story_5028_50280901_183_dialog_content = "Ugh... No otra pelea...",
  ui_story_5028_50280902_1_dialog_content = "Kyllo!",
  ui_story_5028_50280902_2_dialog_content = "Lo, lo, lo... ¡Lo!",
  ui_story_5028_50280902_3_dialog_content = "¡Graagh!",
  ui_story_5028_50280902_4_dialog_content = "¡Cuidado con no dañar a ninguna de esas maravillosas bestias!",
  ui_story_5028_50280902_5_dialog_content = "¡Son espectadores inocentes en todo esto!",
  ui_story_5028_50280902_6_dialog_content = "Peko!",
  ui_story_5028_50280902_7_dialog_content = "No tengas miedo, no te haré daño. Ven conmigo.",
  ui_story_5028_50280902_8_dialog_content = "Peko peko!!!",
  ui_story_5028_50280902_9_dialog_content = "¡Oye! ¡¿Por qué lo asustaste así?!",
  ui_story_5028_50280902_10_dialog_content = "¡No estaba tratando de hacerlo! Yo solo...",
  ui_story_5028_50280902_11_dialog_content = "Graaah-!!",
  ui_story_5028_50280902_12_dialog_content = "¡Argh! ¡Que dolor!",
  ui_story_5028_50280902_13_dialog_content = "(¿Shira se ve un poco frustrada...?)",
  ui_story_5028_50280902_14_dialog_content = "(Y parece que las bestias maravillosas no están dispuestas a acercarse a ella. También lo están las que son amigas de Fia...)",
  ui_story_5028_50280902_15_dialog_content = "Bueno, los Eclipsites están todos solucionados. Shira también asusta a esas maravillosas bestias.",
  ui_story_5028_50280902_16_dialog_content = "¡Hmph, ninguno de ellos se enfrentó a Fia, una verdadera extrozoóloga!",
  ui_story_5028_50280902_17_dialog_content = "¿Pero no crees que es extraño? ¿Por qué Gary podía mantener juntos a los eclipses y a las bestias maravillosas?",
  ui_story_5028_50280902_18_dialog_content = "Y era como si estuvieran protegiendo la cueva.",
  ui_story_5028_50280902_X18_dialog_content = "Están entrenados para ser así.",
  ui_story_5028_50280902_19_dialog_content = "Espera... ¿Se puede entrenar a los eclipses como a otras bestias?",
  ui_story_5028_50280902_20_dialog_content = "No estoy seguro, pero hay un rumor de que Gary tiene en sus manos <color=#FFB400>un látigo que puede obligar a las bestias a obedecer sus órdenes</color>.",
  ui_story_5028_50280902_21_dialog_content = "Quizás ese látigo también podría usarse para controlar Eclipsites.",
  ui_story_5028_50280902_22_dialog_content = "Después de todo, usar la violencia para obligar a otros a someterse es una segunda naturaleza para los bandidos.",
  ui_story_5028_50280902_23_dialog_content = "Entonces, ¿esas bestias maravillosas también se vieron obligadas a luchar por ellas?",
  ui_story_5028_50280902_24_dialog_content = "Yo diría que es muy probable que hayan sido sometidos al mismo tipo de \"entrenamiento\".",
  ui_story_5028_50280902_25_dialog_content = "Los bandidos no son eruditos; utilizan los métodos más brutales para llevar a cabo sus planes sin importar los sentimientos de la bestia.",
  ui_story_5028_50280902_26_dialog_content = "Pero, ¿cómo podían ser tan despiadados?",
  ui_story_5028_50280902_27_dialog_content = "Tú también.",
  ui_story_5028_50280902_28_dialog_content = "Veo que no sabes nada sobre bestias maravillosas de cualquier manera. Solo sigue los libros y las palabras de Vic para manejarlos.",
  ui_story_5028_50280902_29_dialog_content = "Llamándote a ti mismo un extrozoólogo a pesar de no tener autocontrol y hacer lo que te plazca.",
  ui_story_5028_50280902_30_dialog_content = "En este sentido, no eres diferente a Vic.",
  ui_story_5028_50280902_31_dialog_content = "¡No soy como él!",
  ui_story_5028_50280902_32_dialog_content = "Si insiste en negarlo, déjeme hacerle algunas preguntas.",
  ui_story_5028_50280902_33_dialog_content = "¿Qué temperatura debes mantener para los huevos de Lutumi Owl en su segunda fase de incubación?",
  ui_story_5028_50280902_34_dialog_content = "¡Conozco a este! 30! O tal vez... ¿40?",
  ui_story_5028_50280902_35_dialog_content = "Son 42,5 grados, y cada huevo debe voltearse cada seis horas.",
  ui_story_5028_50280902_36_dialog_content = "¿Tienen que ser volteados?",
  ui_story_5028_50280902_37_dialog_content = "Por supuesto. De lo contrario, la incubación fallará por completo.",
  ui_story_5028_50280902_38_dialog_content = "¡Yo sabía eso!",
  ui_story_5028_50280902_39_dialog_content = "¡Solo tengo que revisar ese cuaderno una vez más!",
  ui_story_5028_50280902_40_dialog_content = "¿Ver? Incluso confías en una hoja de trucos para saber cómo cuidar de las maravillosas bestias que, según afirmas, son tan importantes para ti...",
  ui_story_5028_50280902_41_dialog_content = "Ese es el tipo de persona descuidada y poco profesional que eres.",
  ui_story_5028_50280902_42_dialog_content = "Yo, yo...",
  ui_story_5028_50280902_43_dialog_content = "Boohoo!!!",
  ui_story_5028_50280902_44_dialog_content = "¡¿F-Fia?!",
  ui_story_5028_50280902_45_dialog_content = "Por eso siempre digo... Los niños pequeños son el dolor más grande que existe.",
  ui_story_5028_50280902_46_dialog_content = "¡No soy un niño pequeño! ¡No soy!",
  ui_story_5028_50280902_47_dialog_content = "Solo un niño pequeño negaría ser uno así.",
  ui_story_5028_50280902_48_dialog_content = "Te aconsejo que retrocedas mientras puedas y que dejes a tus amiguitos donde pertenecen.",
  ui_story_5028_50280902_49_dialog_content = "¡Eso es suficiente! ¿No ves lo mal que la haces sentir?",
  ui_story_5028_50280902_50_dialog_content = "¡Uh!",
  ui_story_5028_50280902_51_dialog_content = "Tú también eres parte de la razón por la que ella es así.",
  ui_story_5028_50280902_52_dialog_content = "¿Eh?",
  ui_story_5028_50280902_53_dialog_content = "Si no disciplinas a una niña mimada como ella, nunca aprenderá a crecer.",
  ui_story_5028_50280902_54_dialog_content = "Si siguen siendo tan imprudentes como lo han sido todo este tiempo, tarde o temprano... se encontrarán en un mundo de dolor.",
  ui_story_5028_50280902_55_dialog_content = "Al igual que yo.",
  ui_story_5028_50280902_56_dialog_content = "¡Guau! ¡Quédate, quédate donde estás!",
  ui_story_5028_50280902_57_dialog_content = "A este chico le encanta despegar sin decir una palabra más, ¿no es así?",
  ui_story_5028_50280902_58_dialog_content = "Corrió directamente hacia el interior de la cueva.",
  ui_story_5028_50280902_59_dialog_content = "Siguió hablando consigo misma... y... e incluso me acusó de...",
  ui_story_5028_50280902_60_dialog_content = "¿Estás bien, Fía?",
  ui_story_5028_50280902_61_dialog_content = "¡Lo, lo!",
  ui_story_5028_50280902_62_dialog_content = "¡Yo... nunca me rendiré tan fácilmente! ¡¡¡Nunca!!!",
  ui_story_5028_50280902_63_dialog_content = "¡¿Qué?!",
  ui_story_5028_50280902_64_dialog_content = "Estoy tan decidida a convertirme en extrozoóloga. ¡Este ridículo nunca podrá detenerme!",
  ui_story_5028_50280902_65_dialog_content = "¡Vamos a alcanzarla!",
  ui_story_5028_50280902_66_dialog_content = "Todos los guardias de la entrada han sido eliminados. ¡Esta es nuestra oportunidad de colarnos y rescatar a mi Maestro!",
  ui_story_5028_50280902_67_dialog_content = "Ella dijo que su nombre es Shira, ¿verdad?",
  ui_story_5028_50280902_68_dialog_content = "¡Definitivamente le mostraré lo capaz que soy!",
  ui_story_5028_50281001_1_dialog_content = "¿Es esta la base oculta de Gary? Que mal gusto.",
  ui_story_5028_50281001_2_dialog_content = "Hay jaulas sucias y vacías tiradas por todas partes. Huele muy mal.",
  ui_story_5028_50281001_3_dialog_content = "Me temo que muchas bestias maravillosas se mantuvieron aquí hasta hace poco.",
  ui_story_5028_50281001_4_dialog_content = "Todas las jaulas se han dejado abiertas de par en par, pero no hay bestias a la vista...",
  ui_story_5028_50281001_5_dialog_content = "¿Shira los liberó en su camino?",
  ui_story_5028_50281001_6_dialog_content = "Espera...",
  ui_story_5028_50281001_7_dialog_content = "Ten cuidado, Fía. Siento que muchas bestias maravillosas vienen hacia aquí.",
  ui_story_5028_50281001_8_dialog_content = "¡Muévete o te aplastarán!",
  ui_story_5028_50281001_9_dialog_content = "¿Eh?",
  ui_story_5028_50281001_10_dialog_content = "¡¿Qué?!",
  ui_story_5028_50281001_11_dialog_content = "Espera, ¿qué está pasando aquí?",
  ui_story_5028_50281001_12_dialog_content = "Alguien mejor me lo dice ahora mismo!",
  ui_story_5028_50281001_13_dialog_content = "¡Eh, tú! Dime, ¿qué diablos pasó aquí?",
  ui_story_5028_50281001_14_dialog_content = "¡Glú!",
  ui_story_5028_50281001_15_dialog_content = "¡¿Q-Qué?!",
  ui_story_5028_50281001_16_dialog_content = "¿Dices que hay un extraño aterrador y asesino esperando más adelante?",
  ui_story_5028_50281001_17_dialog_content = "¿Y que este extraño fue quien te liberó antes de adentrarte en la cueva?",
  ui_story_5028_50281001_18_dialog_content = "Un extraño aterrador y asesino...",
  ui_story_5028_50281001_19_option_content = "¿Podría estar hablando del líder de los bandidos?",
  ui_story_5028_50281001_20_dialog_content = "No seas tan ingenuo, PlayerName.",
  ui_story_5028_50281001_21_dialog_content = "El líder de esta pandilla de bandidos nunca dejaría escapar a una sola bestia maravillosa bajo su vigilancia.",
  ui_story_5028_50281001_22_dialog_content = "S-Sí, tienes razón.",
  ui_story_5028_50281001_23_dialog_content = "La persona de la que está hablando... probablemente sea Shira.",
  ui_story_5028_50281001_24_dialog_content = "Entonces el \"tipo aterrador\" ha estado aterrorizando a tantas bestias últimamente... No crees...",
  ui_story_5028_50281001_25_option_content = "¿Podría ser Shira también?",
  ui_story_5028_50281001_26_dialog_content = "Así es como la ven las bestias maravillosas, ¿eh? Aterrador y asesino...",
  ui_story_5028_50281001_27_dialog_content = "No puedo decir que no se alinee con su actitud podrida o esa cara suya.",
  ui_story_5028_50281001_28_dialog_content = "¡Yo también estaría asustado si fuera una bestia!",
  ui_story_5028_50281001_29_dialog_content = "Pero ahora no es el momento de preocuparse por estas bestias. No parecen estar heridos y podrían salir corriendo de aquí por su cuenta.",
  ui_story_5028_50281001_30_dialog_content = "Tenemos que seguir buscando al Maestro Vic.",
  ui_story_5028_50281001_31_dialog_content = "Claro.",
  ui_story_5028_50281001_32_dialog_content = "Está completamente oscuro aquí. no puedo ver nada...",
  ui_story_5028_50281001_33_dialog_content = "¿Estaban manteniendo a esas pobres bestias en la oscuridad así todo el tiempo?",
  ui_story_5028_50281001_34_dialog_content = "Es tan descorazonador...",
  ui_story_5028_50281001_35_dialog_content = "¡Hmph! ¿Qué tienes, miedo a la oscuridad? ¡Nunca supe que la última Caelestite fuera tan asustadiza!",
  ui_story_5028_50281001_36_dialog_content = "Eh... ¿Fia? M-Mira detrás de ti...",
  ui_story_5028_50281001_37_dialog_content = "¿Por qué, para que puedas asustarme? Lo siento amigo, eso es tan cliché.",
  ui_story_5028_50281001_38_dialog_content = "Ustedes dos... todavía me siguieron hasta aquí.",
  ui_story_5028_50281001_39_dialog_content = "¡Guau!",
  ui_story_5028_50281001_40_dialog_content = "¡¿Q-Qué crees que estás haciendo, escabulléndote detrás de mí de esa manera?!",
  ui_story_5028_50281001_41_dialog_content = "¡A-Dejemos una cosa en claro! ¡N-No me asustó en absoluto justo ahora!",
  ui_story_5028_50281001_42_dialog_content = "...",
  ui_story_5028_50281001_43_dialog_content = "Shira? ¿Vic no está contigo?",
  ui_story_5028_50281001_44_dialog_content = "Vic? No, todavía está atado en una parte más profunda de la cueva.",
  ui_story_5028_50281001_45_dialog_content = "Entonces, ¿por qué no lo rescataste?",
  ui_story_5028_50281001_46_dialog_content = "Desatarlo sería demasiado doloroso. Llevarlo fuera sería un dolor aún mayor.",
  ui_story_5028_50281001_47_dialog_content = "¡Oye! ¿No crees que usas esa excusa demasiado?",
  ui_story_5028_50281001_48_dialog_content = "Además, incluso si lo liberara, no se sabe si se metería o no en problemas aún más graves.",
  ui_story_5028_50281001_49_dialog_content = "No sé cómo espera proteger a las bestias maravillosas con esa mente dispersa.",
  ui_story_5028_50281001_50_dialog_content = "Esto es algo mejor dejárselo a alguien más profesional.",
  ui_story_5028_50281001_51_dialog_content = "Bueno, al menos podemos estar de acuerdo en algo: nuestro Maestro es realmente poco confiable.",
  ui_story_5028_50281001_52_dialog_content = "¡Pero como extrozoólogo, haré todo lo que esté a mi alcance para proteger a las maravillosas bestias del mundo en su lugar!",
  ui_story_5028_50281001_53_dialog_content = "Hmph. Lo que sea.",
  ui_story_5028_50281001_54_dialog_content = "Vic está justo ahí. Si quieres rescatarlo, adelante.",
  ui_story_5028_50281001_55_dialog_content = "Solo trata de no interponerte en mi camino.",
  ui_story_5028_50281001_56_dialog_content = "Grr... ¡Me está despreciando otra vez!",
  ui_story_5028_50281001_57_dialog_content = "¡Maldita sea... lo juro, uno de estos días, voy a dejarla boquiabierta con mis habilidades!",
  ui_story_5028_50281001_58_dialog_content = "Lo!!!",
  ui_story_5028_50281001_59_dialog_content = "Tú también lo crees, ¿no Kyllo?",
  ui_story_5028_50281001_60_dialog_content = "¡Vamos a sacar a mi Maestro de aquí!",
  ui_story_5028_50281001_61_dialog_content = "<color=#e8d9bb>En lo profundo de la fortaleza de Gary</color>",
  ui_story_5028_50281001_62_dialog_content = "¡Maestro Vic!",
  ui_story_5028_50281001_63_dialog_content = "Te metiste en un verdadero lío esta vez, Maestro...",
  ui_story_5028_50281001_64_dialog_content = "En ese caso, te desataré amablemente.",
  ui_story_5028_50281001_65_dialog_content = "¡Uf! ¡Sabía que vendrías a rescatarme tarde o temprano!",
  ui_story_5028_50281001_66_dialog_content = "¡Y ni un minuto demasiado tarde, tampoco! Mis manos se han entumecido por estas restricciones...",
  ui_story_5028_50281001_67_dialog_content = "¿Y quién podría ser este?",
  ui_story_5028_50281001_68_dialog_content = "Hola Vic. Me llamo PlayerName, y yo soy-",
  ui_story_5028_50281001_69_option_content = "Soy el Caelestite que Fia capturó.",
  ui_story_5028_50281001_70_dialog_content = "¡Sí!",
  ui_story_5028_50281001_71_dialog_content = "¡Esta es una Caelestite, una de las bestias maravillosas más raras que he atrapado!",
  ui_story_5028_50281001_72_dialog_content = "¡Solo queda uno en toda la existencia!",
  ui_story_5028_50281001_73_option_content = "Soy amigo de Fia.",
  ui_story_5028_50281001_74_dialog_content = "¡Así es! ¡Es otro de mis maravillosos compañeros de bestias!",
  ui_story_5028_50281001_75_dialog_content = "¡La única Caelestita en todo el mundo!",
  ui_story_5028_50281001_76_dialog_content = "¿Vaya? ¿Y lograste atraparlo?",
  ui_story_5028_50281001_77_dialog_content = "¡Apuesta!",
  ui_story_5028_50281001_78_dialog_content = "Y no solo eso, completé todas las tareas que me asignaste.",
  ui_story_5028_50281001_79_dialog_content = "Más impresionante...",
  ui_story_5028_50281001_80_dialog_content = "Ciertamente no voy a ser un gran extrozoólogo si no puedo manejar algunas pequeñas cosas como esa.",
  ui_story_5028_50281001_81_dialog_content = "Si encuentras una Caelestita significa que la siguiente fase de mi plan está mejorando.",
  ui_story_5028_50281001_82_dialog_content = "¿Y qué es eso?",
  ui_story_5028_50281001_83_dialog_content = "¡El último paso en tu camino para completar tu aprendizaje no es otro que detener el nefasto complot de Gary!",
  ui_story_5028_50281001_84_dialog_content = "¡Espera un segundo!",
  ui_story_5028_50281001_85_dialog_content = "¿No dijiste eso de lo que acabo de hacer?",
  ui_story_5028_50281001_86_dialog_content = "Naturalmente, tuve que preservar una capa de secreto. Su última misión real ahora se revela. De todos modos, ¿no es así como transcurren la mayoría de las grandes aventuras?",
  ui_story_5028_50281001_87_dialog_content = "¡No fidedigno! ¡Sabía que no podía creer tus palabras!",
  ui_story_5028_50281001_88_dialog_content = "¿De qué están hablando ustedes dos...",
  ui_story_5028_50281001_89_dialog_content = "¿Alguien puede decirme qué diablos está pasando?",
  ui_story_5028_50281001_90_dialog_content = "De todos modos, ¿cuál es el problema entre tú y este Gary? ¿Y por qué diablos querría secuestrarte?",
  ui_story_5028_50281001_91_dialog_content = "Es una larga historia...",
  ui_story_5028_50281001_92_dialog_content = "Hubo un tiempo en que conté a Gary entre mis amigos más cercanos.",
  ui_story_5028_50281001_93_dialog_content = "Mi fascinación por estas criaturas extraordinarias me llevó a lugares inusuales. Me encontré rechazado por la mayoría en la sociedad educada.",
  ui_story_5028_50281001_94_dialog_content = "Pero Gary no pudo tener suficiente de mí una vez que se enteró de mi experiencia en extrazoología. Se quedó día y noche para sondear las profundidades de mi conocimiento.",
  ui_story_5028_50281001_95_dialog_content = "Pensé que había encontrado un espíritu afín, un compañero experto que buscaba avanzar en los límites de nuestro campo.",
  ui_story_5028_50281001_96_dialog_content = "Es decir, hasta que un día, estaba bebiendo hasta quedar estupefacto en una taberna de Umbraton cuando me preguntó—",
  ui_story_5028_50281001_97_dialog_content = "Ya que sabes tanto sobre estas maravillosas criaturas, Vic.",
  ui_story_5028_50281001_98_dialog_content = "Seguramente también debes saber qué animal es el más poderoso.",
  ui_story_5028_50281001_99_dialog_content = "El más poderoso... ¿un-animal?",
  ui_story_5028_50281001_100_dialog_content = "Ja. Por supuesto que sí, hic—",
  ui_story_5028_50281001_101_dialog_content = "El animal más poderoso de nuestro mundo es... <color=#FFB400>Kyllo</color>!",
  ui_story_5028_50281001_102_dialog_content = "je. Haz que un Kyllo confíe en ti, y me atrevo a decir que el mundo entero... ¡será tu ostra!",
  ui_story_5028_50281001_103_dialog_content = "Con Kyllos a tu lado... hic... podrías romper las puertas de Gannon City y patear las puertas de Lumopolis, ¡fácil!",
  ui_story_5028_50281001_104_dialog_content = "Supongo que la pregunta de Gary no estaba motivada simplemente por un sentido de curiosidad.",
  ui_story_5028_50281001_105_dialog_content = "je. Me tomó tanto tiempo descubrir sus verdaderas intenciones.",
  ui_story_5028_50281001_106_dialog_content = "Solo había una razón por la que se hizo amigo mío.",
  ui_story_5028_50281001_107_dialog_content = "¿Qué fue eso, exactamente?",
  ui_story_5028_50281001_108_dialog_content = "Venganza. Quería venganza, particularmente contra todas las bestias maravillosas.",
  ui_story_5028_50281001_109_dialog_content = "¿Por qué?",
  ui_story_5028_50281001_110_dialog_content = "¡Diablos si lo sé!",
  ui_story_5028_50281001_111_dialog_content = "Al final del día, simplemente desapareció de mí después de eso.",
  ui_story_5028_50281001_112_dialog_content = "La siguiente vez que apareció fue durante ese secuestro.",
  ui_story_5028_50281001_113_dialog_content = "Maestro Vic, ¿cuál sería el punto de secuestrarlo? No eres exactamente rico. De hecho, pareces un poco apurado.",
  ui_story_5028_50281001_114_dialog_content = "Me duele oírte decir eso, Fia.",
  ui_story_5028_50281001_115_dialog_content = "¡Solo responde seriamente por un momento!",
  ui_story_5028_50281001_116_dialog_content = "¡Ay!",
  ui_story_5028_50281001_117_dialog_content = "Quería saber dónde anidan los Kyllos.",
  ui_story_5028_50281001_118_dialog_content = "¡¿Qué?!",
  ui_story_5028_50281001_119_dialog_content = "Entonces, ¿supongo que realmente cree que domesticar a Kyllos le dará todo lo que necesita y sin rival?",
  ui_story_5028_50281001_120_dialog_content = "¿Pero no es eso nada más que otra fantasía surgida de tu imaginación hiperactiva?",
  ui_story_5028_50281001_121_dialog_content = "...",
  ui_story_5028_50281001_122_dialog_content = "Si tienes razón sobre los Kyllos, entonces el mundo entero podría estar en peligro...",
  ui_story_5028_50281001_123_dialog_content = "No te preocupes. Estoy seguro de que funcionará bien.",
  ui_story_5028_50281001_124_dialog_content = "Gary nunca puede influir en los eventos mundiales, incluso si de alguna manera logró obtener a todos los Kyllo.",
  ui_story_5028_50281001_125_dialog_content = "Podemos dejarlo con sus dispositivos.",
  ui_story_5028_50281001_126_dialog_content = "...",
  ui_story_5028_50281001_127_dialog_content = "<size=50>¡No!</size>",
  ui_story_5028_50281001_128_dialog_content = "¡Ningún extrozoólogo profesional con algún honor, como yo, que pronto sería yo, podría quedarse quieto y ver cómo sucedía!",
  ui_story_5028_50281001_129_dialog_content = "¡Lo!",
  ui_story_5028_50281001_130_dialog_content = "Ahhh...",
  ui_story_5028_50281001_131_dialog_content = "¡Estamos hablando de un grupo de bandidos que esclavizan a estas maravillosas bestias a sus órdenes malvadas! ¿Crees que se preocupan por ellos o los tratan bien?",
  ui_story_5028_50281001_132_dialog_content = "¡Si dejamos que este Gary los capture, los pasará por la picadora de carne hasta que hagan lo que quiere!",
  ui_story_5028_50281001_133_dialog_content = "Obligar a estas hermosas criaturas a traicionar sus instintos es sumamente inmoral, ¡y no se puede tolerar!",
  ui_story_5028_50281001_134_dialog_content = "¡Oye! ¡Ese es el espíritu!",
  ui_story_5028_50281001_135_dialog_content = "¡Sigamos canalizando esos sentimientos mientras localizamos a Gary y detenemos su loco plan!",
  ui_story_5028_50281001_136_dialog_content = "Te daré el beneficio de la duda una vez más, ¡solo una vez, por el bien de Kyllos!",
  ui_story_5028_50281001_137_dialog_content = "¡Mis maravillosos compañeros y yo trabajaremos juntos para resolver esta malvada amenaza!",
  ui_story_5028_50281001_138_dialog_content = "¡Así que lo juro como un extrozoólogo prometedor!",
  ui_story_5028_50281001_139_dialog_content = "Y puedo contar con todos ustedes, Kyllo, Peko, Glooey, Bica y PlayerName, no puedo?",
  ui_story_5028_50281001_140_dialog_content = "¡Lo!",
  ui_story_5028_50281001_141_dialog_content = "Peko peko!",
  ui_story_5028_50281001_142_dialog_content = "gloo...",
  ui_story_5028_50281001_143_dialog_content = "hola hola!",
  ui_story_5028_50281001_144_dialog_content = "Eh... ¿de acuerdo?",
  ui_story_5028_50281001_145_dialog_content = "¡De acuerdo! ¡Vamos entonces!",
  ui_story_5028_50281001_146_dialog_content = "Parecen casi listos para derribar una fortaleza. Debería pensar que mi presencia aquí es bastante superflua entonces...",
  ui_story_5028_50281001_147_dialog_content = "Su estimado Maestro, por lo tanto, esperará noticias de su regreso a salvo de casa, ¡ay, ay, ay!",
  ui_story_5028_50281001_148_dialog_content = "¡Tranquilo! ¡Los brazos y las piernas de tu pobre viejo Maestro no están a la altura de ese tipo de castigo cruel e inusual!",
  ui_story_5028_50281001_149_dialog_content = "Perdóname por pensar lo contrario después de que cierta persona dijera que era un \"eterno joven de 18 años\".",
  ui_story_5028_50281001_150_dialog_content = "Ah-ja-ja...",
  ui_story_5028_50281001_151_dialog_content = "¿Eso no es todo esto mayormente obra suya de todos modos, Maestro?",
  ui_story_5028_50281001_152_dialog_content = "¡No deje a otros un desastre que usted hizo y puede ayudar a limpiar!",
  ui_story_5028_50281001_153_dialog_content = "Solo te ayudaré—",
  ui_story_5028_50281001_154_dialog_content = "Si dices, por ejemplo:",
  ui_story_5028_50281001_155_dialog_content = "\"¡Por favor, ayúdame, oh poderosa extrozoóloga Fia, a lidiar con estos eclipses!\"",
  ui_story_5028_50281001_156_dialog_content = "Ja ja. ¿No nos estamos adelantando un poco? Primero tenemos que averiguar el plan maestro de Gary.",
  ui_story_5028_50281001_157_dialog_content = "Bueno, en ese caso, ¿qué tal si te dejo encargarte de esos Eclipsites en su camino de regreso?",
  ui_story_5028_50281001_158_dialog_content = "Jajaja... ¡¿Ah?!",
  ui_story_5028_50281001_159_dialog_content = "Grah! ¡Rugido!",
  ui_story_5028_50281001_160_dialog_content = "¡Ay! ¡Ayuda!",
  ui_story_5028_50281001_161_dialog_content = "¡No puedo detenerlos yo mismo!",
  ui_story_5028_50281002_1_dialog_content = "Ay... Mi pobre espalda...",
  ui_story_5028_50281002_2_dialog_content = "No soy fanático de los entrenamientos de alta intensidad.",
  ui_story_5028_50281002_3_dialog_content = "Creo que te subestimas a ti mismo. Después de todo, no eres mucho mayor que yo, Vic, ¿verdad?",
  ui_story_5028_50281002_4_dialog_content = "Nunca juzgues un libro por su portada, PlayerName.",
  ui_story_5028_50281002_5_dialog_content = "Puede que sea un eterno joven de 18 años, pero las experiencias que he tenido serían bastante numerosas según sus estándares.",
  ui_story_5028_50281002_6_dialog_content = "Ahí vas de nuevo, tonto. ¡Tan ingenioso!",
  ui_story_5028_50281002_7_dialog_content = "¡Desafortunadamente, su credibilidad se está agotando!",
  ui_story_5028_50281002_8_dialog_content = "Boo-hoo, honestamente estoy desconsolado, Fia.",
  ui_story_5028_50281002_9_dialog_content = "(¿Vic está a punto de llorar?)",
  ui_story_5028_50281002_10_dialog_content = "Seguramente no hay mayores profundidades de soledad que para un Maestro ser abandonado y despreciado por sus aprendices.",
  ui_story_5028_50281002_11_dialog_content = "Creo que entiendo por qué Shira ni siquiera te dio la hora del día en que necesitabas ayuda. Eres un trabajo duro.",
  ui_story_5028_50281002_12_dialog_content = "¡Oye! Shira actualmente está muy ocupada con sus propios problemas, muchas gracias. Por eso ella no intervino.",
  ui_story_5028_50281002_13_dialog_content = "¿Problemas? ¿Qué problemas?",
  ui_story_5028_50281002_14_dialog_content = "¿Qué tipo de problema podría inspirarla a dejar a su Maestro en manos de bandidos?",
  ui_story_5028_50281002_15_dialog_content = "Shira, pobre niña, está hechizada por el mismo interés apasionado por las bestias maravillosas que todos compartimos.",
  ui_story_5028_50281002_16_dialog_content = "Desafortunadamente, sus esfuerzos se han visto empañados por un poco de mala suerte. ¿Notaste algo inusual en ella?",
  ui_story_5028_50281002_17_dialog_content = "Te refieres a...",
  ui_story_5028_50281002_18_dialog_content = "¿Sus pies con tentáculos?",
  ui_story_5028_50281002_19_dialog_content = "Hmm... Podrías decirlo así.",
  ui_story_5028_50281002_20_dialog_content = "¿Las maravillosas bestias le tienen miedo?",
  ui_story_5028_50281002_21_dialog_content = "Por cierto. Perceptivo de ti.",
  ui_story_5028_50281002_22_dialog_content = "Un desafortunado incidente fusionó las piernas de Shira con las de un pulpo cercano.",
  ui_story_5028_50281002_23_dialog_content = "Cómo la amaban los animales en su día. Después de su transformación, ahora se acercan temerosos a distancia, si es que lo hacen.",
  ui_story_5028_50281002_24_dialog_content = "Un pulpo representa una especie extraña y aterradora para la mayoría de los animales.",
  ui_story_5028_50281002_25_dialog_content = "Fue un golpe terrible para Shira, eso seguro. Pero nada que disminuya su pasión por el campo.",
  ui_story_5028_50281002_26_dialog_content = "Si su pasión cambió en absoluto, podríamos decir que cambió solo hacia las bestias maravillosas.",
  ui_story_5028_50281002_27_dialog_content = "¿A qué te refieres?",
  ui_story_5028_50281002_28_dialog_content = "¿No me digas que no notaste nada?",
  ui_story_5028_50281002_29_dialog_content = "Ella se preocupa profundamente por las bestias maravillosas, le concedo eso...",
  ui_story_5028_50281002_30_dialog_content = "¡Pero ella ha llegado a verme como nada más que un \"aficionado\"!",
  ui_story_5028_50281002_31_dialog_content = "Me considera un aficionado tan aficionado que ni siquiera confía en la seguridad de mis métodos.",
  ui_story_5028_50281002_32_dialog_content = "... ¿Le parece una opinión razonada?",
  ui_story_5028_50281002_33_dialog_content = "...",
  ui_story_5028_50281002_34_dialog_content = "Oh, Shira, siento mucho lo de nuestro Maestro...",
  ui_story_5028_50281002_35_dialog_content = "Veo que la misma actitud te ha afectado a ti también, Fia.",
  ui_story_5028_50281002_36_dialog_content = "De todos modos, no es el primer malentendido con el que tengo que lidiar en mi vida, y no será el último.",
  ui_story_5028_50281002_37_dialog_content = "En resumen, a Shira le han disgustado mis métodos \"extemporáneos\" y centra todos sus esfuerzos en convertirse en una extrozoóloga profesional.",
  ui_story_5028_50281002_38_dialog_content = "¿Un \"extrozoólogo profesional\"? ¿Existe tal cosa?",
  ui_story_5028_50281002_39_dialog_content = "Bueno, ella se abrió paso a través de muchos materiales arcanos y diseñó muchos métodos para observar bestias maravillosas.",
  ui_story_5028_50281002_40_dialog_content = "Por ejemplo, al asignar etiquetas en los tobillos a las bestias maravillosas que encuentra en la naturaleza antes de liberarlas.",
  ui_story_5028_50281002_41_dialog_content = "Entonces, cuando solo captura un tipo específico de bestias maravillosas, puede obtener una estimación aproximada de su población total por la cantidad de etiquetas en los tobillos.",
  ui_story_5028_50281002_42_dialog_content = "¿Entonces Shira es quien puso todas esas etiquetas en los pies de los Drakolions?",
  ui_story_5028_50281002_43_dialog_content = "Sí. Probablemente vamos. ¿Quién más lo haría excepto ella?",
  ui_story_5028_50281002_44_dialog_content = "Ahora que lo pienso, se le ocurrieron algunas técnicas ingeniosas. ¡Algunos de ellos, tengo que admitirlo, son bastante ingeniosos!",
  ui_story_5028_50281002_45_dialog_content = "¡Pero a medida que ha pasado el tiempo, nuestras \"diferencias de opinión\" solo han empeorado!",
  ui_story_5028_50281002_46_dialog_content = "Ella culpa en parte de su accidente a su falta de conocimiento, pero también a mi... error.",
  ui_story_5028_50281002_47_dialog_content = "¡Pasó de considerarme un practicante poco serio a algo así como un peligro para ser despreciado!",
  ui_story_5028_50281002_48_dialog_content = "¿Eh? ¿Así que eres responsable de lo que le pasó a Shira?",
  ui_story_5028_50281002_49_dialog_content = "¡No absolutamente no! ¡Eso es lo que significa accidente! ¡Nadie tuvo la culpa!",
  ui_story_5028_50281002_50_dialog_content = "Shira quería saber de dónde venía y buscaba información sobre su pasado.",
  ui_story_5028_50281002_51_dialog_content = "Me di cuenta de que tenía un pequeño pulpo, así que le aconsejé que comprobara el hábitat del que procedía su amiguito.",
  ui_story_5028_50281002_52_dialog_content = "¿Cómo iba a saber que trazaría un barco hasta las profundidades del océano y luego tendría la mala suerte de chocar contra una tormenta eléctrica...",
  ui_story_5028_50281002_53_dialog_content = "Ese pequeño pulpo se fusionó con Shira para salvarle la vida a través de sus extraordinarios poderes de regeneración.",
  ui_story_5028_50281002_54_dialog_content = "Todo lo que hice fue revelar la forma de encontrar el hábitat de los pulpos y nada más.",
  ui_story_5028_50281002_55_dialog_content = "Hmph, no obtendrás mi simpatía incluso con esa cara de \"Estoy a punto de llorar\".",
  ui_story_5028_50281002_56_dialog_content = "Esto es lo que pasa cuando das malos consejos de forma irresponsable.",
  ui_story_5028_50281002_57_dialog_content = "Si quieres arreglar las cosas, lo primero que tenemos que hacer es encontrar el hábitat de Kyllos y detener el loco plan de Gary.",
  ui_story_5028_50281002_58_dialog_content = "Suspiro, tienes todas las marcas de un aprendiz, Fia, pero nada del respeto.",
  ui_story_5028_50281002_59_dialog_content = "Parece que después de un largo período de secuestro, todavía tengo que soportar un viaje con el estómago vacío...",
  ui_story_5028_50281002_60_dialog_content = "¿Tienes hambre?",
  ui_story_5028_50281002_61_dialog_content = "¡Este pan plano te llenará!",
  ui_story_5028_50281002_62_dialog_content = "¿Oh? ¿Detecto el olor a harina y un brillo dorado crujiente...? No importa si empiezo ahora...",
  ui_story_5028_50281002_63_dialog_content = "¡Nom-nom, mi hambre lo ha transformado en el pan plano más delicioso que puedas imaginar!",
  ui_story_5028_50281002_64_dialog_content = "De alguna manera parece familiar... Espera. ¿Por qué llevas un pan plano contigo, Fia?",
  ui_story_5028_50281002_65_dialog_content = "Porque pensé que los inútiles que secuestraron a mi Maestro podrían no haber sido lo suficientemente considerados como para proporcionar comidas.",
  ui_story_5028_50281002_66_dialog_content = "Así que traje provisiones especiales.",
  ui_story_5028_50281002_67_dialog_content = "¡Nom-nom, un gran aprendiz es realmente aquel que considera las necesidades de su Maestro!",
  ui_story_5028_50281002_68_dialog_content = "Aunque tengo que decir que los compré hace unos días. Espero que no les haya ido mal.",
  ui_story_5028_50281002_69_dialog_content = "Nom, tos, ¡oye!",
  ui_story_5028_50281002_70_dialog_content = "Vic?!",
  ui_story_5028_50281002_71_dialog_content = "Tos, ahora estoy bien. Por ahora, de todos modos.",
  ui_story_5028_50281002_72_dialog_content = "¿Quisieras un poco mas? Traje algunos otros con diferentes sabores.",
  ui_story_5028_50281002_73_dialog_content = "E-Está bien. ya estoy lleno En uno solo.",
  ui_story_5028_50281002_74_dialog_content = "¡Vamos, entonces!",
  ui_story_5028_50281002_75_dialog_content = "¡Y detén a ese malvado y su complot!",
  ui_story_5028_50281002_76_dialog_content = "Así que esos fueron los bandidos que secuestraron PlayerName?",
  ui_story_5028_50281002_77_dialog_content = "Parecen bastante extraños.",
  ui_story_5028_50281002_78_dialog_content = "¿Que te importa? Entremos y trapeemos el piso con ellos. ¿Te parece un plan suficiente?",
  ui_story_5028_50281002_79_dialog_content = "que imprudente Smokey.",
  ui_story_5028_50281002_80_dialog_content = "No es lo que esperaba de un miembro de la nobleza.",
  ui_story_5028_50281002_81_dialog_content = "Shhh. Sin discutir",
  ui_story_5028_50281002_82_dialog_content = "Tsk...",
  ui_story_5028_50281002_83_dialog_content = "Simplemente sigámoslos. Entonces entraremos y rescataremos PlayerName cuando surja la oportunidad!",
  ui_story_5028_50281101_1_dialog_content = "<color=#e8d9bb>El hábitat de Kyllos</color>",
  ui_story_5028_50281101_2_dialog_content = "Debo admitir que tienes algunas habilidades, mi jovencita.",
  ui_story_5028_50281101_3_dialog_content = "Pero, ¿cuánto tiempo puedes aguantar?",
  ui_story_5028_50281101_4_dialog_content = "Gary",
  ui_story_5028_50281101_X4_dialog_content = "38 años",
  ui_story_5028_50281101_X5_dialog_content = "Un villano que anda capturando bestias maravillosas.",
  ui_story_5028_50281101_5_dialog_content = "Si te rebajaras tanto como para usar a estas criaturas en mi contra, puedo ver que eres alguien a quien debo detener...",
  ui_story_5028_50281101_6_dialog_content = "Y puedo ver que eres alguien con el poder de derrotar fácilmente a los Eclipsites.",
  ui_story_5028_50281101_7_dialog_content = "Sin embargo, está tan obstaculizado por su amor imaginario por los animales que no está dispuesto a hacer lo que es necesario.",
  ui_story_5028_50281101_8_dialog_content = "¿Es mejor soportar su escandaloso asalto, supongo? Pobre idiota.",
  ui_story_5028_50281101_9_dialog_content = "Callarse la boca.",
  ui_story_5028_50281101_10_dialog_content = "Al menos sé a quién responsabilizar por todos estos crímenes.",
  ui_story_5028_50281101_11_dialog_content = "¡Y quién hizo cautivas de guerra a estas pobres y maravillosas bestias!",
  ui_story_5028_50281101_12_dialog_content = "¿Cautivos de guerra? je. ¡Ridículo!",
  ui_story_5028_50281101_13_dialog_content = "¿Cómo te atreves a llamar \"cautivos\" de cualquier tipo a criaturas tan simples y brutales? No son más cautivos que cualquier otra bestia de carga.",
  ui_story_5028_50281101_14_dialog_content = "¡De hecho, estos estúpidos brutos no merecen compartir los recursos del mundo y su aire con nosotros!",
  ui_story_5028_50281101_15_dialog_content = "¡Cállate la boca!",
  ui_story_5028_50281101_16_dialog_content = "*Roncando*",
  ui_story_5028_50281101_17_dialog_content = "¿Eh?",
  ui_story_5028_50281101_18_dialog_content = "Vamos. matarla",
  ui_story_5028_50281101_19_dialog_content = "Desengaña a esta tonta de sus ridículas nociones.",
  ui_story_5028_50281101_20_dialog_content = "Graah! ¡Rugido!",
  ui_story_5028_50281101_21_dialog_content = "por favor no...",
  ui_story_5028_50281101_22_dialog_content = "¡Páralos!",
  ui_story_5028_50281101_23_dialog_content = "¡Lo!",
  ui_story_5028_50281101_24_dialog_content = "¡Buen tiro, Fia!",
  ui_story_5028_50281101_25_dialog_content = "Gracias. ¿No me digas que te sorprende que pueda pelear?",
  ui_story_5028_50281101_26_dialog_content = "Shira, ¿estás bien?",
  ui_story_5028_50281101_27_dialog_content = "Por qué eres...",
  ui_story_5028_50281101_28_dialog_content = "Estás a salvo ahora. ¡Estamos aquí para detener a Gary!",
  ui_story_5028_50281101_29_dialog_content = "Vic nos contó todo.",
  ui_story_5028_50281101_30_dialog_content = "¡Te ayudaremos a detener a Gary!",
  ui_story_5028_50281101_31_dialog_content = "¡Sal de aquí! No podemos arriesgarnos.",
  ui_story_5028_50281101_32_dialog_content = "¡Este tipo es un puñado!",
  ui_story_5028_50281101_33_dialog_content = "Me sorprende que haya logrado llamar a la caballería.",
  ui_story_5028_50281101_34_dialog_content = "Y pensé que simplemente te habrías escapado después de lo que pasó, Vic.",
  ui_story_5028_50281101_35_dialog_content = "No soy tan cobarde como crees, Gary.",
  ui_story_5028_50281101_36_dialog_content = "Si vas a venir con fuerza, es posible que yo también tenga que ayudarme.",
  ui_story_5028_50281101_37_dialog_content = "¡Me complace mucho revelar el poder de estos terribles brutos!",
  ui_story_5028_50281101_X37_dialog_content = "Conduce esos Eclipsites aquí también. ¡Juntos ahora!",
  ui_story_5028_50281101_38_dialog_content = "Gah...",
  ui_story_5028_50281101_39_dialog_content = "Separarlos.",
  ui_story_5028_50281101_40_dialog_content = "¡Si jefe!",
  ui_story_5028_50281101_41_dialog_content = "¡Gahhhh!",
  ui_story_5028_50281101_42_dialog_content = "Golpea, Kyllo, PlayerName!",
  ui_story_5028_50281101_43_dialog_content = "¡Lo!",
  ui_story_5028_50281101_44_dialog_content = "¿Eh? ¿Y yo?",
  ui_story_5028_50281101_45_dialog_content = "¡Deja de distraerte! ¡Dé las órdenes!",
  ui_story_5028_50281102_1_dialog_content = "Débil. Tan terriblemente débil...",
  ui_story_5028_50281102_2_dialog_content = "¿Cómo es posible que tengas bestias tan poderosas a tu lado y no sepas cómo usarlas?",
  ui_story_5028_50281102_3_dialog_content = "¡Por qué, pequeña!",
  ui_story_5028_50281102_4_dialog_content = "Esta lección está en la casa: para doblar una criatura para hacer tu voluntad en la batalla, hazlo así...",
  ui_story_5028_50281102_5_dialog_content = "¡Levántense, perezosos patéticos, y destrúyanlos!",
  ui_story_5028_50281102_6_dialog_content = "¡¡¡Rugido!!!",
  ui_story_5028_50281102_7_dialog_content = "Tú... ¿entrenaste a este Drakolion?",
  ui_story_5028_50281102_8_dialog_content = "¡¡¡Rugido!!!",
  ui_story_5028_50281102_9_dialog_content = "¡Lo!",
  ui_story_5028_50281102_10_dialog_content = "¡Detén esta locura! ¡Ninguna bestia maravillosa quiere pelear con nadie!",
  ui_story_5028_50281102_11_dialog_content = "¿No quieren?",
  ui_story_5028_50281102_12_dialog_content = "¡Ja ja! ¡Me alegro de no tener que preocuparme por lo que quieren estas bestias!",
  ui_story_5028_50281102_13_dialog_content = "¡Solo necesito que me teman y me respeten lo suficiente como para sacrificar sus vidas!",
  ui_story_5028_50281102_14_dialog_content = "¡Te has vuelto completamente loco! ¡Y yo, como extrozoólogo, te pediré cuentas!",
  ui_story_5028_50281102_15_dialog_content = "¡Buen trabajo, mi brillante aprendiz! ¡Puedes hacerlo!",
  ui_story_5028_50281102_16_dialog_content = "Su aliento es tan vano como inútil.",
  ui_story_5028_50281102_17_dialog_content = "Oh Dios mío. Mi aprendiz se está volviendo contra mí otra vez...",
  ui_story_5028_50281102_18_dialog_content = "¡Qué palabras tan fuertes de una cosa tan pequeña!",
  ui_story_5028_50281102_19_dialog_content = "Lástima que no tengas la fuerza para respaldarlo.",
  ui_story_5028_50281102_20_dialog_content = "¡Rooooooor!",
  ui_story_5028_50281102_21_dialog_content = "¡Yeaargh!",
  ui_story_5028_50281102_22_dialog_content = "fia!!!",
  ui_story_5028_50281102_23_dialog_content = "¿Eh?",
  ui_story_5028_50281102_24_dialog_content = "Oh querido. Nos estamos aplastando...",
  ui_story_5028_50281102_25_dialog_content = "¡Nos rendimos! Por favor, déjanos ir.",
  ui_story_5028_50281102_26_dialog_content = "¿Qué sucede contigo? ¿No vas a ofrecer la más mínima resistencia?",
  ui_story_5028_50281102_27_dialog_content = "¿Qué resistencia? No podemos hacer nada.",
  ui_story_5028_50281102_28_dialog_content = "Te sacó a ti ya Fia, ¿no?",
  ui_story_5028_50281102_29_dialog_content = "PlayerName es un caelestita, no un auroriano. Él no puede pelear.",
  ui_story_5028_50281102_30_dialog_content = "Y ya tengo suficientes problemas con mis pobres piernas y brazos.",
  ui_story_5028_50281102_31_dialog_content = "Así que nuestra única opción es rendirnos.",
  ui_story_5028_50281102_32_dialog_content = "Al menos tienes que intentar ofrecer algo de resistencia...",
  ui_story_5028_50281102_33_dialog_content = "¿Qué resistencia? Yo digo que elijamos la supervivencia práctica.",
  ui_story_5028_50281102_34_dialog_content = "¿Crees que te dejaré salir de aquí si te rindes?",
  ui_story_5028_50281102_35_dialog_content = "¡No, te quedarás conmigo hasta que puedas presenciar mi momento de grandeza!",
  ui_story_5028_50281102_36_dialog_content = "Asegúrelos firmemente y acompáñelos a las celdas de detención.",
  ui_story_5028_50281102_37_dialog_content = "¡Si jefe!",
  ui_story_5028_50281102_38_dialog_content = "je. Nos hiciste la vida muy difícil la última vez. Ahora podemos expresar nuestra \"gratitud\".",
  ui_story_5028_50281102_39_dialog_content = "¡Lo! ¡Lo, lo!",
  ui_story_5028_50281102_40_dialog_content = "Kyllo!",
  ui_story_5028_50281102_41_dialog_content = "¡Uh!",
  ui_story_5028_50281102_42_dialog_content = "¡Congelar!",
  ui_story_5028_50281102_43_dialog_content = "¡No tan apretado! Soy propenso a los espasmos en los brazos. ¡Ay!",
  ui_story_5028_50281102_44_dialog_content = "Ugh...",
  ui_story_5028_50281102_45_dialog_content = "Esto es todo entonces. Estamos total y absolutamente jodidos...",
  ui_story_5028_50281102_46_dialog_content = "Abre bien los ojos y observa lo que voy a mostrarte.",
  ui_story_5028_50281102_47_dialog_content = "Mostraré al mundo cuán aterradores y poderosos son estos brutos hasta que la idea esté firmemente implantada en la mente de todos.",
  ui_story_5028_50281102_48_dialog_content = "Vaya. ¿Así que ese fue tu plan maestro todo el tiempo?",
  ui_story_5028_50281102_49_dialog_content = "¿Qué pasa contigo y la bestia maravillosa? ¿Por qué los odias tanto?",
  ui_story_5028_50281102_50_dialog_content = "Dudo que un \"amante de los animales\" como tú lo entienda.",
  ui_story_5028_50281102_51_dialog_content = "Todo lo que necesitas saber es que los hago responsables por privarme de lo que más importaba.",
  ui_story_5028_50281102_52_dialog_content = "\"Lo que más importaba\"... ¿Eh?",
  ui_story_5028_50281102_53_dialog_content = "Eres irritante, ¿no?",
  ui_story_5028_50281102_54_dialog_content = "Estaba en camino de atrapar a estas criaturas cuando decidiste lanzar una llave inglesa en las obras.",
  ui_story_5028_50281102_55_dialog_content = "Eso está bien. Puedo permitirme ser paciente.",
  ui_story_5028_50281102_56_dialog_content = "Con tal de que este pequeño no se escape...",
  ui_story_5028_50281102_57_dialog_content = "¡Lo, lo!",
  ui_story_5028_50281102_58_dialog_content = "¿Qué es?",
  ui_story_5028_50281102_59_dialog_content = "Hace los mismos sonidos que un Kyllo aunque parezca un poco extraño.",
  ui_story_5028_50281102_60_dialog_content = "¿También es un Kyllo?",
  ui_story_5028_50281102_61_dialog_content = "Toda mi experiencia me dice que sí, que son de la misma especie.",
  ui_story_5028_50281102_62_dialog_content = "¿Hay otro tipo de Kyllo? ¿Cómo terminó luciendo así?",
  ui_story_5028_50281102_63_dialog_content = "Hay muchas posibilidades.",
  ui_story_5028_50281102_64_dialog_content = "La evolución repentina, los factores ambientales y la variación subracial podrían ser responsables de tales diferencias individuales.",
  ui_story_5028_50281102_65_dialog_content = "Se ve completamente diferente a mi Kyllo. ¿Seguro que son de la misma especie?",
  ui_story_5028_50281102_66_dialog_content = "Algunas posibilidades podrían explicar eso, eh, en realidad ninguna viene a la mente.",
  ui_story_5028_50281102_67_dialog_content = "¡Necesitamos que sea lo más confiable posible ahora!",
  ui_story_5028_50281102_68_dialog_content = "Je, valora estos preciosos momentos llenos de diversión. Serán los últimos.",
  ui_story_5028_50281102_69_dialog_content = "¿Por qué estás haciendo esto?",
  ui_story_5028_50281102_70_dialog_content = "Aunque estos brutos no pueden entender el lenguaje humano, pueden responder a los gritos de su propia especie.",
  ui_story_5028_50281102_71_dialog_content = "¡Lo, lo!",
  ui_story_5028_50281102_72_dialog_content = "Con eso, puedo atraer a todos los Kyllos alrededor de estas partes a mi red. Entonces será un simple proceso de entrenamiento.",
  ui_story_5028_50281102_73_dialog_content = "Jaja... Jajajajaja!!",
  ui_story_5028_50281102_74_dialog_content = "¡Y todos los Aurorianos de Astra pronto sabrán de qué terribles terrores son capaces!",
  ui_story_5028_50281102_75_dialog_content = "Y únete a mí en el mismo dolor.",
  ui_story_5028_50281102_76_dialog_content = "Mantén una estrecha vigilancia sobre ellos. No dejes que se escapen.",
  ui_story_5028_50281102_77_dialog_content = "¡Si jefe!",
  ui_story_5028_50281102_78_dialog_content = "<color=#e8d9bb>base de gary</color>",
  ui_story_5028_50281102_79_dialog_content = "¡Adentro vas!",
  ui_story_5028_50281102_80_dialog_content = "¡No tan duro!",
  ui_story_5028_50281102_81_dialog_content = "¡Te pisotearé cuando salga de aquí!",
  ui_story_5028_50281102_82_dialog_content = "Sí, ese es el espíritu, Fia.",
  ui_story_5028_50281102_83_dialog_content = "No puedo creer que sigas siendo impertinente en un momento como este.",
  ui_story_5028_50281102_84_dialog_content = "No tienes sentido de lo apropiado. ¡Dios mío, estamos en peligro mortal!",
  ui_story_5028_50281102_85_dialog_content = "¡Callarse la boca! ¡Un vistazo más de ti y los tendré colgados a todos!",
  ui_story_5028_50281102_86_dialog_content = "...",
  ui_story_5028_50281102_87_dialog_content = "...",
  ui_story_5028_50281102_88_dialog_content = "¡No te estoy escuchando! Si quieres que deje de hablar, entonces voy a... ¡uf!",
  ui_story_5028_50281102_89_dialog_content = "Enfríelo por unos minutos mientras pienso en un plan, ¿de acuerdo?",
  ui_story_5028_50281102_90_dialog_content = "(¿Qué debo hacer? Realmente no puedo pensar en nada por mi cuenta...)",
  ui_story_5028_50281102_91_dialog_content = "(¡Oh, claro! Ya que no puedo hablar, ¿por qué no uso mi habilidad psíquica para comunicarme con todos?)",
  ui_story_5028_50281102_92_dialog_content = "(De esta manera, esos bandidos no deberían notar que discutimos).",
  ui_story_5028_50281102_93_option_content = "¡Potencia de fuerza!",
  ui_story_5028_50281102_94_dialog_content = "¡Fia! ¿Puedes escucharme?",
  ui_story_5028_50281102_95_dialog_content = "¡Guau! PlayerName, ¿puedes al menos darme un aviso antes de usar tu poder?",
  ui_story_5028_50281102_96_dialog_content = "Lo siento. ¡Es una emergencia!",
  ui_story_5028_50281102_97_dialog_content = "Vic?",
  ui_story_5028_50281102_98_dialog_content = "Oh, sí, las habilidades psíquicas de Caelestite, ¿lo entiendo? Ah, los viejos tiempos...",
  ui_story_5028_50281102_99_dialog_content = "¡Y Shira!",
  ui_story_5028_50281102_100_dialog_content = "Te escucho.",
  ui_story_5028_50281102_101_dialog_content = "¡Fia, discutamos cómo podemos escapar!",
  ui_story_5028_50281102_102_dialog_content = "¿Una carrera por ello? ¿Y cómo van a hacer eso?",
  ui_story_5028_50281102_103_dialog_content = "Consiguieron mi Kyllo, y el resto no es rival para estos bandidos.",
  ui_story_5028_50281102_104_dialog_content = "¿Le has preguntado a Shira? Ella es extremadamente fuerte, aunque un poco rara. Tal vez ella tiene algunas ideas.",
  ui_story_5028_50281102_105_dialog_content = "Shira, ¿se te ocurre algo? ¿Hay alguna forma de usar los poderes de estas maravillosas bestias para escapar?",
  ui_story_5028_50281102_106_dialog_content = "En lugar de pensar en una forma de volver a estas pobres criaturas contra estos malvados bandidos...",
  ui_story_5028_50281102_107_dialog_content = "Creo que podría tener más suerte para salir de estas malditas cuerdas.",
  ui_story_5028_50281102_108_dialog_content = "No debería ser demasiado difícil arrancarlos una vez que me recupere.",
  ui_story_5028_50281102_109_dialog_content = "Pero si no nos ayudan en absoluto entonces... Vic, ¿alguna idea?",
  ui_story_5028_50281102_110_dialog_content = "No tenemos tanta prisa, PlayerName.",
  ui_story_5028_50281102_111_dialog_content = "Es posible que nos hayan inmovilizado, pero este podría ser un buen momento para usar tus habilidades de Caelestite para observar nuestro entorno.",
  ui_story_5028_50281102_112_dialog_content = "Nuestro destino está en tus manos, PlayerName.",
  ui_story_5028_50281102_113_dialog_content = "¿Así? ¿Sobre mí?",
  ui_story_5028_50281102_114_dialog_content = "Daré lo mejor de mí.",
  ui_story_5028_50281102_115_option_content = "¡Potencia de fuerza!",
  ui_story_5028_50281102_116_dialog_content = "...",
  ui_story_5028_50281102_117_dialog_content = "(Hay bandidos patrullando cerca...)",
  ui_story_5028_50281102_118_dialog_content = "(Algunas bestias maravillosas enjauladas).",
  ui_story_5028_50281102_119_dialog_content = "(¿Muchas bestias maravillosas que se parecen a Kyllos?)",
  ui_story_5028_50281102_120_dialog_content = "Vic, no es genial. ¡Los bandidos han capturado a un montón de Kyllos!",
  ui_story_5028_50281102_121_dialog_content = "Dios mío. Entonces, ¿realmente lo logró?",
  ui_story_5028_50281102_122_dialog_content = "Sin embargo, no deberíamos tener mucho de qué preocuparnos a menos que logre despertar las habilidades de Kyllos.",
  ui_story_5028_50281102_123_dialog_content = "Derecha. Miraré alrededor de nuevo. Creo que puedo sentir alguna actividad lejana.",
  ui_story_5028_50281102_124_dialog_content = "Ese es Revy, escondido en algunos trastos.",
  ui_story_5028_50281102_125_dialog_content = "Esperar, Revy?!",
  ui_story_5028_50281102_126_dialog_content = "PlayerName! ¡Finalmente me has notado!",
  ui_story_5028_50281102_127_dialog_content = "Acabábamos de empezar y desapareciste de mí, PlayerName.",
  ui_story_5028_50281102_128_dialog_content = "Así es, recién empezábamos a jugar cuando Fia me llevó para ayudarla.",
  ui_story_5028_50281102_129_dialog_content = "Lo siento mucho.",
  ui_story_5028_50281102_130_dialog_content = "¡Te hemos estado buscando por años!",
  ui_story_5028_50281102_131_dialog_content = "¿Nosotros? ¿Tienes a otros contigo? ¡Déjame echar otro vistazo!",
  ui_story_5028_50281102_132_dialog_content = "Es Genevieve...",
  ui_story_5028_50281102_133_dialog_content = "PlayerName, ¿tienes un montón de nuevos compañeros allí?",
  ui_story_5028_50281102_134_dialog_content = "eres muy popular, PlayerName.",
  ui_story_5028_50281102_135_dialog_content = "Giro la cabeza por un momento y luego, ¡guau! Mira cuántos seguidores tienes.",
  ui_story_5028_50281102_136_dialog_content = "y es que Smokey? Y ella ha hecho las paces con Genevieve?",
  ui_story_5028_50281102_137_dialog_content = "Vaya. ¿Son esos amigos tuyos?",
  ui_story_5028_50281102_138_dialog_content = "Yo estaba deseando un poco de diversión ardiente.",
  ui_story_5028_50281102_139_dialog_content = "¡Oh no, por favor no te burles de mí!",
  ui_story_5028_50281102_140_dialog_content = "Excelente. ¡Creo que todos juntos podremos definitivamente cambiar esto!",
  ui_story_5028_50281102_141_dialog_content = "¡Estoy en un lugar problemático y necesito tu ayuda!",
  ui_story_5028_50281102_142_dialog_content = "Por supuesto. PlayerName es mi amigo, y siempre estaré aquí para ayudar!",
  ui_story_5028_50281102_143_dialog_content = "Todos nosotros vinimos aquí solo para encontrarte, PlayerName.",
  ui_story_5028_50281102_144_dialog_content = "¡Gracias!",
  ui_story_5028_50281102_145_dialog_content = "Fia, Shira, Vic: ¡tenemos una salida!",
  ui_story_5028_50281102_146_dialog_content = "¡Encontré algunas personas para ayudarnos!",
  ui_story_5028_50281102_147_dialog_content = "Eh. ¡Eso tomó años!",
  ui_story_5028_50281102_148_dialog_content = "Mientras estabas holgazaneando con tu telepatía, ya se me ocurrió una idea extremadamente <color=#FFB400>plan brillante</color>.",
  ui_story_5028_50281102_149_dialog_content = "¿Eh? ¿Q-Qué plan se te ocurrió?",
  ui_story_5028_50281102_150_dialog_content = "¡Nunca subestimes a un extrozoólogo!",
  ui_story_5028_50281102_151_dialog_content = "Esto es con lo que empezamos, y luego vamos a...",
  ui_story_5028_50281201_1_dialog_content = "<color=#e8d9bb>Fuera de la base de Gary</color>",
  ui_story_5028_50281201_2_dialog_content = "¿Qué piensas? ¿Crees que el plan del jefe realmente puede funcionar?",
  ui_story_5028_50281201_3_dialog_content = "Shh... Silencio.",
  ui_story_5028_50281201_4_dialog_content = "No expreses tus dudas o te colgará del árbol durante toda una noche helada.",
  ui_story_5028_50281201_5_dialog_content = "¿Y qué era todo eso que decía Vic?",
  ui_story_5028_50281201_6_dialog_content = "¡Parece que el jefe realmente le creyó!",
  ui_story_5028_50281201_7_dialog_content = "<color=#e8d9bb>Toot Toot</color>",
  ui_story_5028_50281201_8_dialog_content = "Escuchen. Boss tiene otra orden.",
  ui_story_5028_50281201_9_dialog_content = "¿Qué? ¿Qué acaba de decir?",
  ui_story_5028_50281201_10_dialog_content = "<color=#e8d9bb>Toot Toot</color>",
  ui_story_5028_50281201_11_dialog_content = "¡Son... intrusos!",
  ui_story_5028_50281201_12_dialog_content = "¡Desde el noroeste!",
  ui_story_5028_50281201_13_dialog_content = "¡Vamos!",
  ui_story_5028_50281201_14_dialog_content = "Uf... ¿Dónde están?",
  ui_story_5028_50281201_15_dialog_content = "¿Diablos? No hay nada aquí...",
  ui_story_5028_50281201_16_dialog_content = "<color=#e8d9bb>Toot-toot, toot—</color>",
  ui_story_5028_50281201_17_dialog_content = "¿Qué? ¿Esa es la señal para desayunar?",
  ui_story_5028_50281201_18_dialog_content = "¿Hay algún problema con el sistema de señalización? ¿Quién está haciendo eso?",
  ui_story_5028_50281201_19_dialog_content = "¡Excelente! ¡El primer paso de mi plan maestro es un éxito rotundo!",
  ui_story_5028_50281201_20_dialog_content = "Buena cosa Revy tomó el libro de señales del bandido...",
  ui_story_5028_50281201_21_dialog_content = "¡Y Peko Rabbit ha hecho un gran trabajo al comérselo!",
  ui_story_5028_50281201_22_dialog_content = "Peko peko!",
  ui_story_5028_50281201_23_dialog_content = "¡Todo depende de ti ahora, Caelestite!",
  ui_story_5028_50281201_24_dialog_content = "No estoy exactamente cómodo con esto, pero después de soportar tantos casi accidentes...",
  ui_story_5028_50281201_25_dialog_content = "¡Creo que mis habilidades de escape han mejorado enormemente!",
  ui_story_5028_50281201_26_dialog_content = "¡Oigan, estúpidos bandidos! ¡Venir a buscarme!",
  ui_story_5028_50281201_27_dialog_content = "¿Que es eso? ¡Se escapó un cautivo!",
  ui_story_5028_50281201_28_dialog_content = "¡Sosténlo justo ahí!",
  ui_story_5028_50281201_29_dialog_content = "¿Eh?",
  ui_story_5028_50281201_30_dialog_content = "Esta es la forma de correr: cerca del hábitat original de los Kyllos.",
  ui_story_5028_50281201_31_dialog_content = "Soroz se detuvo por aquí cuando buscaba a Gary, y...",
  ui_story_5028_50281201_32_dialog_content = "¡Ese tipo que estaba persiguiendo a Soroz todavía está aquí!",
  ui_story_5028_50281201_33_dialog_content = "*Rugido*",
  ui_story_5028_50281201_34_dialog_content = "¡Mira allá!",
  ui_story_5028_50281201_35_dialog_content = "¿Que demonios? ¿Otro Drakolion?",
  ui_story_5028_50281201_36_dialog_content = "¡¡¡Rugido!!!",
  ui_story_5028_50281201_37_dialog_content = "¡Urgh-!",
  ui_story_5028_50281201_38_dialog_content = "¡Rápido, repórtaselo al jefe!",
  ui_story_5028_50281201_39_dialog_content = "¡Cierto, okey!",
  ui_story_5028_50281201_40_dialog_content = "Extraño. Los Drakolions acaban de volar. ¿Y por qué sigue tan oscuro?",
  ui_story_5028_50281201_41_dialog_content = "¡Ay!",
  ui_story_5028_50281201_42_dialog_content = "hola hola! ¡Hola!",
  ui_story_5028_50281201_43_dialog_content = "¡Excelente! La próxima vez no tendrás que comerte una piedra tan grande...",
  ui_story_5028_50281201_44_dialog_content = "¿Quién es ese que llama? ¿Qué sucedió?",
  ui_story_5028_50281201_45_dialog_content = "¡Ahh!",
  ui_story_5028_50281201_46_dialog_content = "¡Glú!",
  ui_story_5028_50281201_47_dialog_content = "¿Es esto algún tipo de broma? ¿Qué? ¿El suelo está resbaladizo de repente?",
  ui_story_5028_50281201_48_dialog_content = "¡Cau cau!",
  ui_story_5028_50281201_49_dialog_content = "¿Que demonios?",
  ui_story_5028_50281201_50_dialog_content = "Como estoy... tan cansada...",
  ui_story_5028_50281201_51_dialog_content = "Uf...",
  ui_story_5028_50281201_52_dialog_content = "El plan va bien.",
  ui_story_5028_50281201_53_dialog_content = "Tienen a los bandidos en un aprieto.",
  ui_story_5028_50281201_54_dialog_content = "Nada mal. Estoy casi impresionado.",
  ui_story_5028_50281201_55_dialog_content = "Bueno, ya sabes, Fia es mi aprendiz después de todo, por lo que se espera la excelencia.",
  ui_story_5028_50281201_56_dialog_content = "¿Cómo no voy a tener éxito si soy un extrozoólogo profesional?",
  ui_story_5028_50281201_57_dialog_content = "Ni siquiera uno de los bandidos se acercó.",
  ui_story_5028_50281201_58_dialog_content = "Sólo un momento, PlayerName. Abriré la jaula y te desataré.",
  ui_story_5028_50281201_59_dialog_content = "Uf. Eso fue muy bueno de tu parte.",
  ui_story_5028_50281201_60_dialog_content = "¡Lo!",
  ui_story_5028_50281201_61_dialog_content = "Mi Kyllo! ¡Maravilloso, estás ileso!",
  ui_story_5028_50281201_62_dialog_content = "La primera fase de nuestro plan fue un éxito impresionante.",
  ui_story_5028_50281201_63_dialog_content = "Ahora es el momento de encontrar y detener a Gary.",
  ui_story_5028_50281201_64_dialog_content = "Fía.",
  ui_story_5028_50281201_65_dialog_content = "¿Por qué me miras así?",
  ui_story_5028_50281201_66_dialog_content = "¡Deja de menospreciarme!",
  ui_story_5028_50281201_67_dialog_content = "¡No quise decir eso!",
  ui_story_5028_50281201_68_dialog_content = "Al final del día, todavía eres un niño.",
  ui_story_5028_50281201_69_dialog_content = "¡Te lo dije, no lo soy!",
  ui_story_5028_50281201_70_dialog_content = "¡Deberías llamarme extrozoólogo!",
  ui_story_5028_50281201_71_dialog_content = "Multa. Un título un poco largo, si me preguntas, y difícil de recordar.",
  ui_story_5028_50281201_72_dialog_content = "¡Por qué tú...!",
  ui_story_5028_50281201_73_dialog_content = "De todos modos, tus acciones te han probado más que a la altura de tal título.",
  ui_story_5028_50281201_74_dialog_content = "Has... crecido.",
  ui_story_5028_50281201_75_dialog_content = "¿Eh?",
  ui_story_5028_50281201_76_dialog_content = "¿Estás... alabandome?",
  ui_story_5028_50281201_77_dialog_content = "Puede que no siempre esté al tanto de los detalles, ¡pero tengo verdadero talento!",
  ui_story_5028_50281201_78_dialog_content = "¡Y puedo averiguar cualquier cosa sobre mis compañeros!",
  ui_story_5028_50281201_79_dialog_content = "¡Eh! ¡Ahora sabes que soy un extrozoólogo muy poderoso!",
  ui_story_5028_50281201_80_dialog_content = "No te adelantes. Lo has hecho bien, pero todavía no nos consideraría iguales.",
  ui_story_5028_50281201_81_dialog_content = "Para que eso suceda, primero tendrías que...",
  ui_story_5028_50281201_82_dialog_content = "Me preguntaba de qué se trataba todo ese ruido. Debí haber sabido que ustedes, tontos arrepentidos, eran los responsables.",
  ui_story_5028_50281201_83_dialog_content = "¡Lo!",
  ui_story_5028_50281201_84_dialog_content = "¡El malo ha vuelto!",
  ui_story_5028_50281201_85_dialog_content = "¿Él es el que te secuestró? PlayerName?",
  ui_story_5028_50281201_86_dialog_content = "Qué patético de su parte ordenar a los Eclipsites.",
  ui_story_5028_50281201_87_dialog_content = "¿Eh? No puedo creerte y estoy de acuerdo en algo, Genevieve.",
  ui_story_5028_50281201_88_dialog_content = "¡\"Ojo a ojo\" usted mismo!",
  ui_story_5028_50281201_89_dialog_content = "Que patada tan terrible. Realmente deberíamos reducir esta base a cenizas.",
  ui_story_5028_50281201_90_dialog_content = "¡Ay! De ninguna manera. Absolutamente no.",
  ui_story_5028_50281201_91_dialog_content = "¡El lugar está lleno de Kyllos que Gary ha capturado! ¡Sería un desastre para los Kyllos!",
  ui_story_5028_50281201_92_dialog_content = "¿Qué es esto? ¿Más tontos? ¿Sin duda tuyo, brote de soja?",
  ui_story_5028_50281201_93_dialog_content = "¡No me llames brote de soja!",
  ui_story_5028_50281201_94_dialog_content = "¿Por qué todos ustedes están tan ansiosos por salvar a estos brutos?",
  ui_story_5028_50281201_95_dialog_content = "¡No son brutos, son nuestros amigos y compañeros!",
  ui_story_5028_50281201_96_dialog_content = "¿Compañeros? ¡Ja ja! No, no son compañeros. Son brutos.",
  ui_story_5028_50281201_97_dialog_content = "Crees que son compañeros. Su creencia es unilateral.",
  ui_story_5028_50281201_98_dialog_content = "Cuando las fichas están caídas, un animal es solo un animal.",
  ui_story_5028_50281201_99_dialog_content = "Solo espera hasta que no tengas más valor para ellos. Se volverán contra ti y te harán pedazos.",
  ui_story_5028_50281201_100_dialog_content = "¡Estás loco! ¡Malvado loco!",
  ui_story_5028_50281201_101_dialog_content = "Hey chico.",
  ui_story_5028_50281201_102_dialog_content = "¡Mi nombre es Fía!",
  ui_story_5028_50281201_103_dialog_content = "Lo que sea. El tipo es un loco. ¿Quién sabe qué lo motiva?",
  ui_story_5028_50281201_104_dialog_content = "No puedes convencer a alguien así del error de sus caminos. La única persuasión que entienden es...",
  ui_story_5028_50281201_105_dialog_content = "Seguir.",
  ui_story_5028_50281201_106_dialog_content = "¿Era...?",
  ui_story_5028_50281201_107_dialog_content = "Fuerza.",
  ui_story_5028_50281201_108_dialog_content = "Guau. Esta respuesta es tan Shira.",
  ui_story_5028_50281201_109_dialog_content = "¿Quieres pelear entonces?",
  ui_story_5028_50281201_110_dialog_content = "¡Ja! Maravilloso.",
  ui_story_5028_50281201_111_dialog_content = "Entonces tendré el placer de derrotarte, no una, sino dos veces. Y así será para siempre.",
  ui_story_5028_50281201_112_dialog_content = "Graaah-!!",
  ui_story_5028_50281202_1_dialog_content = "¡Kyllo, atrápalo!",
  ui_story_5028_50281202_2_dialog_content = "¡Lo!",
  ui_story_5028_50281202_3_dialog_content = "Demasiado lento y torpe para mi gusto.",
  ui_story_5028_50281202_4_dialog_content = "¡Gaaah!",
  ui_story_5028_50281202_5_dialog_content = "Revy, protege a Fia!",
  ui_story_5028_50281202_6_dialog_content = "¡No dejaré que te salgas con la tuya!",
  ui_story_5028_50281202_7_dialog_content = "¡Latigazo!",
  ui_story_5028_50281202_8_dialog_content = "¿Qué hay sobre eso? ¿Mis compañeros te muestran una cosa o dos?",
  ui_story_5028_50281202_9_dialog_content = "Err...",
  ui_story_5028_50281202_10_dialog_content = "Tienes suficientes trucos para salvar tu pellejo en el campo de batalla.",
  ui_story_5028_50281202_11_dialog_content = "Debo decir que estos aurorianos me han causado bastantes problemas, ¿no es así?",
  ui_story_5028_50281202_12_dialog_content = "¿Qué tal si probamos esto?",
  ui_story_5028_50281202_13_dialog_content = "Su látigo—es <color=#FFB400>brillante</color>!",
  ui_story_5028_50281202_14_dialog_content = "¡Cuidado, todos!",
  ui_story_5028_50281202_15_dialog_content = "¡Lo... lo...!",
  ui_story_5028_50281202_16_dialog_content = "Kyllo? Kyllo!",
  ui_story_5028_50281202_17_dialog_content = "Peko...",
  ui_story_5028_50281202_18_dialog_content = "¡psicópata! ¡¿Qué has hecho?!",
  ui_story_5028_50281202_19_dialog_content = "Todo a su tiempo, chico.",
  ui_story_5028_50281202_20_dialog_content = "¡En un momento, podrás observar a tus adorables amigos animales arrancándote el estómago de tu cuerpo!",
  ui_story_5028_50281202_21_dialog_content = "¡Nunca harían eso!",
  ui_story_5028_50281202_22_dialog_content = "¡Ataca su látigo!",
  ui_story_5028_50281202_23_dialog_content = "¡Lo se!",
  ui_story_5028_50281202_24_dialog_content = "¡Oye!",
  ui_story_5028_50281202_25_dialog_content = "No puedo creer cuántos Eclipsites tiene bajo su pulgar...",
  ui_story_5028_50281202_26_dialog_content = "Lo mejor de Eclipsites es que puedes tener tantos como quieras.",
  ui_story_5028_50281202_27_dialog_content = "Incluso si todos mueren, hay un suministro interminable de nuevos para ocupar su lugar.",
  ui_story_5028_50281202_28_dialog_content = "¡Todos ahora!",
  ui_story_5028_50281202_29_dialog_content = "<color=#e8d9bb>¡Lo!</color>",
  ui_story_5028_50281202_30_dialog_content = "¿Ese es tu Kyllo llorando?",
  ui_story_5028_50281202_31_dialog_content = "<color=#e8d9bb>Lo... ¡Lo!</color>",
  ui_story_5028_50281202_32_dialog_content = "¡N-No, no lo es!",
  ui_story_5028_50281202_33_dialog_content = "¡Sus gritos vienen de todos lados!",
  ui_story_5028_50281202_34_dialog_content = "Esto no está bien...",
  ui_story_5028_50281202_35_dialog_content = "No estaba apuntando al Kyllo de Fia, ¡sino a todos los Kyllo cautivos en su base!",
  ui_story_5028_50281202_36_dialog_content = "Oh querido. Esto no está bien.",
  ui_story_5028_50281202_37_dialog_content = "No podemos quedarnos aquí. ¡Alguien tiene que rescatarlos!",
  ui_story_5028_50281202_38_dialog_content = "Shira!",
  ui_story_5028_50281202_39_dialog_content = "¿Eh?",
  ui_story_5028_50281202_40_dialog_content = "Te llamas a ti mismo un experto en bestias maravillosas, ¿verdad?",
  ui_story_5028_50281202_41_dialog_content = "Pero estás herido. No te preocupes por la batalla. ¡Solo sácalos de aquí!",
  ui_story_5028_50281202_42_dialog_content = "¿Estás a las puertas de la muerte y, sin embargo, todo en lo que puedes pensar es en tus queridos amigos Kyllo?",
  ui_story_5028_50281202_43_dialog_content = "Es un milagro que alguno de ustedes haya sobrevivido hasta la edad adulta.",
  ui_story_5028_50281202_44_dialog_content = "Graah! ¡Rugido!",
  ui_story_5028_50281202_45_dialog_content = "¡Hora de luchar, hermanos!",
  ui_story_5028_50281202_46_dialog_content = "¡Uh!",
  ui_story_5028_50281202_47_dialog_content = "A ver cuantos consigo esta vez, uno, dos, tres...",
  ui_story_5028_50281202_48_dialog_content = "Tengo montones.",
  ui_story_5028_50281202_49_dialog_content = "¡Demasiado lento! Tendrán el lugar en llamas en poco tiempo.",
  ui_story_5028_50281202_50_dialog_content = "¿Es eso así? ¡Entonces veamos quién de nosotros puede obtener más en el menor tiempo!",
  ui_story_5028_50281202_51_dialog_content = "¡Lo, lo!",
  ui_story_5028_50281202_52_dialog_content = "¿Vic nunca te lo dijo? Las bestias maravillosas me tienen miedo.",
  ui_story_5028_50281202_53_dialog_content = "Entonces déjame asegurarte, como compañero experto, ¡que pronto será historia antigua!",
  ui_story_5028_50281202_54_dialog_content = "¿Qué?",
  ui_story_5028_50281202_55_dialog_content = "¡Vamos, Drakolion!",
  ui_story_5028_50281202_56_dialog_content = "Rugido-",
  ui_story_5028_50281202_57_dialog_content = "(Fia... llama al Drakolion.)",
  ui_story_5028_50281202_58_dialog_content = "Grr...",
  ui_story_5028_50281202_59_dialog_content = "Siento imponerte, pero ¿podrías por favor...",
  ui_story_5028_50281202_60_dialog_content = "¡Ayuda a Shira a encontrar a las otras bestias maravillosas en el bosque y aléjalas de aquí!",
  ui_story_5028_50281202_61_dialog_content = "Shira!",
  ui_story_5028_50281202_62_dialog_content = "...",
  ui_story_5028_50281202_63_dialog_content = "(Shira se acerca lentamente al Drakolion...)",
  ui_story_5028_50281202_64_dialog_content = "¡...!",
  ui_story_5028_50281202_65_dialog_content = "(Maravilloso. ¡Es aceptar su presencia!)",
  ui_story_5028_50281202_66_dialog_content = "Es real...",
  ui_story_5028_50281202_67_dialog_content = "¡Gracias, \"Extrozoóloga Fia\"!",
  ui_story_5028_50281202_68_dialog_content = "¡Entonces hazlo! ¡Ahora!",
  ui_story_5028_50281202_69_dialog_content = "¡Jajajaja!",
  ui_story_5028_50281202_70_dialog_content = "¿Por qué se está riendo?",
  ui_story_5028_50281202_71_dialog_content = "Es difícil creer el montón de idiotas que sois.",
  ui_story_5028_50281202_72_dialog_content = "¿Llevar algunas bestias y un brote de soja aquí intenta detenerme?",
  ui_story_5028_50281202_73_dialog_content = "Quería dejar lo mejor para el final, pero tengo que hacer una excepción...",
  ui_story_5028_50281202_74_dialog_content = "Déjame mostrarte por qué soy imparable.",
  ui_story_5028_50281202_75_dialog_content = "Muéstrate.",
  ui_story_5028_50281202_76_dialog_content = "Lo...",
  ui_story_5028_50281202_77_dialog_content = "¿Es esa la voz de Kyllo...?",
  ui_story_5028_50281202_78_dialog_content = "¿Ese Kyllo?",
  ui_story_5028_50281202_79_dialog_content = "¡Eso no es suficiente para asustarme!",
  ui_story_5028_50281202_80_dialog_content = "¡Lo!",
  ui_story_5028_50281202_81_dialog_content = "¡¿Ay-?!",
  ui_story_5028_50281202_82_dialog_content = "¿P-Por qué todos se ven como eclipses?",
  ui_story_5028_50281202_83_dialog_content = "¿Y por qué todos suenan como Kyllos?",
  ui_story_5028_50281202_84_dialog_content = "¡Lo, lo! ¡Lo!",
  ui_story_5028_50281202_85_dialog_content = "Esta criatura es realmente el mismo Kyllo de hace un momento.",
  ui_story_5028_50281202_86_dialog_content = "El mayor poder de Kyllos es <color=#FFB400>metamorfosis</color>.",
  ui_story_5028_50281202_87_dialog_content = "Con un poco de estímulo, cualquier Kyllo puede transformarse en la forma de cualquier criatura y usar sus habilidades.",
  ui_story_5028_50281202_88_dialog_content = "¿¡Cómo dejaste algo tan importante!?",
  ui_story_5028_50281202_89_dialog_content = "Uh, no se me había ocurrido mencionarlo hasta ahora. Además, no sabía que los Kyllos podían usar esta habilidad cuando estaban aterrorizados.",
  ui_story_5028_50281202_90_dialog_content = "En última instancia, Kyllos solo lo usará para proteger a un compañero de confianza.",
  ui_story_5028_50281202_91_dialog_content = "En realidad es más increíble de lo que esperaba...",
  ui_story_5028_50281202_92_dialog_content = "¿Seguramente este no es un momento apropiado para sonreír?",
  ui_story_5028_50281202_93_dialog_content = "¡Es aterrador! ¿Cómo vamos a lidiar con esto?",
  ui_story_5028_50281202_94_dialog_content = "Es bueno que me tengas para responder eso.",
  ui_story_5028_50281202_95_dialog_content = "Kyllos tiene un fuerte sentido de confianza y lealtad. Gana su confianza y el mundo es tu ostra.",
  ui_story_5028_50281202_96_dialog_content = "Y por supuesto, lo único que puede vencer a un Kyllo es otro Kyllo.",
  ui_story_5028_50281301_1_dialog_content = "¡Lo!",
  ui_story_5028_50281301_2_dialog_content = "¡Lo, lo!",
  ui_story_5028_50281301_3_dialog_content = "¡Maldita sea! ¡Qué podemos hacer contra los poderes de Gary!",
  ui_story_5028_50281301_4_dialog_content = "Lucha un poco más, ¿por qué no? ¡Graba el terror de este día en lo profundo de tu corazón!",
  ui_story_5028_50281301_5_dialog_content = "... Y luego tendré el placer de enviar a mis brutos a todos los rincones y grietas de todo Astra.",
  ui_story_5028_50281301_6_dialog_content = "Jaja... ¡Jajajajaja!",
  ui_story_5028_50281301_7_dialog_content = "Adiós, chico.",
  ui_story_5028_50281301_8_dialog_content = "¡Ahora, PlayerName!",
  ui_story_5028_50281301_9_dialog_content = "¡Usa tu poder para mostrarles a esos Kyllos cuánto crees y confías en Fia!",
  ui_story_5028_50281301_10_dialog_content = "¿Eh? ¿Mi poder?",
  ui_story_5028_50281301_11_dialog_content = "Ya sabes, esa cosa mental que haces. ¡Vamos, piensa!",
  ui_story_5028_50281301_12_dialog_content = "(Mi poder...)",
  ui_story_5028_50281301_13_dialog_content = "(Mi único poder es la habilidad psíquica, y eso solo ayuda a las personas a hablar entre sí).",
  ui_story_5028_50281301_14_dialog_content = "(Hablen entre ellos pero... ¡¿Fia no tiene forma de comunicarse con Kyllo?!)",
  ui_story_5028_50281301_15_dialog_content = "En pocas palabras, trate de sentir los pensamientos y sentimientos de Kyllo y transfiéralos a Fia.",
  ui_story_5028_50281301_16_dialog_content = "¡Fia se encargará del resto!",
  ui_story_5028_50281301_17_dialog_content = "¿Eh? ¿Puedo sentir los pensamientos de Kyllo?",
  ui_story_5028_50281301_18_dialog_content = "Por supuesto que puede. ¡Nunca olvides que eres un Caelestite!",
  ui_story_5028_50281301_19_dialog_content = "Está bien, ¡lo intentaré!",
  ui_story_5028_50281301_20_option_content = "¡Potencia de fuerza!",
  ui_story_5028_50281301_21_dialog_content = "Necesito sentir los pensamientos de Kyllo...",
  ui_story_5028_50281301_22_dialog_content = "¡Lo, lo! ¡Lo!",
  ui_story_5028_50281301_23_dialog_content = "Está muy asustado. Hay algo de poder que no ha usado y... parece que está siendo bloqueado para usarlos.",
  ui_story_5028_50281301_24_dialog_content = "¡Lo! ¡Lo!",
  ui_story_5028_50281301_25_dialog_content = "Siento una emoción que creo que significa que quieres proteger algo.",
  ui_story_5028_50281301_26_dialog_content = "¿Proteger algo? ¿Proteger?",
  ui_story_5028_50281301_27_dialog_content = "¡Fia! ¡Kyllo quiere protegerte!",
  ui_story_5028_50281301_28_dialog_content = "¡¿Qué?!",
  ui_story_5028_50281301_29_dialog_content = "¡Lo, lo! ¡Lo!",
  ui_story_5028_50281301_30_dialog_content = "¿Está diciendo que quiere protegerme?",
  ui_story_5028_50281301_31_dialog_content = "¡Lo, lo! ¡Lo, lo!",
  ui_story_5028_50281301_32_dialog_content = "Creo que está de acuerdo con lo que estás pensando, ¡y es realmente ansioso!",
  ui_story_5028_50281301_33_dialog_content = "Está muy ansioso... y está de acuerdo...",
  ui_story_5028_50281301_34_dialog_content = "¿Así que eso es lo que significa ese grito?",
  ui_story_5028_50281301_35_dialog_content = "¡Me lo imaginé! ¡Finalmente lo resolví!",
  ui_story_5028_50281301_36_dialog_content = "¿Lo averigué? ¿Averiguado qué?",
  ui_story_5028_50281301_37_dialog_content = "Gracias a ti, finalmente descubrí el significado de los gritos de Kyllo.",
  ui_story_5028_50281301_38_dialog_content = "En otras palabras, ¡he descifrado el lenguaje de Kyllos!",
  ui_story_5028_50281301_39_dialog_content = "¿Lo hiciste?",
  ui_story_5028_50281301_40_dialog_content = "¡Lo, lo, lo! ¡Lo, lo!",
  ui_story_5028_50281301_41_dialog_content = "¿Q-Qué está diciendo...?",
  ui_story_5028_50281301_42_dialog_content = "Está diciendo: \"Quiero proteger a Fia\".",
  ui_story_5028_50281301_43_dialog_content = "¡Lo!",
  ui_story_5028_50281301_44_dialog_content = "¿Eh? Kyllo, ¿estás diciendo que hablar conmigo te ha dado nuevos poderes?",
  ui_story_5028_50281301_45_dialog_content = "¡Entonces úsalo!",
  ui_story_5028_50281301_46_dialog_content = "¡Guau, el Kyllo está brillando!",
  ui_story_5028_50281301_47_dialog_content = "El Kyllo está cambiando de forma...",
  ui_story_5028_50281301_48_dialog_content = "¡Fia y Kyllo, usen su nuevo poder para derrotar a Gary!",
  ui_story_5028_50281301_49_dialog_content = "Gracias por el comentario. ¡Lo conseguimos!",
  ui_story_5028_50281301_50_dialog_content = "¿Crees que puedes vencerme? Debes estar soñando.",
  ui_story_5028_50281301_51_dialog_content = "Adelante pues, mis criaturas. ¡Aplastarlos!",
  ui_story_5028_50281301_52_dialog_content = "*Rugido*",
  ui_story_5028_50281301_53_dialog_content = "¡Lo!",
  ui_story_5028_50281302_1_dialog_content = "¡Ve, Kyllo, y enséñale a este hombre malvado que no debemos ser intimidados!",
  ui_story_5028_50281302_2_dialog_content = "¡Lo!",
  ui_story_5028_50281302_3_dialog_content = "¿Cómo?",
  ui_story_5028_50281302_4_dialog_content = "¡Lo! ¡Lo, lo, lo!",
  ui_story_5028_50281302_5_dialog_content = "El Kyllo de Gary grita de dolor.",
  ui_story_5028_50281302_6_dialog_content = "Kyllo...",
  ui_story_5028_50281302_7_dialog_content = "Kyllo! ¡Ve por el látigo de Gary!",
  ui_story_5028_50281302_8_dialog_content = "Lo!!!",
  ui_story_5028_50281302_9_dialog_content = "¡Uh!",
  ui_story_5028_50281302_10_dialog_content = "¡El tiempo es ahora!",
  ui_story_5028_50281302_11_dialog_content = "¡Mira!",
  ui_story_5028_50281302_12_dialog_content = "¡Quema!",
  ui_story_5028_50281302_13_dialog_content = "¡Latigazo!",
  ui_story_5028_50281302_14_dialog_content = "¡Todos los Eclipsites están derrotados!",
  ui_story_5028_50281302_15_dialog_content = "Tengo el último enemigo. Así que realmente fue mi victoria.",
  ui_story_5028_50281302_16_dialog_content = "Te las arreglaste para meter un pequeño snipe allí, querida Genevieve.",
  ui_story_5028_50281302_17_dialog_content = "Pero en realidad, ese último tipo era mío.",
  ui_story_5028_50281302_18_dialog_content = "Simplemente lo golpeaste con tu látigo al final, creo.",
  ui_story_5028_50281302_19_dialog_content = "¿Los sacamos a todos?",
  ui_story_5028_50281302_20_dialog_content = "¿Lo hicimos...?",
  ui_story_5028_50281302_21_dialog_content = "¡Lo!",
  ui_story_5028_50281302_22_dialog_content = "¡Sí!",
  ui_story_5028_50281302_23_dialog_content = "Asqueroso...",
  ui_story_5028_50281302_24_dialog_content = "¡Todos los Kyllos han sido liberados del control de Gary!",
  ui_story_5028_50281302_25_dialog_content = "PlayerName, ¡usa tu poder para transmitir los pensamientos de Fia a ese otro Kyllo como lo hiciste antes!",
  ui_story_5028_50281302_26_dialog_content = "¡Ok!",
  ui_story_5028_50281302_27_option_content = "¡Potencia de fuerza!",
  ui_story_5028_50281302_28_dialog_content = "¿Eres un compañero Kyllo?",
  ui_story_5028_50281302_29_dialog_content = "¡Ya no tienes que tenerle miedo a ese hombre malvado y desagradable!",
  ui_story_5028_50281302_30_dialog_content = "Te liberamos de su control. ¡Él nunca podrá obligarte a hacer algo que no quieras hacer nunca más!",
  ui_story_5028_50281302_31_dialog_content = "Ya no tienes que pelear. Ven y únete a nosotros.",
  ui_story_5028_50281302_32_dialog_content = "Soy extrozoólogo y te protegeré.",
  ui_story_5028_50281302_33_dialog_content = "Lo... Lo?",
  ui_story_5028_50281302_34_dialog_content = "¡Lo!",
  ui_story_5028_50281302_35_dialog_content = "No te preocupes. No soy como el hombre malo allí. Te cuidaré bien.",
  ui_story_5028_50281302_36_dialog_content = "...",
  ui_story_5028_50281302_37_dialog_content = "Oh querido. La crueldad de Gary es todo lo que Kyllo ha conocido. ¡Me temo que lo ha llevado a un punto de quiebre psicológico!",
  ui_story_5028_50281302_38_dialog_content = "Tenemos que salir de aquí ahora mismo. Llevará tiempo enseñarle otra forma de vida.",
  ui_story_5028_50281302_39_dialog_content = "¡No dejaré que mis sueños de justicia, de venganza, fracasen por culpa de un montón de tontos como tú!",
  ui_story_5028_50281302_40_dialog_content = "¡Ríndete a mí, bestia!",
  ui_story_5028_50281302_41_dialog_content = "¡Se acabó el tiempo de descanso!",
  ui_story_5028_50281302_42_dialog_content = "¡Lo... Lo...!",
  ui_story_5028_50281302_43_dialog_content = "El Kyllo ha estado constantemente gritando de dolor, ¿no es así?",
  ui_story_5028_50281302_44_dialog_content = "¡Basta, Gary!",
  ui_story_5028_50281302_45_dialog_content = "¿Vas a torturarlo?",
  ui_story_5028_50281302_46_dialog_content = "torturarlo?",
  ui_story_5028_50281302_47_dialog_content = "¡Qué buena idea!",
  ui_story_5028_50281302_48_dialog_content = "¿De qué otra manera me temerá?",
  ui_story_5028_50281302_49_dialog_content = "Y si no me teme, ¿cómo puedo usar su mayor poder?",
  ui_story_5028_50281302_50_dialog_content = "¡Ahora usa todo tu poder para destruirlos!",
  ui_story_5028_50281302_51_dialog_content = "¡O conocerás el verdadero dolor en mis manos!",
  ui_story_5028_50281302_52_dialog_content = "¡Lo, lo! ¡Lo!",
  ui_story_5028_50281302_53_dialog_content = "¡Lo!",
  ui_story_5028_50281302_54_dialog_content = "¿Oh, no? qué hacemos? ¡Está pidiendo ayuda a gritos!",
  ui_story_5028_50281302_55_dialog_content = "¿Deberíamos vencerlo de nuevo?",
  ui_story_5028_50281302_56_dialog_content = "¡Lo!",
  ui_story_5028_50281302_57_dialog_content = "¡Basta, Fía!",
  ui_story_5028_50281302_58_dialog_content = "El Kyllo es tremendamente débil ahora. No sobrevivirá a otro golpe.",
  ui_story_5028_50281302_59_dialog_content = "Bueno, entonces, ¿qué crees que deberíamos hacer, Maestro?",
  ui_story_5028_50281302_60_dialog_content = "Con un Kyllo tan lejos, creo que realmente depende del destino y la suerte.",
  ui_story_5028_50281302_61_dialog_content = "Me reuso a creerlo. ¡He aprendido a no confiar en ti!",
  ui_story_5028_50281302_62_dialog_content = "¡Ja ja! Reza por buena suerte entonces. Esa es tu última esperanza de todos modos.",
  ui_story_5028_50281302_63_dialog_content = "Ahora es el momento de—",
  ui_story_5028_50281302_64_dialog_content = "Sinceramente, no soporto pelear. Es la peor parte de esto.",
  ui_story_5028_50281302_65_dialog_content = "¡¿De donde vino eso?!",
  ui_story_5028_50281302_66_dialog_content = "¡Pero cualquier cosa es mejor que dejar libre a alguien como tú!",
  ui_story_5028_50281302_67_dialog_content = "¡¡¡Rugido!!!",
  ui_story_5028_50281302_68_dialog_content = "¡Ay! Cómo hizo...",
  ui_story_5028_50281302_69_option_content = "Eso fue suerte... ¡Se convirtió en Shira!",
  ui_story_5028_50281302_70_option_content = "¡Shira golpea el suelo y envía a Gary por los aires con una patada!",
  ui_story_5028_50281302_71_dialog_content = "Nada que ver con la suerte en absoluto.",
  ui_story_5028_50281302_72_dialog_content = "Solo una transformación cualitativa de todos mis esfuerzos hasta ahora.",
  ui_story_5028_50281302_73_dialog_content = "Shira!",
  ui_story_5028_50281302_74_dialog_content = "Tuve suerte de tener la previsión de decirle al Drakolion que ayudara a Shira a salvar a los demás.",
  ui_story_5028_50281302_75_dialog_content = "¡Esa fue la clave para detener el complot de Gary!",
  ui_story_5028_50281302_76_dialog_content = "Y estaba listo para decir lo maduro que has crecido...",
  ui_story_5028_50281302_77_dialog_content = "Lo...",
  ui_story_5028_50281302_78_dialog_content = "¿Eh?",
  ui_story_5028_50281302_79_dialog_content = "¿Lo, lo?",
  ui_story_5028_50281302_80_dialog_content = "No puedo imaginar las torturas que esta pobre criatura ha sufrido bajo Gary.",
  ui_story_5028_50281302_81_dialog_content = "¿Por qué no le damos un respiro?",
  ui_story_5028_50281302_82_dialog_content = "¿Qué vamos a hacer con el Sr. Public Enemy Number One?",
  ui_story_5028_50281302_83_dialog_content = "*Tose*... ¡Uf!",
  ui_story_5028_50281302_84_dialog_content = "(Shira levanta a Gary por uno de sus tentáculos y lo acerca.)",
  ui_story_5028_50281302_85_dialog_content = "(Parece llena de rabia asesina.)",
  ui_story_5028_50281302_86_dialog_content = "(¡Ella es aterradora!)",
  ui_story_5028_50281302_87_dialog_content = "Lo, lo, lo...",
  ui_story_5028_50281302_88_dialog_content = "Eh... Parece que... He sido... derrotado al fin...",
  ui_story_5028_50281302_89_dialog_content = "Será mejor que me mates.",
  ui_story_5028_50281302_90_dialog_content = "Quizás era mi destino morir a manos de estos brutos después de todo.",
  ui_story_5028_50281302_91_dialog_content = "Es demasiado peligroso para vivir.",
  ui_story_5028_50281302_92_dialog_content = "Creo que, por el bien mayor, debemos...",
  ui_story_5028_50281302_93_dialog_content = "Digo que escuchemos primero a nuestro principal arquitecto del éxito de hoy: escuchemos su opinión, Fia. ¿Qué crees que deberíamos hacerle?",
  ui_story_5028_50281302_94_dialog_content = "...",
  ui_story_5028_50281302_95_dialog_content = "¿Fia?",
  ui_story_5028_50281302_96_dialog_content = "¡Obviamente, deberíamos dejar que este malvado se pudra en prisión por sus crímenes!",
  ui_story_5028_50281302_97_dialog_content = "¿Eh?",
  ui_story_5028_50281302_98_dialog_content = "¿Eh? ¿Podredumbre en la cárcel?",
  ui_story_5028_50281302_99_dialog_content = "No creas que voy a dejar de tramar venganza después de que salga.",
  ui_story_5028_50281302_100_dialog_content = "¡Y entonces yo, la extrozoóloga Fia, tendré que detenerte de nuevo!",
  ui_story_5028_50281302_101_dialog_content = "Podrás ver cuán poderosas se han vuelto mis maravillosas bestias bajo mi protección en ese tiempo—",
  ui_story_5028_50281302_102_dialog_content = "¡Ese será tu mayor castigo!",
  ui_story_5028_50281302_103_dialog_content = "Bien hecho. Un discurso muy impresionante.",
  ui_story_5028_50281302_104_dialog_content = "¡Dios mío! Te pareces a Shira. ¿Pero eres un hombre pulpo?",
  ui_story_5028_50281302_105_dialog_content = "Dios mío. Realmente duele oírte decir eso.",
  ui_story_5028_50281302_106_dialog_content = "Kleken, ¿estar aquí significa que el Señor de las Sombras...?",
  ui_story_5028_50281302_107_dialog_content = "El momento no podría haber sido más perfecto, PlayerName. Tienes en tus manos al mismísimo bandido que busca el Señor de las Sombras.",
  ui_story_5028_50281302_108_dialog_content = "Dada la molestia que ha sido, sería más sorprendente que el Señor de las Sombras no se interesara.",
  ui_story_5028_50281302_109_dialog_content = "Muy cierto, señora.",
  ui_story_5028_50281302_110_dialog_content = "Gary, hace diez años, tu esposa y tu hijo tropezaron con el territorio de las bestias maravillosas, donde fueron tristemente asesinados por un grupo de bestias maravillosas.",
  ui_story_5028_50281302_111_dialog_content = "Y desde ese día te ocupaste de matar y capturar bestias maravillosas de todo tipo.",
  ui_story_5028_50281302_112_dialog_content = "Si simplemente te hubieras limitado a eso, el Señor de las Sombras no se habría involucrado.",
  ui_story_5028_50281302_113_dialog_content = "Pero sus comportamientos recientes han cruzado una línea que amenaza incluso al mismo Umbraton.",
  ui_story_5028_50281302_114_dialog_content = "¿Amenaza a Umbratón? Seguramente no...",
  ui_story_5028_50281302_115_dialog_content = "De hecho, querida.",
  ui_story_5028_50281302_116_dialog_content = "Muchas bestias maravillosas eligen hacer su morada cerca de Umbraton y son un componente importante de su defensa.",
  ui_story_5028_50281302_117_dialog_content = "Las bestias expulsan cualquier amenaza peligrosa de sus ecosistemas, incluidos los eclipses.",
  ui_story_5028_50281302_118_dialog_content = "La presencia de Eclipsite cerca de Umbraton ha impulsado a las maravillosas bestias a construir un muro intangible que separa a los aurorianos de la amenaza de Eclipsite.",
  ui_story_5028_50281302_119_dialog_content = "Por supuesto, la desaparición de las bestias expondría a Umbraton a un ataque directo de Eclipsite.",
  ui_story_5028_50281302_120_dialog_content = "Entonces eso es...",
  ui_story_5028_50281302_121_dialog_content = "¿Eh? ¿Señor de la sombra?",
  ui_story_5028_50281302_122_dialog_content = "Si el Señor de las Sombras es tan grande y poderoso, ¿por qué no intervino hace tantos años para proteger a mi esposa e hijo?",
  ui_story_5028_50281302_123_dialog_content = "Al fin y al cabo, ¿no vivimos todos bajo sus supuestas \"leyes\"?",
  ui_story_5028_50281302_124_dialog_content = "El Señor de las Sombras hace cumplir sus leyes en Umbraton, pero esto sin mencionar el bosque.",
  ui_story_5028_50281302_125_dialog_content = "En última instancia, el respeto por sus dictados requiere su manifestación.",
  ui_story_5028_50281302_126_dialog_content = "¡Bah! Sólo si fuera así de simple.",
  ui_story_5028_50281302_127_dialog_content = "Gary.",
  ui_story_5028_50281302_128_dialog_content = "¿Qué? ¿Tienes más palabras de sabiduría?",
  ui_story_5028_50281302_129_dialog_content = "¿O querías tomar tu propia oportunidad conmigo por nuestra amistad de corta duración?",
  ui_story_5028_50281302_130_dialog_content = "Lo que sea. No me importa. No voy a cambiar de opinión sobre nada.",
  ui_story_5028_50281302_131_dialog_content = "Nadie me puede parar. ¡Nadie!",
  ui_story_5028_50281302_132_dialog_content = "... No es su llamada a hacer.",
  ui_story_5028_50281302_133_dialog_content = "Entrenar bestias maravillosas para que se maten unas a otras podría conducir en última instancia a la extinción de toda la vida exótica en este planeta...",
  ui_story_5028_50281302_134_dialog_content = "Incluso si el Señor de las Sombras no hubiera hecho nada para detenerte, otros, incluida esta dama, lo habrían hecho en su lugar.",
  ui_story_5028_50281302_135_dialog_content = "Gary.",
  ui_story_5028_50281302_136_dialog_content = "¿Sabes por qué solo tengo un ala?",
  ui_story_5028_50281302_137_dialog_content = "No sé. ¿Asi que?",
  ui_story_5028_50281302_138_dialog_content = "¿Eh?",
  ui_story_5028_50281302_139_option_content = "¿Por qué?",
  ui_story_5028_50281302_140_dialog_content = "Me di cuenta de eso desde que nos conocimos, pero siempre rozaste el tema.",
  ui_story_5028_50281302_141_dialog_content = "Estaba tan cautivado con las bestias maravillosas incluso cuando era niño. Me encantó conocer de cerca y personal con ellos.",
  ui_story_5028_50281302_142_dialog_content = "Pero no entendí muy bien cómo funcionaban sus mentes entonces. Así que una vez terminé irritando a la maravillosa bestia equivocada.",
  ui_story_5028_50281302_143_dialog_content = "Atacó, arrancando la mitad de mi ala con su mandíbula, dejándome con esto.",
  ui_story_5028_50281302_144_dialog_content = "¿Ves lo que pueden hacer? ¿Y no estabas enojado por ser tratado así?",
  ui_story_5028_50281302_145_dialog_content = "Estaba confundido y enojado hasta que cierto amigo me mostró algo diferente.",
  ui_story_5028_50281302_146_dialog_content = "Nosotros, los aurorianos, somos tan confusos e indescifrables para las maravillosas bestias como ellos lo son para nosotros.",
  ui_story_5028_50281302_147_dialog_content = "Sus instintos les dicen que teman y duden de nosotros. La criatura atacó solo en defensa propia cuando me acerqué demasiado.",
  ui_story_5028_50281302_148_dialog_content = "¿Y no es eso exactamente lo que les hacemos a veces también?",
  ui_story_5028_50281302_149_dialog_content = "Desde su perspectiva, es probable que los aurorianos salgan a cazarlos o capturarlos, o invadir sus tierras.",
  ui_story_5028_50281302_150_dialog_content = "Y si mi amigo no hubiera usado sus poderes telepáticos para ayudarme a comunicarme con las criaturas...",
  ui_story_5028_50281302_151_dialog_content = "Puede que nunca haya tenido la oportunidad de saber real y verdaderamente lo que sienten por nosotros.",
  ui_story_5028_50281302_152_dialog_content = "Esa fue la clave que me permitió comprenderlos y finalmente perdonarlos.",
  ui_story_5028_50281302_153_dialog_content = "No somos lo mismo.",
  ui_story_5028_50281302_154_dialog_content = "Decidiste perdonarlos. Eso no dice nada sobre lo que piensan.",
  ui_story_5028_50281302_155_dialog_content = "¡Mi familia fue asesinada!",
  ui_story_5028_50281302_156_dialog_content = "Y, según tengo entendido, después empezaste a cazarlos solo en el bosque, ¿correcto?",
  ui_story_5028_50281302_157_dialog_content = "Derecha. Maté a muchos de ellos. Ninguno sobrevivió.",
  ui_story_5028_50281302_158_dialog_content = "Entonces mataste a los culpables, completa y completamente logrando venganza. Entonces, ¿por qué continuar? ¿Por qué someter a otros exóticos al mismo destino?",
  ui_story_5028_50281302_159_dialog_content = "Y mucho menos someterlos a una campaña de miedo dirigida a los aurorianos.",
  ui_story_5028_50281302_160_dialog_content = "¡Obviamente para mostrarles a todos que estos brutos no se parecen en nada a los aurorianos y merecen morir!",
  ui_story_5028_50281302_161_dialog_content = "Si las maravillosas bestias fueran realmente tan horribles como crees...",
  ui_story_5028_50281302_162_dialog_content = "Y apuntó deliberadamente a su familia, destruyendo su felicidad y cualquier posibilidad de una vida normal...",
  ui_story_5028_50281302_163_dialog_content = "Entonces, ¿en qué eres diferente, dada tu campaña para masacrarlos a todos indiscriminadamente?",
  ui_story_5028_50281302_164_dialog_content = "¡...!",
  ui_story_5028_50281302_165_dialog_content = "Todavía te quedan muchos años de vida, mi viejo amigo. Espero que uses el resto para pensar realmente en lo que estás haciendo.",
  ui_story_5028_50281302_166_dialog_content = "No tengo nada más que agregar, Sr. Pulpo Misterioso.",
  ui_story_5028_50281302_167_dialog_content = "¿Vaya? ¿Has terminado?",
  ui_story_5028_50281302_168_dialog_content = "Entonces por favor escucha mi petición.",
  ui_story_5028_50281302_169_dialog_content = "Bien. Apreciaría que todos los presentes pudieran entregarlo a él y a sus subordinados al Señor de las Sombras.",
  ui_story_5028_50281302_170_dialog_content = "El Señor de las Sombras se ha comprometido a dar a este criminal el castigo debido para proteger la seguridad de Umbraton.",
  ui_story_5028_50281302_171_dialog_content = "Con respecto a la sentencia de prisión que mencionó Milady, haré todo lo posible para transmitir sus deseos al Señor de las Sombras.",
  ui_story_5028_50281302_172_dialog_content = "No tengo objeciones. ¿Qué pasa con el resto de ustedes?",
  ui_story_5028_50281302_173_dialog_content = "Puede que Shadowlord no comparta nuestra pasión por la investigación exótica, pero es un experto cuando se trata de castigar a los criminales.",
  ui_story_5028_50281302_174_dialog_content = "Será difícil montar una prisión solo para él.",
  ui_story_5028_50281302_175_dialog_content = "Estoy seguro de que el Señor de las Sombras tiene muchos lugares para ocultar amenazas a la sociedad.",
  ui_story_5028_50281302_176_dialog_content = "Estoy de acuerdo.",
  ui_story_5028_50281302_177_dialog_content = "¡Mientras pase mucho tiempo en prisión, estoy bien con eso!",
  ui_story_5028_50281302_178_option_content = "Tienes tu deseo, Kleken.",
  ui_story_5028_50281302_179_option_content = "Aún así, muchas gracias.",
  ui_story_5028_50281302_180_dialog_content = "Entonces, todos, ¿puedo obtener su ayuda para transportar a estos bandidos de regreso a Umbraton conmigo?",
  ui_story_5028_50281302_181_dialog_content = "¿Quieres ayuda? Claro.",
  ui_story_5028_50281302_182_dialog_content = "Oh, no. Otra tarea aburrida.",
  ui_story_5028_50281302_183_dialog_content = "No veo cómo podemos realmente ayudar. Deberíamos entregar las otras criaturas aquí a un profesional o algo para ayudarlas.",
  ui_story_5028_50281302_184_dialog_content = "¡Sí!",
  ui_story_5028_50281302_185_dialog_content = "Regresaré a mi misión entonces. Adiós a todos.",
  ui_story_5028_50281302_186_dialog_content = "Solo espero que nunca tengamos que volver a ver su cara de pena.",
  ui_story_5028_50281302_187_dialog_content = "Bueno, no creo que sea lo último que hemos visto de Gary.",
  ui_story_5028_50281401_1_dialog_content = "El final de todo lo desagradable es suficiente para estar agradecido.",
  ui_story_5028_50281401_2_dialog_content = "Estoy impresionado de lo poderosos que son los Kyllos.",
  ui_story_5028_50281401_3_dialog_content = "Y aquí pensé que tu referencia a la invencibilidad era solo un truco para atrapar a Gary.",
  ui_story_5028_50281401_4_dialog_content = "Nunca engañaría a un aprendiz mío anterior o actual, ya sea Gary, Shira o Fia, mis estimados aprendices.",
  ui_story_5028_50281401_5_dialog_content = "Él no es intencionalmente engañoso.",
  ui_story_5028_50281401_6_dialog_content = "Verás, Shira lo dijo ella misma.",
  ui_story_5028_50281401_7_dialog_content = "Sus problemas de credibilidad tienen más que ver con la falta de fiabilidad que con cualquier otra cosa.",
  ui_story_5028_50281401_8_dialog_content = "Shira, me duele hasta el borde de las lágrimas oírte decir eso...",
  ui_story_5028_50281401_9_dialog_content = "Pero no entiendo cómo mi Kyllo podría tener todo este poder y aún así no usarlo antes, ¿incluso en peligro?",
  ui_story_5028_50281401_10_dialog_content = "No, espera, lo más extraño es...",
  ui_story_5028_50281401_11_dialog_content = "¿Cómo vamos a explicar la sorprendente falta de éxito del Maestro Vic dadas todas las poderosas y maravillosas bestias a su alcance?",
  ui_story_5028_50281401_12_dialog_content = "Derecha. ¡Eso es realmente extraño!",
  ui_story_5028_50281401_13_dialog_content = "...",
  ui_story_5028_50281401_14_dialog_content = "Dios... Déjame.",
  ui_story_5028_50281401_15_dialog_content = "Kyllo es una especie muy especial con habilidades únicas.",
  ui_story_5028_50281401_16_dialog_content = "Sin embargo, estas habilidades solo se despliegan en conversaciones con otras criaturas que comparten un vínculo de confianza.",
  ui_story_5028_50281401_17_dialog_content = "Lamentablemente, a medida que el número de Kyllos ha disminuido, también lo ha hecho su capacidad para comunicarse entre sí.",
  ui_story_5028_50281401_18_dialog_content = "Y dada la extraordinaria gama de características de Kyllo y las diferencias en el lenguaje corporal, se ha vuelto casi imposible para los demás obtener una comprensión precisa.",
  ui_story_5028_50281401_19_dialog_content = "Es por eso que tan pocos Aurorianos pueden comunicarse con los Kyllos.",
  ui_story_5028_50281401_20_dialog_content = "A veces, incluso los propios Kyllos luchan por comprender el significado de los gritos de los demás.",
  ui_story_5028_50281401_21_dialog_content = "Todo esto ha aumentado severamente la tasa de mortalidad infantil entre los Kyllos en estado salvaje.",
  ui_story_5028_50281401_22_dialog_content = "De hecho, todos los Kyllos que observaste en ese hábitat fueron criados personalmente por Vic hasta la edad adulta.",
  ui_story_5028_50281401_23_dialog_content = "¿Es el Maestro tan brillante?",
  ui_story_5028_50281401_24_dialog_content = "Entonces, si los Kyllos no pueden comunicarse con nosotros, ¿cómo descubrió el Maestro todo esto?",
  ui_story_5028_50281401_25_dialog_content = "Hay un método que puede permitirle a alguien entender lo que Kyllo está pensando real y verdaderamente, y es...",
  ui_story_5028_50281401_26_option_content = "¿Yo?",
  ui_story_5028_50281401_27_dialog_content = "Específicamente, la habilidad psíquica de los Caelestites.",
  ui_story_5028_50281401_28_option_content = "Caelestitas...?",
  ui_story_5028_50281401_29_dialog_content = "Sí.",
  ui_story_5028_50281401_30_dialog_content = "Las habilidades psíquicas de Caelestites son capaces de salvar directamente la barrera del idioma y percibir los pensamientos de Kyllos.",
  ui_story_5028_50281401_31_dialog_content = "Esta comprensión constituye la clave para descifrar la relación entre los gritos y pensamientos de Kyllo y luego el lenguaje mismo.",
  ui_story_5028_50281401_32_dialog_content = "Fue entonces cuando finalmente descubrí tu talento especial, Fia, cuando pudiste entenderlos tan rápido.",
  ui_story_5028_50281401_33_dialog_content = "Y es por eso que la primera tarea que me dio mi Maestro fue capturar una Caelestite, ¿verdad?",
  ui_story_5028_50281401_34_dialog_content = "Correcto. La \"comunicación\" es el factor más importante que se necesita para desbloquear el verdadero potencial de Kyllo.",
  ui_story_5028_50281401_35_dialog_content = "Entonces, ¿cómo es que yo también pude entender lo que Kyllo estaba diciendo?",
  ui_story_5028_50281401_36_dialog_content = "Debido a todos sus viajes juntos, sospecho que Kyllo lo consideró un amigo.",
  ui_story_5028_50281401_37_dialog_content = "Pero entonces, ¿cómo usó el Kyllo de Gary el mismo poder?",
  ui_story_5028_50281401_38_dialog_content = "No estoy seguro.",
  ui_story_5028_50281401_39_dialog_content = "Supongo que puede ser un efecto del látigo.",
  ui_story_5028_50281401_40_dialog_content = "Ese látigo terrible es capaz de subyugar la mente de una bestia maravillosa con una huella terrible.",
  ui_story_5028_50281401_41_dialog_content = "El miedo es igual y el extremo opuesto del amor. El terror extremo de Kyllo desató una horrible metamorfosis.",
  ui_story_5028_50281401_42_dialog_content = "Mmm. ¡Eso no es exactamente lo que yo llamaría \"comunicación\"!",
  ui_story_5028_50281401_43_dialog_content = "¡Esa debe ser la razón por la que finalmente no pudo vencerme, un extrozoólogo, y lograr ningún tipo de conexión real con su Kyllo!",
  ui_story_5028_50281401_44_dialog_content = "¿Crees que Vic fue consciente de todo esto todo el tiempo?",
  ui_story_5028_50281401_45_dialog_content = "No necesariamente.",
  ui_story_5028_50281401_46_dialog_content = "Una vez tuvo un amigo caelestita.",
  ui_story_5028_50281401_47_dialog_content = "Este amigo lo ayudó a comunicarse con éxito con Kyllo y a comprender más sobre estas magníficas criaturas.",
  ui_story_5028_50281401_48_dialog_content = "Hasta hace diecisiete años.",
  ui_story_5028_50281401_49_dialog_content = "Espera, ¿Vic siempre se ha descrito a sí mismo como un \"eterno joven de 18 años\"?",
  ui_story_5028_50281401_50_dialog_content = "¿Exactamente cuántos años tiene entonces?",
  ui_story_5028_50281401_51_dialog_content = "Tos, está bien entonces. No nos pasemos el día hurgando en el pasado, ¿de acuerdo?",
  ui_story_5028_50281401_52_dialog_content = "Creo que tenemos bastantes cosas que hacer aquí tal como están las cosas.",
  ui_story_5028_50281401_53_dialog_content = "¡Lo! ¡Lo!",
  ui_story_5028_50281401_54_dialog_content = "¿Qué es? ¿Quieres que lo mire?",
  ui_story_5028_50281401_55_dialog_content = "Lo... lo...",
  ui_story_5028_50281401_56_dialog_content = "Su... Su situación se ha deteriorado rápidamente.",
  ui_story_5028_50281401_57_dialog_content = "Oh querido. Debe ser el resultado de vivir bajo un régimen de puro terror y sufrimiento durante tanto tiempo.",
  ui_story_5028_50281401_58_dialog_content = "Fue gravemente herido en la batalla hace un momento. Me temo que su vida se está escapando.",
  ui_story_5028_50281401_59_dialog_content = "¿Hay alguien aquí capaz de curarlo con Luminatics?",
  ui_story_5028_50281401_60_dialog_content = "...",
  ui_story_5028_50281401_61_dialog_content = "¡Rápido! ¡Será mejor que encontremos a alguien que pueda ayudarnos en Umbraton! ¡Debería haber tiempo!",
  ui_story_5028_50281401_62_dialog_content = "¡Drakolion, ayúdanos!",
  ui_story_5028_50281401_63_dialog_content = "¡Sin tiempo, sin tiempo!",
  ui_story_5028_50281401_64_dialog_content = "¡Lo!",
  ui_story_5028_50281401_65_dialog_content = "¿Eh? K-Kyllo?!",
  ui_story_5028_50281401_66_dialog_content = "¡Lo! ¡Lo! ¡Lo!",
  ui_story_5028_50281401_67_dialog_content = "Son todos los Kyllos que acabo de sacar...",
  ui_story_5028_50281401_68_dialog_content = "¿Ellos volvieron?",
  ui_story_5028_50281401_69_dialog_content = "¡Lo! ¡Lo, lo!",
  ui_story_5028_50281401_70_dialog_content = "¿Quieres decir que si puedo comunicarme con ellos, entonces nos ayudarán?",
  ui_story_5028_50281401_71_dialog_content = "¡OK trataré!",
  ui_story_5028_50281401_72_dialog_content = "¡Escúchame, oh Kyllos, ayúdanos a salvarlo!",
  ui_story_5028_50281401_73_dialog_content = "Ayúdanos...",
  ui_story_5028_50281401_74_dialog_content = "Ayúdalo...",
  ui_story_5028_50281401_75_dialog_content = "¡Lo!",
  ui_story_5028_50281401_76_dialog_content = "¡Lo, lo, lo!",
  ui_story_5028_50281401_77_dialog_content = "¡Es la misma luminiscencia que rodeó al Kyllo de Fia en la batalla!",
  ui_story_5028_50281401_78_dialog_content = "Será mejor que te sientes y observes.",
  ui_story_5028_50281401_79_dialog_content = "Es posible que te encuentres en una experiencia única en la vida.",
  ui_story_5028_50281401_80_dialog_content = "El Caelestite ayuda a Fia a comunicarse con los Kyllos para desbloquear su extraordinario poder...",
  ui_story_5028_50281401_81_dialog_content = "Lo, lo, lo-",
  ui_story_5028_50281401_82_dialog_content = "La luz del Kyllos envuelve al herido Kyllo...",
  ui_story_5028_50281401_83_dialog_content = "Sus heridas, ¡se está curando!",
  ui_story_5028_50281401_83X_dialog_content = "¡Así de poderoso es Kyllo!",
  ui_story_5028_50281401_84_dialog_content = "Ser capaz de imitar las habilidades de otras bestias maravillosas y Aurorianos...",
  ui_story_5028_50281401_85_dialog_content = "\"Extraordinario\" no es una exageración.",
  ui_story_5028_50281401_86_dialog_content = "Parece que no estaba muy equivocado cuando dije que \"el mundo sería tu ostra\".",
  ui_story_5028_50281401_87_dialog_content = "Ok...",
  ui_story_5028_50281401_88_option_content = "Asombroso.",
  ui_story_5028_50281401_89_dialog_content = "No eres tan malo tú mismo, PlayerName.",
  ui_story_5028_50281401_90_dialog_content = "¿Eh?",
  ui_story_5028_50281401_91_option_content = "Soy un poco celoso...",
  ui_story_5028_50281401_92_dialog_content = "Haría un trabajo mucho mejor protegiendo a mis amigos si tuviera ese tipo de poder...",
  ui_story_5028_50281401_93_dialog_content = "Tienes mucho poder tal como es: el poder de la comunicación perfecta entre individuos divergentes.",
  ui_story_5028_50281401_94_dialog_content = "Puede que no sea mucho en combate, pero no subestimes el poder de ayudar a las personas a entenderse entre sí.",
  ui_story_5028_50281401_95_dialog_content = "El poder de disipar conceptos erróneos, desenredar viejos odios y evitar que estallen peleas en primer lugar.",
  ui_story_5028_50281401_96_dialog_content = "Ok...",
  ui_story_5028_50281401_97_dialog_content = "¡Entendido!",
  ui_story_5028_50281401_98_dialog_content = "Mira, que Kyllo parece haber recuperado sus fuerzas.",
  ui_story_5028_50281401_99_dialog_content = "Lo... Lo?",
  ui_story_5028_50281401_100_dialog_content = "¡Estás curado!",
  ui_story_5028_50281401_101_dialog_content = "¡Todos trabajando juntos te han sanado!",
  ui_story_5028_50281401_102_dialog_content = "¡Lo, lo! ¡Lo!",
  ui_story_5028_50281401_103_dialog_content = "¡Ah, y también gracias a su extrozoólogo residente!",
  ui_story_5028_50281401_104_dialog_content = "¡Lo, lo, lo!",
  ui_story_5028_50281401_105_dialog_content = "¡Guau! ¡Jaja, eso hace cosquillas!",
  ui_story_5028_50281401_106_dialog_content = "De todos modos, creo que ya es hora de que nos vayamos y llevemos a estas criaturas a un hábitat mucho más adecuado.",
  ui_story_5028_50281401_107_dialog_content = "¿Eh? ¿Kyllo volverá?",
  ui_story_5028_50281401_108_dialog_content = "¡Lo!",
  ui_story_5028_50281401_109_dialog_content = "Tú... ¿Me vas a dejar, Kyllo?",
  ui_story_5028_50281401_110_dialog_content = "¿No crees que podrías quedarte?",
  ui_story_5028_50281401_111_dialog_content = "Lo...",
  ui_story_5028_50281401_112_dialog_content = "¡Lo-woo!",
  ui_story_5028_50281401_113_dialog_content = "¿N-No lo crees? P-Pero...",
  ui_story_5028_50281401_114_dialog_content = "Todavía un niño, al final del día.",
  ui_story_5028_50281401_115_dialog_content = "Un investigador puro no solo debe comprender sino también respetar los hábitos y deseos instintivos de las criaturas que observa.",
  ui_story_5028_50281401_116_dialog_content = "No puedes imponer tu voluntad a las maravillosas bestias.",
  ui_story_5028_50281401_117_dialog_content = "¡Yo no soy un niño!",
  ui_story_5028_50281401_118_dialog_content = "¡Lo!",
  ui_story_5028_50281401_119_dialog_content = "Aquí...",
  ui_story_5028_50281401_120_dialog_content = "El poder del Búho Lutumi. Te las arreglaste para... guau.",
  ui_story_5028_50281401_121_dialog_content = "¡Lo! ¡Lo!",
  ui_story_5028_50281401_122_dialog_content = "¡Ay! ¿Te vas tan pronto?",
  ui_story_5028_50281401_123_dialog_content = "Fia no va a estar feliz cuando se despierte después de despedirse de tantos compañeros.",
  ui_story_5028_50281401_124_dialog_content = "Asegúrate de consolarla. Estas cosas pueden ser difíciles y molestas.",
  ui_story_5028_50281401_125_dialog_content = "No tengo mucha experiencia con niños. ¿Puedo importunar a mi estimado aprendiz para que se encargue de esto?",
  ui_story_5028_50281401_126_dialog_content = "Oh...",
  ui_story_5028_50281401_127_dialog_content = "¡Asegúrense de cuidarse bien unos a otros!",
  ui_story_5028_50281401_128_dialog_content = "Y manténgase alejado de las personas que parecen malas noticias.",
  ui_story_5028_50281401_129_dialog_content = "¡Lo!",
  ui_story_5028_50281401_130_dialog_content = "Bueno, ese es el final de la historia.",
  ui_story_5028_50281401_131_dialog_content = "Los Kyllo y sus hermanos habitan en ese mismo bosque incluso hoy.",
  ui_story_5028_50281401_132_dialog_content = "La niña llamada Fia creció y se convirtió en una renombrada extrozoóloga.",
  ui_story_5028_50281401_133_dialog_content = "Un buen final para todos.",
  ui_story_5028_50281401_134_dialog_content = "¿Y luego qué pasó?",
  ui_story_5028_50281401_135_dialog_content = "En todo caso, Vice, déjame descansar un poco primero, ¿quieres?",
  ui_story_5028_50281401_136_dialog_content = "He estado leyendo \"Las aventuras del extrozoólogo\" durante 3 horas completas.",
  ui_story_5028_50281401_137_dialog_content = "Mi garganta se está poniendo ronca.",
  ui_story_5028_50281401_138_dialog_content = "Oh, lo siento. Será mejor que descanses entonces.",
  ui_story_5028_50281401_139_dialog_content = "¡Pero realmente me estoy metiendo en eso! No podemos terminar aquí.",
  ui_story_5028_50281401_140_dialog_content = "Realmente quiero saber qué pasó después.",
  ui_story_5028_50281401_141_dialog_content = "O simplemente puede preguntarle a la señora que escribió el libro, ella debe—",
  ui_story_5028_50281401_142_dialog_content = "¡¡¡PlayerName!!!",
  ui_story_5028_50281401_143_dialog_content = "¡Mira, ahí está!",
  ui_story_5028_50281401_144_dialog_content = "¡Quiero ir a buscar bestias maravillosas mañana junto al mar!",
  ui_story_5028_50281401_145_dialog_content = "Y como exótica, Caelestite, ¡no aceptaré un no por respuesta!",
  ui_story_5028_50281401_146_dialog_content = "Bien bien. Ya te lo dije unas cuantas veces, que no soy una bestia maravillosa...",
  ui_story_5028_50281401_147_dialog_content = "¿Lo niegas? Qué vergüenza. Un poco tarde para eso ahora.",
  ui_story_5028_50281401_148_dialog_content = "Y, como su \"maestro extrozoólogo\", ¡no puedo dejar que huya!",
  ui_story_5028_50281401_149_dialog_content = "Realmente quieres dar un paseo en Soroz, ¿verdad?",
  ui_story_5028_50281401_150_dialog_content = "¡Y parece que Drakolion también está llegando!",
  ui_story_5028_50281401_151_dialog_content = "¡Tienes que pensar en una manera de devolverlo a donde debe ir!",
  ui_story_5028_50281401_152_dialog_content = "¡Confía en mí, Soroz no aceptará ninguna solicitud de asociación!",
  ui_story_5028_50281401_153_dialog_content = "¿No dije eso? Drakolion volverá después de la temporada de apareamiento.",
  ui_story_5028_50281401_154_dialog_content = "El respeto por las bestias maravillosas, sus hábitos y esperanzas, es fundamental para cualquier extrozoólogo que se precie.",
  ui_story_5028_50281401_155_dialog_content = "No voy a obligarlo a volver, ¡eso es seguro!",
  ui_story_5028_50281401_156_dialog_content = "Bien dicho, esta vez.",
  ui_story_5028_50281401_157_dialog_content = "¡Dios sabe cuánto tiempo llorarías si Kyllo no regresara!",
  ui_story_5028_50281401_158_dialog_content = "¿Perdóname?",
  ui_story_5028_50281401_159_dialog_content = "¡No recuerdo eso!",
  ui_story_5028_50281401_160_dialog_content = "¡Vamos! ¡Admitelo!",
  ui_story_5028_50281401_161_dialog_content = "¡Oye!",
  ui_story_5028_50281401_162_dialog_content = "¡Kyllo, muérdelo!",
  ui_story_5028_50281401_163_dialog_content = "Lo-Oowoo!",
  ui_story_5028_50281401_164_dialog_content = "¡Grrr!",
  ui_story_5028_50281401_165_dialog_content = "¡Mi pierna!",
  ui_story_5028_50281401_166_dialog_content = "¡Ptui!",
  ui_story_5028_50281401_167_dialog_content = "No se puede ser demasiado directo con los niños, PlayerName.",
  ui_story_5028_50281401_168_dialog_content = "Vice, ¡ven y ayudame!",
  ui_story_5028_50281401_169_dialog_content = "¡Ayúdame a quitarme a Kyllo de la pierna!",
  ui_story_5028_50281401_170_dialog_content = "Bien bien. Liberar PlayerName, ¿OK?",
  ui_story_5028_50281401_171_dialog_content = "¡Lo!",
  ui_story_5028_50281401_172_dialog_content = "¡Eh! Los extrozoólogos tienen todo el poder, ¿no?",
  ui_story_5028_50281401_173_dialog_content = "Mi pierna... ¡Las marcas de mordedura de Kyllo están en ella!",
  ui_story_5028_50281401_174_dialog_content = "Esperar. El Kyllo se fue. Lo recuerdo claramente. ¿Cómo es que todavía está dando vueltas por Fia?",
  ui_story_5028_50281401_175_dialog_content = "Un experto en mi campo tiene un carisma tremendo del que poco sabes. Mi Kyllo finalmente regresó.",
  ui_story_5028_50281401_176_dialog_content = "¡Lo, lo, lo, lo, lo, lo, lo, lo, lo, lo, lo, lo, lo, lo!",
  ui_story_5028_50281401_177_dialog_content = "¿Vaya? ¿Kyllo está tratando de decirnos algo?",
  ui_story_5028_50281401_178_dialog_content = "¿Vaya? No entendí bien eso, Kyllo. ¿Qué estabas diciendo? ¿Podrías repetirte?",
  ui_story_5028_50281401_179_dialog_content = "Lo, lo, lo...",
  ui_story_5028_50281401_180_dialog_content = "\"¿Porque estaba preocupado por el bienestar de Fia?\"",
  ui_story_5028_50281401_181_dialog_content = "\"Pensé en todos los días que Fia estaría llorando en mi ausencia...\"",
  ui_story_5028_50281401_182_dialog_content = "\"Estaba tan preocupado por su salud que tuve que volver...\"",
  ui_story_5028_50281401_183_dialog_content = "¡¿Es eso así?!",
  ui_story_5028_50281401_184_dialog_content = "¡Lo! ¡Lo! ¡Lo!",
  ui_story_5028_50281401_185_dialog_content = "¡Ahhh! Kyllo!",
  ui_story_5028_50281401_186_dialog_content = "¡Para!",
  ui_story_5028_50281401_187_dialog_content = "... Y con eso debemos cerrar las cortinas de esta historia.",
  ui_story_5028_50281401_188_dialog_content = "... Teniendo en cuenta que no puede haber fin a las muchas aventuras de un verdadero extrozoólogo."
}
return config
